/*************************************************************************
Checks whether inverse is correct
Returns True on success.
*************************************************************************/
static ae_bool testmatinvunit_rmatrixcheckinverse(/* Real    */ const ae_matrix* a,
     /* Real    */ const ae_matrix* inva,
     ae_int_t n,
     double threshold,
     const matinvreport* rep,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t j;
    double v;
    ae_bool result;


    result = ae_true;
    if( rep->terminationtype<=0 )
    {
        result = ae_false;
    }
    else
    {
        result = result&&!(ae_fp_less(rep->r1,(double)100*ae_machineepsilon)||ae_fp_greater(rep->r1,(double)1+(double)1000*ae_machineepsilon));
        result = result&&!(ae_fp_less(rep->rinf,(double)100*ae_machineepsilon)||ae_fp_greater(rep->rinf,(double)1+(double)1000*ae_machineepsilon));
        for(i=0; i<=n-1; i++)
        {
            for(j=0; j<=n-1; j++)
            {
                v = ae_v_dotproduct(&a->ptr.pp_double[i][0], 1, &inva->ptr.pp_double[0][j], inva->stride, ae_v_len(0,n-1));
                if( i==j )
                {
                    v = v-(double)1;
                }
                result = result&&ae_fp_less_eq(ae_fabs(v, _state),threshold);
            }
        }
    }
    return result;
}


/*************************************************************************
Checks whether inverse is correct
Returns True on success.
*************************************************************************/
static ae_bool testmatinvunit_spdmatrixcheckinverse(/* Real    */ const ae_matrix* _a,
     /* Real    */ const ae_matrix* _inva,
     ae_bool isupper,
     ae_int_t n,
     double threshold,
     const matinvreport* rep,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_matrix a;
    ae_matrix inva;
    ae_int_t i;
    ae_int_t j;
    double v;
    ae_bool result;

    ae_frame_make(_state, &_frame_block);
    memset(&a, 0, sizeof(a));
    memset(&inva, 0, sizeof(inva));
    ae_matrix_init_copy(&a, _a, _state, ae_true);
    ae_matrix_init_copy(&inva, _inva, _state, ae_true);

    for(i=0; i<=n-2; i++)
    {
        if( isupper )
        {
            ae_v_move(&a.ptr.pp_double[i+1][i], a.stride, &a.ptr.pp_double[i][i+1], 1, ae_v_len(i+1,n-1));
            ae_v_move(&inva.ptr.pp_double[i+1][i], inva.stride, &inva.ptr.pp_double[i][i+1], 1, ae_v_len(i+1,n-1));
        }
        else
        {
            ae_v_move(&a.ptr.pp_double[i][i+1], 1, &a.ptr.pp_double[i+1][i], a.stride, ae_v_len(i+1,n-1));
            ae_v_move(&inva.ptr.pp_double[i][i+1], 1, &inva.ptr.pp_double[i+1][i], inva.stride, ae_v_len(i+1,n-1));
        }
    }
    result = ae_true;
    if( rep->terminationtype<=0 )
    {
        result = ae_false;
    }
    else
    {
        result = result&&!(ae_fp_less(rep->r1,(double)100*ae_machineepsilon)||ae_fp_greater(rep->r1,(double)1+(double)1000*ae_machineepsilon));
        result = result&&!(ae_fp_less(rep->rinf,(double)100*ae_machineepsilon)||ae_fp_greater(rep->rinf,(double)1+(double)1000*ae_machineepsilon));
        for(i=0; i<=n-1; i++)
        {
            for(j=0; j<=n-1; j++)
            {
                v = ae_v_dotproduct(&a.ptr.pp_double[i][0], 1, &inva.ptr.pp_double[0][j], inva.stride, ae_v_len(0,n-1));
                if( i==j )
                {
                    v = v-(double)1;
                }
                result = result&&ae_fp_less_eq(ae_fabs(v, _state),threshold);
            }
        }
    }
    ae_frame_leave(_state);
    return result;
}


/*************************************************************************
Checks whether inverse is correct
Returns True on success.
*************************************************************************/
static ae_bool testmatinvunit_hpdmatrixcheckinverse(/* Complex */ const ae_matrix* _a,
     /* Complex */ const ae_matrix* _inva,
     ae_bool isupper,
     ae_int_t n,
     double threshold,
     const matinvreport* rep,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_matrix a;
    ae_matrix inva;
    ae_int_t i;
    ae_int_t j;
    ae_complex v;
    ae_bool result;

    ae_frame_make(_state, &_frame_block);
    memset(&a, 0, sizeof(a));
    memset(&inva, 0, sizeof(inva));
    ae_matrix_init_copy(&a, _a, _state, ae_true);
    ae_matrix_init_copy(&inva, _inva, _state, ae_true);

    for(i=0; i<=n-2; i++)
    {
        if( isupper )
        {
            ae_v_cmove(&a.ptr.pp_complex[i+1][i], a.stride, &a.ptr.pp_complex[i][i+1], 1, "Conj", ae_v_len(i+1,n-1));
            ae_v_cmove(&inva.ptr.pp_complex[i+1][i], inva.stride, &inva.ptr.pp_complex[i][i+1], 1, "Conj", ae_v_len(i+1,n-1));
        }
        else
        {
            ae_v_cmove(&a.ptr.pp_complex[i][i+1], 1, &a.ptr.pp_complex[i+1][i], a.stride, "Conj", ae_v_len(i+1,n-1));
            ae_v_cmove(&inva.ptr.pp_complex[i][i+1], 1, &inva.ptr.pp_complex[i+1][i], inva.stride, "Conj", ae_v_len(i+1,n-1));
        }
    }
    result = ae_true;
    if( rep->terminationtype<=0 )
    {
        result = ae_false;
    }
    else
    {
        result = result&&!(ae_fp_less(rep->r1,(double)100*ae_machineepsilon)||ae_fp_greater(rep->r1,(double)1+(double)1000*ae_machineepsilon));
        result = result&&!(ae_fp_less(rep->rinf,(double)100*ae_machineepsilon)||ae_fp_greater(rep->rinf,(double)1+(double)1000*ae_machineepsilon));
        for(i=0; i<=n-1; i++)
        {
            for(j=0; j<=n-1; j++)
            {
                v = ae_v_cdotproduct(&a.ptr.pp_complex[i][0], 1, "N", &inva.ptr.pp_complex[0][j], inva.stride, "N", ae_v_len(0,n-1));
                if( i==j )
                {
                    v = ae_c_sub_d(v,(double)(1));
                }
                result = result&&ae_fp_less_eq(ae_c_abs(v, _state),threshold);
            }
        }
    }
    ae_frame_leave(_state);
    return result;
}


/*************************************************************************
Checks whether inversion result indicate singular matrix
Returns True on success.
*************************************************************************/
static ae_bool testmatinvunit_rmatrixcheckinversesingular(/* Real    */ const ae_matrix* inva,
     ae_int_t n,
     double threshold,
     const matinvreport* rep,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t j;
    ae_bool result;


    result = ae_true;
    if( rep->terminationtype!=-3&&rep->terminationtype!=1 )
    {
        result = ae_false;
    }
    else
    {
        result = result&&!(ae_fp_less(rep->r1,(double)(0))||ae_fp_greater(rep->r1,(double)1000*ae_machineepsilon));
        result = result&&!(ae_fp_less(rep->rinf,(double)(0))||ae_fp_greater(rep->rinf,(double)1000*ae_machineepsilon));
        if( rep->terminationtype==-3 )
        {
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    result = result&&ae_fp_eq(inva->ptr.pp_double[i][j],(double)(0));
                }
            }
        }
    }
    return result;
}


