ae_bool testminnlc(ae_bool silent, ae_state *_state)
{
    ae_bool waserrors;
    ae_bool bcerr;
    ae_bool lcerr;
    ae_bool nlcerr;
    ae_bool othererr;
    ae_bool optguarderr;
    ae_bool bugs;
    ae_bool result;


    waserrors = ae_false;
    bcerr = ae_false;
    lcerr = ae_false;
    nlcerr = ae_false;
    othererr = ae_false;
    optguarderr = ae_false;
    bugs = ae_false;
    testminnlcunit_testbugs(&bugs, _state);
    testminnlcunit_testbc(&bcerr, _state);
    testminnlcunit_testlc(&lcerr, _state);
    testminnlcunit_testnlc(&nlcerr, _state);
    testminnlcunit_testother(&othererr, _state);
    testminnlcunit_testoptguard(&optguarderr, _state);
    
    /*
     * end
     */
    waserrors = ((((bcerr||lcerr)||nlcerr)||othererr)||bugs)||optguarderr;
    if( !silent )
    {
        printf("TESTING MINNLC OPTIMIZATION\n");
        printf("GENERIC TESTS:\n");
        printf("* box constrained                         ");
        if( bcerr )
        {
            printf("FAILED\n");
        }
        else
        {
            printf("OK\n");
        }
        printf("* linearly constrained                    ");
        if( lcerr )
        {
            printf("FAILED\n");
        }
        else
        {
            printf("OK\n");
        }
        printf("* nonlinearly constrained                 ");
        if( nlcerr )
        {
            printf("FAILED\n");
        }
        else
        {
            printf("OK\n");
        }
        printf("* other properties                        ");
        if( othererr )
        {
            printf("FAILED\n");
        }
        else
        {
            printf("OK\n");
        }
        printf("* optguard integrity monitor              ");
        if( optguarderr )
        {
            printf("FAILED\n");
        }
        else
        {
            printf("OK\n");
        }
        printf("* fixed bugs                              ");
        if( bugs )
        {
            printf("FAILED\n");
        }
        else
        {
            printf("OK\n");
        }
        if( waserrors )
        {
            printf("TEST FAILED\n");
        }
        else
        {
            printf("TEST PASSED\n");
        }
        printf("\n\n");
    }
    result = !waserrors;
    return result;
}


/*************************************************************************
This function tests bound constrained quadratic programming algorithm.

On failure sets error flag.
*************************************************************************/
static void testminnlcunit_testbc(ae_bool* wereerrors, ae_state *_state)
{
    ae_frame _frame_block;
    minnlcstate state;
    minnlcreport rep;
    optguardreport ogrep;
    ae_int_t n;
    ae_int_t pass;
    ae_int_t i;
    ae_int_t j;
    ae_int_t aulits;
    double tolx;
    double tolg;
    ae_int_t scaletype;
    double rho;
    ae_int_t solvertype;
    ae_matrix fulla;
    ae_vector b;
    ae_vector bndl;
    ae_vector bndu;
    ae_vector s;
    ae_vector x0;
    ae_vector x1;
    double gnorm;
    double g;
    ae_int_t prectype;
    hqrndstate rs;

    ae_frame_make(_state, &_frame_block);
    memset(&state, 0, sizeof(state));
    memset(&rep, 0, sizeof(rep));
    memset(&ogrep, 0, sizeof(ogrep));
    memset(&fulla, 0, sizeof(fulla));
    memset(&b, 0, sizeof(b));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&s, 0, sizeof(s));
    memset(&x0, 0, sizeof(x0));
    memset(&x1, 0, sizeof(x1));
    memset(&rs, 0, sizeof(rs));
    _minnlcstate_init(&state, _state, ae_true);
    _minnlcreport_init(&rep, _state, ae_true);
    _optguardreport_init(&ogrep, _state, ae_true);
    ae_matrix_init(&fulla, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&b, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&s, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x1, 0, DT_REAL, _state, ae_true);
    _hqrndstate_init(&rs, _state, ae_true);

    hqrndrandomize(&rs, _state);
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        
        /*
         * Convex test:
         * * N dimensions
         * * random number (0..N) of random boundary constraints
         * * positive-definite quadratic programming problem
         * * initial point is random (maybe infeasible!)
         * * random scale (unit or non-unit)
         */
        aulits = 10;
        rho = 200.0;
        tolx = 0.0005;
        tolg = 0.01;
        for(n=1; n<=10; n++)
        {
            for(pass=1; pass<=10; pass++)
            {
                for(prectype=0; prectype<=2; prectype++)
                {
                    
                    /*
                     * Generate well-conditioned problem with unit scale
                     */
                    spdmatrixrndcond(n, 1.0E2, &fulla, _state);
                    ae_vector_set_length(&b, n, _state);
                    ae_vector_set_length(&bndl, n, _state);
                    ae_vector_set_length(&bndu, n, _state);
                    ae_vector_set_length(&x0, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        b.ptr.p_double[i] = hqrndnormal(&rs, _state);
                        bndl.ptr.p_double[i] = _state->v_neginf;
                        bndu.ptr.p_double[i] = _state->v_posinf;
                        x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                        j = hqrnduniformi(&rs, 5, _state);
                        if( j==0 )
                        {
                            bndl.ptr.p_double[i] = (double)(0);
                        }
                        if( j==1 )
                        {
                            bndu.ptr.p_double[i] = (double)(0);
                        }
                        if( j==2 )
                        {
                            bndl.ptr.p_double[i] = hqrndnormal(&rs, _state);
                            bndu.ptr.p_double[i] = bndl.ptr.p_double[i];
                        }
                        if( j==3 )
                        {
                            bndl.ptr.p_double[i] = -0.1;
                            bndu.ptr.p_double[i] = 0.1;
                        }
                    }
                    
                    /*
                     * Apply scaling to quadratic/linear term, so problem becomes
                     * well-conditioned in the scaled coordinates.
                     */
                    scaletype = hqrnduniformi(&rs, 2, _state);
                    ae_vector_set_length(&s, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        if( scaletype==0 )
                        {
                            s.ptr.p_double[i] = (double)(1);
                        }
                        else
                        {
                            s.ptr.p_double[i] = ae_exp((double)5*hqrndnormal(&rs, _state), _state);
                        }
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        x0.ptr.p_double[i] = x0.ptr.p_double[i]*s.ptr.p_double[i];
                        bndl.ptr.p_double[i] = bndl.ptr.p_double[i]*s.ptr.p_double[i];
                        bndu.ptr.p_double[i] = bndu.ptr.p_double[i]*s.ptr.p_double[i];
                        b.ptr.p_double[i] = b.ptr.p_double[i]/s.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            fulla.ptr.pp_double[i][j] = fulla.ptr.pp_double[i][j]/(s.ptr.p_double[i]*s.ptr.p_double[j]);
                        }
                    }
                    
                    /*
                     * Solve problem
                     */
                    minnlccreate(n, &x0, &state, _state);
                    if( solvertype==0 )
                    {
                        minnlcsetalgoaul(&state, rho, aulits, _state);
                        if( prectype==1 )
                        {
                            minnlcsetprecexactlowrank(&state, 0, _state);
                        }
                        if( prectype==2 )
                        {
                            minnlcsetprecexactrobust(&state, 0, _state);
                        }
                    }
                    else
                    {
                        if( solvertype==1 )
                        {
                            minnlcsetalgoslp(&state, _state);
                        }
                        else
                        {
                            if( solvertype==2 )
                            {
                                minnlcsetalgosqp(&state, _state);
                            }
                            else
                            {
                                ae_assert(ae_false, "Assertion failed", _state);
                            }
                        }
                    }
                    if( scaletype!=0 )
                    {
                        minnlcsetscale(&state, &s, _state);
                    }
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                    }
                    minnlcsetbc(&state, &bndl, &bndu, _state);
                    minnlcsetcond(&state, 1.0E-7, 0, _state);
                    while(minnlciteration(&state, _state))
                    {
                        if( state.needfij )
                        {
                            state.fi.ptr.p_double[0] = (double)(0);
                            for(i=0; i<=n-1; i++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                                state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                                for(j=0; j<=n-1; j++)
                                {
                                    state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                    state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                }
                            }
                            continue;
                        }
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                    minnlcresults(&state, &x1, &rep, _state);
                    ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:240");
                    ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:241");
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardresults(&state, &ogrep, _state);
                        ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:245");
                    }
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    
                    /*
                     * Check constraint violation reports
                     */
                    ae_set_error_flag(wereerrors, ae_fp_greater(rep.bcerr,tolx), __FILE__, __LINE__, "testminnlcunit.ap:253");
                    ae_set_error_flag(wereerrors, rep.bcidx>=n, __FILE__, __LINE__, "testminnlcunit.ap:254");
                    ae_set_error_flag(wereerrors, ae_fp_greater(rep.lcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:255");
                    ae_set_error_flag(wereerrors, rep.lcidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:256");
                    
                    /*
                     * Check feasibility properties
                     */
                    for(i=0; i<=n-1; i++)
                    {
                        ae_set_error_flag(wereerrors, ae_isfinite(bndl.ptr.p_double[i], _state)&&ae_fp_less_eq(x1.ptr.p_double[i],bndl.ptr.p_double[i]-tolx*s.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:263");
                        ae_set_error_flag(wereerrors, ae_isfinite(bndu.ptr.p_double[i], _state)&&ae_fp_greater_eq(x1.ptr.p_double[i],bndu.ptr.p_double[i]+tolx*s.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:264");
                    }
                    
                    /*
                     * Test - calculate scaled constrained gradient at solution,
                     * check its norm.
                     */
                    gnorm = 0.0;
                    for(i=0; i<=n-1; i++)
                    {
                        g = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            g = g+fulla.ptr.pp_double[i][j]*x1.ptr.p_double[j];
                        }
                        g = s.ptr.p_double[i]*g;
                        if( (ae_isfinite(bndl.ptr.p_double[i], _state)&&ae_fp_less(ae_fabs(x1.ptr.p_double[i]-bndl.ptr.p_double[i], _state),tolx*s.ptr.p_double[i]))&&ae_fp_greater(g,(double)(0)) )
                        {
                            g = (double)(0);
                        }
                        if( (ae_isfinite(bndu.ptr.p_double[i], _state)&&ae_fp_less(ae_fabs(x1.ptr.p_double[i]-bndu.ptr.p_double[i], _state),tolx*s.ptr.p_double[i]))&&ae_fp_less(g,(double)(0)) )
                        {
                            g = (double)(0);
                        }
                        gnorm = gnorm+ae_sqr(g, _state);
                    }
                    gnorm = ae_sqrt(gnorm, _state);
                    ae_set_error_flag(wereerrors, ae_fp_greater(gnorm,tolg), __FILE__, __LINE__, "testminnlcunit.ap:286");
                }
            }
        }
        
        /*
         * Non-convex test:
         * * N dimensions, N>=2
         * * box constraints, x[i] in [-1,+1]
         * * A is symmetric indefinite with condition number 50.0
         * * random B with normal entries
         * * initial point is random, feasible
         * * scale is always unit
         *
         * We check that constrained problem can be successfully solved.
         * We do not check ability to detect unboundedness of unconstrained
         * problem because there is such functionality in MinNLC.
         */
        aulits = 50;
        rho = 200.0;
        tolx = 0.0005;
        tolg = 0.01;
        for(n=2; n<=10; n++)
        {
            for(pass=1; pass<=10; pass++)
            {
                for(prectype=0; prectype<=2; prectype++)
                {
                    
                    /*
                     * Generate problem
                     */
                    for(i=0; i<=n-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            fulla.ptr.pp_double[i][j] = 0.0;
                        }
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        fulla.ptr.pp_double[i][i] = (double)(-1)-hqrnduniformr(&rs, _state);
                    }
                    ae_vector_set_length(&b, n, _state);
                    ae_vector_set_length(&bndl, n, _state);
                    ae_vector_set_length(&bndu, n, _state);
                    ae_vector_set_length(&x0, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        b.ptr.p_double[i] = 0.05*hqrndnormal(&rs, _state);
                        bndl.ptr.p_double[i] = (double)(-1);
                        bndu.ptr.p_double[i] = (double)(1);
                        x0.ptr.p_double[i] = (double)2*hqrnduniformr(&rs, _state)-(double)1;
                    }
                    
                    /*
                     * Solve problem:
                     * * without constraints we expect failure
                     * * with constraints algorithm must succeed
                     */
                    minnlccreate(n, &x0, &state, _state);
                    if( solvertype==0 )
                    {
                        minnlcsetalgoaul(&state, rho, aulits, _state);
                        if( prectype==0 )
                        {
                            minnlcsetprecinexact(&state, _state);
                        }
                        if( prectype==1 )
                        {
                            minnlcsetprecexactlowrank(&state, 0, _state);
                        }
                        if( prectype==2 )
                        {
                            minnlcsetprecexactrobust(&state, 0, _state);
                        }
                    }
                    else
                    {
                        if( solvertype==1 )
                        {
                            minnlcsetalgoslp(&state, _state);
                        }
                        else
                        {
                            if( solvertype==2 )
                            {
                                minnlcsetalgosqp(&state, _state);
                            }
                            else
                            {
                                ae_assert(ae_false, "Assertion failed", _state);
                            }
                        }
                    }
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                    }
                    minnlcsetbc(&state, &bndl, &bndu, _state);
                    minnlcsetcond(&state, 1.0E-7, 0, _state);
                    while(minnlciteration(&state, _state))
                    {
                        if( state.needfij )
                        {
                            state.fi.ptr.p_double[0] = (double)(0);
                            for(i=0; i<=n-1; i++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                                state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                                for(j=0; j<=n-1; j++)
                                {
                                    state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                    state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                }
                            }
                            continue;
                        }
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                    minnlcresults(&state, &x1, &rep, _state);
                    ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:378");
                    ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:379");
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardresults(&state, &ogrep, _state);
                        ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:383");
                    }
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    
                    /*
                     * Check feasibility properties
                     */
                    for(i=0; i<=n-1; i++)
                    {
                        ae_set_error_flag(wereerrors, ae_isfinite(bndl.ptr.p_double[i], _state)&&ae_fp_less_eq(x1.ptr.p_double[i],bndl.ptr.p_double[i]-tolx), __FILE__, __LINE__, "testminnlcunit.ap:393");
                        ae_set_error_flag(wereerrors, ae_isfinite(bndu.ptr.p_double[i], _state)&&ae_fp_greater_eq(x1.ptr.p_double[i],bndu.ptr.p_double[i]+tolx), __FILE__, __LINE__, "testminnlcunit.ap:394");
                    }
                    
                    /*
                     * Test - calculate scaled constrained gradient at solution,
                     * check its norm.
                     */
                    gnorm = 0.0;
                    for(i=0; i<=n-1; i++)
                    {
                        g = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            g = g+fulla.ptr.pp_double[i][j]*x1.ptr.p_double[j];
                        }
                        if( (ae_isfinite(bndl.ptr.p_double[i], _state)&&ae_fp_less(ae_fabs(x1.ptr.p_double[i]-bndl.ptr.p_double[i], _state),tolx))&&ae_fp_greater(g,(double)(0)) )
                        {
                            g = (double)(0);
                        }
                        if( (ae_isfinite(bndu.ptr.p_double[i], _state)&&ae_fp_less(ae_fabs(x1.ptr.p_double[i]-bndu.ptr.p_double[i], _state),tolx))&&ae_fp_less(g,(double)(0)) )
                        {
                            g = (double)(0);
                        }
                        gnorm = gnorm+ae_sqr(g, _state);
                    }
                    gnorm = ae_sqrt(gnorm, _state);
                    ae_set_error_flag(wereerrors, ae_fp_greater(gnorm,tolg), __FILE__, __LINE__, "testminnlcunit.ap:415");
                }
            }
        }
    }
    ae_frame_leave(_state);
}


/*************************************************************************
This function tests linearly constrained quadratic programming algorithm.

Sets error flag on failure.
*************************************************************************/
static void testminnlcunit_testlc(ae_bool* wereerrors, ae_state *_state)
{
    ae_frame _frame_block;
    ae_int_t n;
    ae_int_t k;
    ae_int_t i;
    ae_int_t j;
    ae_int_t pass;
    ae_matrix q;
    ae_matrix fulla;
    double v;
    double vv;
    ae_vector tmp;
    ae_vector bl;
    ae_vector bu;
    ae_vector b;
    ae_vector xs0;
    ae_vector xstart;
    ae_vector x;
    ae_vector x0;
    ae_vector x1;
    ae_vector x2;
    ae_vector xm;
    ae_vector s;
    ae_vector g;
    ae_vector bndl;
    ae_vector bndu;
    ae_matrix a;
    ae_matrix c;
    ae_matrix ce;
    ae_vector ct;
    ae_vector nonnegative;
    double tolx;
    double tolg;
    double tolf;
    ae_int_t aulits;
    double rho;
    minnlcstate state;
    minnlcreport rep;
    optguardreport ogrep;
    ae_int_t scaletype;
    double f0;
    double f1;
    double tolconstr;
    ae_int_t bscale;
    ae_int_t akind;
    ae_int_t ccnt;
    ae_int_t shiftkind;
    ae_int_t prectype;
    ae_int_t solvertype;
    double gnrm2;
    hqrndstate rs;
    snnlssolver nnls;

    ae_frame_make(_state, &_frame_block);
    memset(&q, 0, sizeof(q));
    memset(&fulla, 0, sizeof(fulla));
    memset(&tmp, 0, sizeof(tmp));
    memset(&bl, 0, sizeof(bl));
    memset(&bu, 0, sizeof(bu));
    memset(&b, 0, sizeof(b));
    memset(&xs0, 0, sizeof(xs0));
    memset(&xstart, 0, sizeof(xstart));
    memset(&x, 0, sizeof(x));
    memset(&x0, 0, sizeof(x0));
    memset(&x1, 0, sizeof(x1));
    memset(&x2, 0, sizeof(x2));
    memset(&xm, 0, sizeof(xm));
    memset(&s, 0, sizeof(s));
    memset(&g, 0, sizeof(g));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&a, 0, sizeof(a));
    memset(&c, 0, sizeof(c));
    memset(&ce, 0, sizeof(ce));
    memset(&ct, 0, sizeof(ct));
    memset(&nonnegative, 0, sizeof(nonnegative));
    memset(&state, 0, sizeof(state));
    memset(&rep, 0, sizeof(rep));
    memset(&ogrep, 0, sizeof(ogrep));
    memset(&rs, 0, sizeof(rs));
    memset(&nnls, 0, sizeof(nnls));
    ae_matrix_init(&q, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&fulla, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&tmp, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&b, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xs0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xstart, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x1, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x2, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xm, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&s, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&g, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&a, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&c, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&ce, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&ct, 0, DT_INT, _state, ae_true);
    ae_vector_init(&nonnegative, 0, DT_BOOL, _state, ae_true);
    _minnlcstate_init(&state, _state, ae_true);
    _minnlcreport_init(&rep, _state, ae_true);
    _optguardreport_init(&ogrep, _state, ae_true);
    _hqrndstate_init(&rs, _state, ae_true);
    _snnlssolver_init(&nnls, _state, ae_true);

    hqrndrandomize(&rs, _state);
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        
        /*
         * First test:
         * * K<N equality constraints Q*x = Q*x0, where Q is random
         *   orthogonal K*N matrix, x0 is some random vector
         * * quadratic programming problem with identity quadratic term A and
         *   linear term equal to xm*A, where xm is some random vector such
         *   that Q*xm=0. It is always possible to find such xm, because K<N
         *   Thus, optimization problem has form 0.5*x'*I*x-xm'*x.
         * * exact solution must be equal to x0
         *
         * NOTE: this test is important because it is the only linearly constrained one
         *       which uses non-unit scaling!
         */
        rho = 200.0;
        tolx = 0.0005;
        tolf = 0.0001;
        aulits = 50;
        for(n=2; n<=6; n++)
        {
            for(k=1; k<=n-1; k++)
            {
                for(prectype=-1; prectype<=2; prectype++)
                {
                    
                    /*
                     * Generate problem: A, b, CMatrix, x0, XStart
                     */
                    rmatrixrndorthogonal(n, &q, _state);
                    ae_vector_set_length(&b, n, _state);
                    ae_vector_set_length(&x0, n, _state);
                    ae_vector_set_length(&xm, n, _state);
                    ae_vector_set_length(&xstart, n, _state);
                    ae_matrix_set_length(&c, k, n+1, _state);
                    ae_vector_set_length(&ct, k, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        x0.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                        xm.ptr.p_double[i] = x0.ptr.p_double[i];
                        xstart.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                    }
                    for(i=0; i<=k-1; i++)
                    {
                        ae_v_move(&c.ptr.pp_double[i][0], 1, &q.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                        v = ae_v_dotproduct(&q.ptr.pp_double[i][0], 1, &x0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                        c.ptr.pp_double[i][n] = v;
                        ct.ptr.p_int[i] = 0;
                        v = (double)2*ae_randomreal(_state)-(double)1;
                        ae_v_addd(&xm.ptr.p_double[0], 1, &q.ptr.pp_double[i][0], 1, ae_v_len(0,n-1), v);
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        b.ptr.p_double[i] = -xm.ptr.p_double[i];
                    }
                    
                    /*
                     * Apply scaling to linear term and known solution,
                     * so problem becomes well-conditioned in the scaled coordinates.
                     */
                    scaletype = hqrnduniformi(&rs, 2, _state);
                    ae_vector_set_length(&s, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        if( scaletype==0 )
                        {
                            s.ptr.p_double[i] = (double)(1);
                        }
                        else
                        {
                            s.ptr.p_double[i] = ae_exp((double)5*hqrndnormal(&rs, _state), _state);
                        }
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        x0.ptr.p_double[i] = x0.ptr.p_double[i]*s.ptr.p_double[i];
                        xstart.ptr.p_double[i] = xstart.ptr.p_double[i]*s.ptr.p_double[i];
                        b.ptr.p_double[i] = b.ptr.p_double[i]/s.ptr.p_double[i];
                    }
                    for(i=0; i<=k-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            c.ptr.pp_double[i][j] = c.ptr.pp_double[i][j]/s.ptr.p_double[j];
                        }
                    }
                    
                    /*
                     * Create optimizer, solve
                     */
                    minnlccreate(n, &xstart, &state, _state);
                    minnlcsetscale(&state, &s, _state);
                    minnlcsetcond(&state, 1.0E-7, 0, _state);
                    minnlcsetlc(&state, &c, &ct, k, _state);
                    if( solvertype==0 )
                    {
                        minnlcsetalgoaul(&state, rho, aulits, _state);
                        if( prectype==0 )
                        {
                            minnlcsetprecinexact(&state, _state);
                        }
                        if( prectype==1 )
                        {
                            minnlcsetprecexactlowrank(&state, 0, _state);
                        }
                        if( prectype==2 )
                        {
                            minnlcsetprecexactrobust(&state, 0, _state);
                        }
                    }
                    else
                    {
                        if( solvertype==1 )
                        {
                            minnlcsetalgoslp(&state, _state);
                        }
                        else
                        {
                            if( solvertype==2 )
                            {
                                minnlcsetalgosqp(&state, _state);
                            }
                            else
                            {
                                ae_assert(ae_false, "Assertion failed", _state);
                            }
                        }
                    }
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                    }
                    while(minnlciteration(&state, _state))
                    {
                        if( state.needfij )
                        {
                            state.fi.ptr.p_double[0] = (double)(0);
                            for(i=0; i<=n-1; i++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i]+0.5*ae_sqr(state.x.ptr.p_double[i], _state)/ae_sqr(s.ptr.p_double[i], _state);
                                state.j.ptr.pp_double[0][i] = b.ptr.p_double[i]+state.x.ptr.p_double[i]/ae_sqr(s.ptr.p_double[i], _state);
                            }
                            continue;
                        }
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                    minnlcresults(&state, &x1, &rep, _state);
                    ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:580");
                    ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:581");
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardresults(&state, &ogrep, _state);
                        ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:585");
                    }
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    
                    /*
                     * Check constraint violation reports
                     */
                    ae_set_error_flag(wereerrors, ae_fp_greater(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:593");
                    ae_set_error_flag(wereerrors, rep.bcidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:594");
                    ae_set_error_flag(wereerrors, ae_fp_greater(rep.lcerr,tolx), __FILE__, __LINE__, "testminnlcunit.ap:595");
                    ae_set_error_flag(wereerrors, rep.lcidx>=n, __FILE__, __LINE__, "testminnlcunit.ap:596");
                    
                    /*
                     * Compare with analytic solution
                     */
                    f0 = (double)(0);
                    f1 = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        f0 = f0+b.ptr.p_double[i]*x0.ptr.p_double[i]+0.5*ae_sqr(x0.ptr.p_double[i]/s.ptr.p_double[i], _state);
                        f1 = f1+b.ptr.p_double[i]*x1.ptr.p_double[i]+0.5*ae_sqr(x1.ptr.p_double[i]/s.ptr.p_double[i], _state);
                    }
                    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(f1-f0, _state),tolf), __FILE__, __LINE__, "testminnlcunit.ap:608");
                }
            }
        }
        
        /*
         * Inequality constrained problem:
         * * N*N diagonal A
         * * one inequality constraint q'*x>=0, where q is random unit vector
         * * optimization problem has form 0.5*x'*A*x-(x1*A)*x,
         *   where x1 is some random vector
         * * either:
         *   a) x1 is feasible => we must stop at x1
         *   b) x1 is infeasible => we must stop at the boundary q'*x=0 and
         *      projection of gradient onto q*x=0 must be zero
         *
         * NOTE: we make several passes because some specific kind of errors is rarely
         *       caught by this test, so we need several repetitions.
         */
        rho = 200.0;
        tolx = 0.0005;
        tolg = 0.01;
        aulits = 50;
        for(n=2; n<=6; n++)
        {
            for(pass=0; pass<=4; pass++)
            {
                
                /*
                 * Generate problem: A, b, CMatrix, x0, XStart
                 */
                spdmatrixrndcond(n, 1.0E2, &fulla, _state);
                ae_vector_set_length(&b, n, _state);
                ae_vector_set_length(&xm, n, _state);
                ae_vector_set_length(&xstart, n, _state);
                ae_matrix_set_length(&c, 1, n+1, _state);
                ae_vector_set_length(&ct, 1, _state);
                for(i=0; i<=n-1; i++)
                {
                    xm.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                    xstart.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                }
                do
                {
                    v = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        c.ptr.pp_double[0][i] = (double)2*ae_randomreal(_state)-(double)1;
                        v = v+ae_sqr(c.ptr.pp_double[0][i], _state);
                    }
                    v = ae_sqrt(v, _state);
                }
                while(ae_fp_eq(v,(double)(0)));
                for(i=0; i<=n-1; i++)
                {
                    c.ptr.pp_double[0][i] = c.ptr.pp_double[0][i]/v;
                }
                c.ptr.pp_double[0][n] = (double)(0);
                ct.ptr.p_int[0] = 1;
                for(i=0; i<=n-1; i++)
                {
                    v = ae_v_dotproduct(&fulla.ptr.pp_double[i][0], 1, &xm.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    b.ptr.p_double[i] = -v;
                }
                
                /*
                 * Apply scaling to linear term and known solution,
                 * so problem becomes well-conditioned in the scaled coordinates.
                 */
                scaletype = hqrnduniformi(&rs, 2, _state);
                ae_vector_set_length(&s, n, _state);
                for(i=0; i<=n-1; i++)
                {
                    if( scaletype==0 )
                    {
                        s.ptr.p_double[i] = (double)(1);
                    }
                    else
                    {
                        s.ptr.p_double[i] = ae_exp(hqrndnormal(&rs, _state), _state);
                    }
                }
                for(i=0; i<=n-1; i++)
                {
                    xm.ptr.p_double[i] = xm.ptr.p_double[i]*s.ptr.p_double[i];
                    xstart.ptr.p_double[i] = xstart.ptr.p_double[i]*s.ptr.p_double[i];
                    b.ptr.p_double[i] = b.ptr.p_double[i]/s.ptr.p_double[i];
                    for(j=0; j<=n-1; j++)
                    {
                        fulla.ptr.pp_double[i][j] = fulla.ptr.pp_double[i][j]/(s.ptr.p_double[i]*s.ptr.p_double[j]);
                    }
                }
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[0][j] = c.ptr.pp_double[0][j]/s.ptr.p_double[j];
                }
                
                /*
                 * Create optimizer, solve
                 */
                minnlccreate(n, &xstart, &state, _state);
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, rho, aulits, _state);
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                minnlcsetlc(&state, &c, &ct, 1, _state);
                minnlcsetscale(&state, &s, _state);
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                }
                while(minnlciteration(&state, _state))
                {
                    if( state.needfij )
                    {
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                            state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                            for(j=0; j<=n-1; j++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            }
                        }
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                minnlcresults(&state, &x1, &rep, _state);
                ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:730");
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:731");
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardresults(&state, &ogrep, _state);
                    ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:735");
                }
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                
                /*
                 * Check constraint violation reports
                 */
                ae_set_error_flag(wereerrors, ae_fp_greater(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:743");
                ae_set_error_flag(wereerrors, rep.bcidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:744");
                ae_set_error_flag(wereerrors, ae_fp_greater(rep.lcerr,tolx), __FILE__, __LINE__, "testminnlcunit.ap:745");
                ae_set_error_flag(wereerrors, rep.lcidx>=n, __FILE__, __LINE__, "testminnlcunit.ap:746");
                
                /*
                 * Test solution
                 */
                ae_vector_set_length(&g, n, _state);
                ae_v_move(&g.ptr.p_double[0], 1, &b.ptr.p_double[0], 1, ae_v_len(0,n-1));
                for(i=0; i<=n-1; i++)
                {
                    v = ae_v_dotproduct(&fulla.ptr.pp_double[i][0], 1, &x1.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    g.ptr.p_double[i] = g.ptr.p_double[i]+v;
                }
                v = ae_v_dotproduct(&x1.ptr.p_double[0], 1, &c.ptr.pp_double[0][0], 1, ae_v_len(0,n-1));
                ae_set_error_flag(wereerrors, ae_fp_less(v,-tolx), __FILE__, __LINE__, "testminnlcunit.ap:759");
                if( ae_fp_less(v,tolx) )
                {
                    
                    /*
                     * Point at the boundary, project gradient into
                     * equality-constrained subspace.
                     */
                    v = 0.0;
                    vv = 0.0;
                    for(i=0; i<=n-1; i++)
                    {
                        v = v+g.ptr.p_double[i]*c.ptr.pp_double[0][i];
                        vv = vv+c.ptr.pp_double[0][i]*c.ptr.pp_double[0][i];
                    }
                    v = v/vv;
                    ae_v_subd(&g.ptr.p_double[0], 1, &c.ptr.pp_double[0][0], 1, ae_v_len(0,n-1), v);
                }
                v = 0.0;
                for(i=0; i<=n-1; i++)
                {
                    v = v+ae_sqr(g.ptr.p_double[i]*s.ptr.p_double[i], _state);
                }
                ae_set_error_flag(wereerrors, ae_fp_greater(ae_sqrt(v, _state),tolg), __FILE__, __LINE__, "testminnlcunit.ap:779");
            }
        }
        
        /*
         * Equality-constrained test:
         * * N*N SPD A
         * * K<N equality constraints Q*x = Q*x0, where Q is random
         *   orthogonal K*N matrix, x0 is some random vector
         * * optimization problem has form 0.5*x'*A*x-(xm*A)*x,
         *   where xm is some random vector
         * * we check feasibility properties of the solution
         * * we do not know analytic form of the exact solution,
         *   but we know that projection of gradient into equality constrained
         *   subspace must be zero at the solution
         */
        rho = 200.0;
        tolx = 0.0005;
        tolg = 0.01;
        aulits = 50;
        for(n=2; n<=6; n++)
        {
            for(k=1; k<=n-1; k++)
            {
                
                /*
                 * Generate problem: A, b, CMatrix, x0, XStart
                 */
                rmatrixrndorthogonal(n, &q, _state);
                spdmatrixrndcond(n, 1.0E2, &fulla, _state);
                ae_vector_set_length(&b, n, _state);
                ae_vector_set_length(&x0, n, _state);
                ae_vector_set_length(&xm, n, _state);
                ae_vector_set_length(&xstart, n, _state);
                ae_matrix_set_length(&c, k, n+1, _state);
                ae_vector_set_length(&ct, k, _state);
                for(i=0; i<=n-1; i++)
                {
                    x0.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                    xm.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                    xstart.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                }
                for(i=0; i<=k-1; i++)
                {
                    ae_v_move(&c.ptr.pp_double[i][0], 1, &q.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                    v = ae_v_dotproduct(&q.ptr.pp_double[i][0], 1, &x0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    c.ptr.pp_double[i][n] = v;
                    ct.ptr.p_int[i] = 0;
                }
                for(i=0; i<=n-1; i++)
                {
                    v = ae_v_dotproduct(&fulla.ptr.pp_double[i][0], 1, &xm.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    b.ptr.p_double[i] = -v;
                }
                
                /*
                 * Create optimizer, solve
                 */
                minnlccreate(n, &xstart, &state, _state);
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, rho, aulits, _state);
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                minnlcsetcond(&state, 1.0E-7, 0, _state);
                minnlcsetlc(&state, &c, &ct, k, _state);
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                }
                while(minnlciteration(&state, _state))
                {
                    if( state.needfij )
                    {
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                            state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                            for(j=0; j<=n-1; j++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            }
                        }
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                minnlcresults(&state, &x1, &rep, _state);
                ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:874");
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:875");
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardresults(&state, &ogrep, _state);
                    ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:879");
                }
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                
                /*
                 * Check constraint violation reports
                 */
                ae_set_error_flag(wereerrors, ae_fp_greater(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:887");
                ae_set_error_flag(wereerrors, rep.bcidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:888");
                ae_set_error_flag(wereerrors, ae_fp_greater(rep.lcerr,tolx), __FILE__, __LINE__, "testminnlcunit.ap:889");
                ae_set_error_flag(wereerrors, rep.lcidx>=n, __FILE__, __LINE__, "testminnlcunit.ap:890");
                
                /*
                 * Check feasibility properties and gradient projection
                 */
                for(i=0; i<=k-1; i++)
                {
                    v = ae_v_dotproduct(&x1.ptr.p_double[0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(v-c.ptr.pp_double[i][n], _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:898");
                }
                ae_vector_set_length(&g, n, _state);
                ae_v_move(&g.ptr.p_double[0], 1, &b.ptr.p_double[0], 1, ae_v_len(0,n-1));
                for(i=0; i<=n-1; i++)
                {
                    v = ae_v_dotproduct(&fulla.ptr.pp_double[i][0], 1, &x1.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    g.ptr.p_double[i] = g.ptr.p_double[i]+v;
                }
                for(i=0; i<=k-1; i++)
                {
                    v = ae_v_dotproduct(&g.ptr.p_double[0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                    ae_v_subd(&g.ptr.p_double[0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1), v);
                }
                v = ae_v_dotproduct(&g.ptr.p_double[0], 1, &g.ptr.p_double[0], 1, ae_v_len(0,n-1));
                ae_set_error_flag(wereerrors, ae_fp_greater(ae_sqrt(v, _state),tolg), __FILE__, __LINE__, "testminnlcunit.ap:913");
            }
        }
        
        /*
         * Boundary constraints vs linear ones:
         * * N*N SPD A
         * * optimization problem has form 0.5*x'*A*x-(xm*A)*x,
         *   where xm is some random vector from [-1,+1]
         * * K=2*N constraints of the form ai<=x[i] or x[i]<=b[i],
         *   with ai in [-1.0,-0.1], bi in [+0.1,+1.0]
         * * initial point xstart is from [-1,+2]
         * * we solve two related QP problems:
         *   a) one with constraints posed as boundary ones
         *   b) another one with same constraints posed as general linear ones
         * both problems must have same solution.
         * Here we test that boundary constrained and linear inequality constrained
         * solvers give same results.
         */
        rho = 200.0;
        tolx = 0.0005;
        tolf = 0.00001;
        aulits = 50;
        for(n=1; n<=6; n++)
        {
            
            /*
             * Generate problem: A, b, x0, XStart, C, CT
             */
            spdmatrixrndcond(n, 1.0E2, &fulla, _state);
            ae_vector_set_length(&b, n, _state);
            ae_vector_set_length(&xm, n, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_matrix_set_length(&c, 2*n, n+1, _state);
            ae_vector_set_length(&ct, 2*n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            for(i=0; i<=n-1; i++)
            {
                xm.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                x0.ptr.p_double[i] = (double)3*ae_randomreal(_state)-(double)1;
                bndl.ptr.p_double[i] = -(0.1+0.9*ae_randomreal(_state));
                bndu.ptr.p_double[i] = 0.1+0.9*ae_randomreal(_state);
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[2*i+0][j] = (double)(0);
                    c.ptr.pp_double[2*i+1][j] = (double)(0);
                }
                c.ptr.pp_double[2*i+0][i] = (double)(1);
                c.ptr.pp_double[2*i+0][n] = bndl.ptr.p_double[i];
                ct.ptr.p_int[2*i+0] = 1;
                c.ptr.pp_double[2*i+1][i] = (double)(1);
                c.ptr.pp_double[2*i+1][n] = bndu.ptr.p_double[i];
                ct.ptr.p_int[2*i+1] = -1;
            }
            for(i=0; i<=n-1; i++)
            {
                v = ae_v_dotproduct(&fulla.ptr.pp_double[i][0], 1, &xm.ptr.p_double[0], 1, ae_v_len(0,n-1));
                b.ptr.p_double[i] = -v;
            }
            
            /*
             * Solve linear inequality constrained problem
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, rho, aulits, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetlc(&state, &c, &ct, 2*n, _state);
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
            }
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1013");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1014");
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardresults(&state, &ogrep, _state);
                ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:1018");
            }
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Solve boundary constrained problem
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, rho, aulits, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x2, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x2, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1060");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1061");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Compare solutions
             */
            f0 = (double)(0);
            f1 = (double)(0);
            for(i=0; i<=n-1; i++)
            {
                f0 = f0+b.ptr.p_double[i]*x1.ptr.p_double[i];
                f1 = f1+b.ptr.p_double[i]*x2.ptr.p_double[i];
                for(j=0; j<=n-1; j++)
                {
                    f0 = f0+0.5*x1.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*x1.ptr.p_double[j];
                    f1 = f1+0.5*x2.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*x2.ptr.p_double[j];
                }
            }
            ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(f0-f1, _state),tolf), __FILE__, __LINE__, "testminnlcunit.ap:1080");
        }
        
        /*
         * Boundary and linear equality constrained QP problem with excessive
         * equality constraints:
         * * N*N SPD A with moderate condtion number (up to 100)
         * * boundary constraints 0<=x[i]<=1
         * * K=2*N equality constraints Q*x = Q*x0, where Q is random matrix,
         *   x0 is some random vector from the feasible hypercube (0.1<=x0[i]<=0.9)
         * * optimization problem has form 0.5*x'*A*x-b*x,
         *   where b is some random vector
         * * because constraints are excessive, the main problem is to find
         *   feasible point; the only existing feasible point is solution,
         *   so we have to check only feasibility
         */
        rho = 1000.0;
        tolx = 0.0005;
        aulits = 10;
        for(n=1; n<=6; n++)
        {
            
            /*
             * Generate problem: A, b, BndL, BndU, CMatrix, x0, xm, XStart
             */
            k = 2*n;
            spdmatrixrndcond(n, 1.0E2, &fulla, _state);
            ae_vector_set_length(&b, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&xm, n, _state);
            ae_vector_set_length(&xstart, n, _state);
            ae_matrix_set_length(&c, k, n+1, _state);
            ae_vector_set_length(&ct, k, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = 0.1+0.8*ae_randomreal(_state);
                xm.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                bndl.ptr.p_double[i] = 0.0;
                bndu.ptr.p_double[i] = 1.0;
                xstart.ptr.p_double[i] = (double)(ae_randominteger(2, _state));
            }
            for(i=0; i<=k-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = (double)2*ae_randomreal(_state)-(double)1;
                }
                v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &x0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                c.ptr.pp_double[i][n] = v;
                ct.ptr.p_int[i] = 0;
            }
            for(i=0; i<=n-1; i++)
            {
                b.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
            }
            
            /*
             * Create optimizer, solve
             */
            minnlccreate(n, &xstart, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, rho, aulits, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            minnlcsetlc(&state, &c, &ct, k, _state);
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
            }
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1177");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1178");
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardresults(&state, &ogrep, _state);
                ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:1182");
            }
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            for(i=0; i<=k-1; i++)
            {
                v = ae_v_dotproduct(&x1.ptr.p_double[0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(v-c.ptr.pp_double[i][n], _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:1189");
            }
        }
        
        /*
         * Boundary and linear equality/inequality constrained QP problem with
         * excessive constraints:
         * * N*N SPD A with moderate condtion number (up to 100)
         * * boundary constraints 0<=x[i]<=1
         * * K=2*N equality/inequality constraints:
         *   * N/2 equality ones q'*x = q'*xm for random vector q
         *   * the rest are inequality ones, feasible at xm (xm is an inner point for these constraints)
         *   where xm is some random vector from the feasible hypercube (0.1<=xm[i]<=0.9)
         * * optimization problem has form 0.5*x'*A*x-b*x,
         *   where b is some random vector
         * * because constraints are excessive, the main problem is to find
         *   feasible point; we do not check that algorithm found a solution,
         *   we just check that it found feasible point.
         *
         * NOTE: this problem is difficult one (estimates of Lagrange multipliers converge
         *       slowly), so we use relaxed tolerances - 0.010 for AUL solver
         */
        rho = 1000.0;
        aulits = 30;
        for(n=1; n<=6; n++)
        {
            
            /*
             * Generate problem: A, b, BndL, BndU, CMatrix, xm, x1, XStart
             */
            k = 2*n;
            spdmatrixrndcond(n, 1.0E2, &fulla, _state);
            ae_vector_set_length(&b, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_vector_set_length(&xm, n, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_matrix_set_length(&c, k, n+1, _state);
            ae_vector_set_length(&ct, k, _state);
            for(i=0; i<=n-1; i++)
            {
                xm.ptr.p_double[i] = 0.1+0.8*ae_randomreal(_state);
                bndl.ptr.p_double[i] = 0.0;
                bndu.ptr.p_double[i] = 1.0;
                x0.ptr.p_double[i] = (double)(ae_randominteger(2, _state));
                b.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
            }
            for(i=0; i<=n/2-1; i++)
            {
                v = (double)(0);
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                    v = v+c.ptr.pp_double[i][j]*xm.ptr.p_double[j];
                }
                c.ptr.pp_double[i][n] = v;
                ct.ptr.p_int[i] = 0;
            }
            for(i=n/2; i<=k-1; i++)
            {
                v = (double)(0);
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = hqrndnormal(&rs, _state)/ae_sqrt((double)(n), _state);
                    v = v+c.ptr.pp_double[i][j]*xm.ptr.p_double[j];
                }
                c.ptr.pp_double[i][n] = v;
                ct.ptr.p_int[i] = 2*hqrnduniformi(&rs, 2, _state)-1;
                if( ct.ptr.p_int[i]>0 )
                {
                    c.ptr.pp_double[i][n] = c.ptr.pp_double[i][n]-0.1;
                }
                else
                {
                    c.ptr.pp_double[i][n] = c.ptr.pp_double[i][n]+0.1;
                }
            }
            
            /*
             * Create optimizer, solve
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, rho, aulits, _state);
                tolx = 0.0050;
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                    tolx = 0.0010;
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                        tolx = 0.0010;
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetlc(&state, &c, &ct, k, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
            }
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1309");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1310");
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardresults(&state, &ogrep, _state);
                ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:1314");
            }
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            for(i=0; i<=k-1; i++)
            {
                v = ae_v_dotproduct(&x1.ptr.p_double[0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                if( ct.ptr.p_int[i]==0 )
                {
                    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(v-c.ptr.pp_double[i][n], _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:1322");
                }
                if( ct.ptr.p_int[i]>0 )
                {
                    ae_set_error_flag(wereerrors, ae_fp_less(v,c.ptr.pp_double[i][n]-tolx), __FILE__, __LINE__, "testminnlcunit.ap:1324");
                }
                if( ct.ptr.p_int[i]<0 )
                {
                    ae_set_error_flag(wereerrors, ae_fp_greater(v,c.ptr.pp_double[i][n]+tolx), __FILE__, __LINE__, "testminnlcunit.ap:1326");
                }
            }
        }
        
        /*
         * Boundary and linear equality constrained QP problem,
         * test checks that different starting points yield same final point:
         * * random N from [1..6], random K from [1..N-1]
         * * N*N SPD A with moderate condtion number (important!)
         * * boundary constraints 0<=x[i]<=1
         * * K<N random linear equality constraints C*x = C*x0,
         *   where x0 is some random vector from the inner area of the
         *   feasible hypercube (0.1<=x0[i]<=0.9)
         * * optimization problem has form 0.5*x'*A*x+b*x,
         *   where b is some random vector with -5<=b[i]<=+5
         *
         * We solve this problem two times:
         * * each time from different initial point XStart in [-2,+2]
         * * we compare values of the target function (although final points
         *   may be slightly different, function values should match each other)
         * 
         * Both points should give same results; any significant difference is
         * evidence of some error in the QP implementation.
         */
        rho = 1000.0;
        tolf = 0.0001;
        aulits = 10;
        for(pass=1; pass<=50; pass++)
        {
            
            /*
             * Generate problem: N, K, A, b, BndL, BndU, CMatrix, x0, xm, XStart.
             */
            n = ae_randominteger(5, _state)+2;
            k = 1+ae_randominteger(n-1, _state);
            spdmatrixrndcond(n, 1.0E2, &fulla, _state);
            ae_vector_set_length(&b, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&xstart, n, _state);
            ae_matrix_set_length(&c, k, n+1, _state);
            ae_vector_set_length(&ct, k, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = 0.1+0.8*ae_randomreal(_state);
                b.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
                bndl.ptr.p_double[i] = 0.0;
                bndu.ptr.p_double[i] = 1.0;
            }
            for(i=0; i<=k-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = (double)2*ae_randomreal(_state)-(double)1;
                }
                c.ptr.pp_double[i][i] = c.ptr.pp_double[i][i]+(double)4;
                v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &x0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                c.ptr.pp_double[i][n] = v;
                ct.ptr.p_int[i] = 0;
            }
            
            /*
             * Start from first point
             */
            for(i=0; i<=n-1; i++)
            {
                xstart.ptr.p_double[i] = (double)4*ae_randomreal(_state)-(double)2;
            }
            minnlccreate(n, &xstart, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, rho, aulits, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetlc(&state, &c, &ct, k, _state);
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
            }
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x0, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x0, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1430");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1431");
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                minnlcoptguardresults(&state, &ogrep, _state);
                ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:1435");
            }
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Start from another point
             */
            for(i=0; i<=n-1; i++)
            {
                xstart.ptr.p_double[i] = (double)4*ae_randomreal(_state)-(double)2;
            }
            minnlcrestartfrom(&state, &xstart, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1466");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1467");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Calculate function value at X0 and X1, compare solutions
             */
            f0 = 0.0;
            f1 = 0.0;
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    f0 = f0+0.5*x0.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*x0.ptr.p_double[j];
                    f1 = f1+0.5*x1.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*x1.ptr.p_double[j];
                }
                f0 = f0+x0.ptr.p_double[i]*b.ptr.p_double[i];
                f1 = f1+x1.ptr.p_double[i]*b.ptr.p_double[i];
            }
            ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(f0-f1, _state),tolf), __FILE__, __LINE__, "testminnlcunit.ap:1486");
        }
        
        /*
         * Convex/nonconvex optimization problem with excessive
         * (degenerate constraints):
         *
         * * N=2..7
         * * f = 0.5*x'*A*x+b'*x
         * * b has normally distributed entries with scale 10^BScale
         * * several kinds of A are tried: zero, well conditioned SPD, well conditioned indefinite, low rank
         * * box constraints: x[i] in [-1,+1]
         * * 2^N "excessive" general linear constraints (v_k,x)<=(v_k,v_k)+v_shift,
         *   where v_k is one of 2^N vertices of feasible hypercube, v_shift is
         *   a shift parameter:
         *   * with zero v_shift such constraints are degenerate (each vertex has
         *     N box constraints and one "redundant" linear constraint)
         *   * with positive v_shift linear constraint is always inactive
         *   * with small (about machine epsilon) but negative v_shift,
         *     constraint is close to degenerate - but not exactly
         *
         * We check that constrained gradient is close to zero at solution.
         * Box constraint is considered active if distance to boundary is less
         * than TolConstr.
         *
         * NOTE: because AUL algorithm is less exact than its active set counterparts,
         *       VERY loose tolerances are used for this test.
         */
        tolconstr = 1.0E-2;
        for(n=2; n<=6; n++)
        {
            for(akind=0; akind<=3; akind++)
            {
                
                /*
                 * Choose random parameters
                 */
                shiftkind = hqrnduniformi(&rs, 7, _state)-5;
                bscale = hqrnduniformi(&rs, 3, _state)-2;
                
                /*
                 * Generate A, B and initial point
                 */
                ae_matrix_set_length(&a, n, n, _state);
                ae_vector_set_length(&b, n, _state);
                ae_vector_set_length(&x, n, _state);
                for(i=0; i<=n-1; i++)
                {
                    b.ptr.p_double[i] = ae_pow((double)(10), (double)(bscale), _state)*hqrndnormal(&rs, _state);
                    x.ptr.p_double[i] = hqrnduniformr(&rs, _state)-0.5;
                }
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        a.ptr.pp_double[i][j] = 0.0;
                    }
                }
                if( akind==1 )
                {
                    
                    /*
                     * Dense well conditioned SPD
                     */
                    spdmatrixrndcond(n, 50.0, &a, _state);
                }
                if( akind==2 )
                {
                    
                    /*
                     * Dense well conditioned indefinite
                     */
                    smatrixrndcond(n, 50.0, &a, _state);
                }
                if( akind==3 )
                {
                    
                    /*
                     * Low rank
                     */
                    ae_vector_set_length(&tmp, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            a.ptr.pp_double[i][j] = 0.0;
                        }
                        a.ptr.pp_double[i][i] = 1.0E-9;
                    }
                    for(k=1; k<=ae_minint(3, n-1, _state); k++)
                    {
                        for(i=0; i<=n-1; i++)
                        {
                            tmp.ptr.p_double[i] = hqrndnormal(&rs, _state);
                        }
                        v = hqrndnormal(&rs, _state);
                        for(i=0; i<=n-1; i++)
                        {
                            for(j=0; j<=n-1; j++)
                            {
                                a.ptr.pp_double[i][j] = a.ptr.pp_double[i][j]+v*tmp.ptr.p_double[i]*tmp.ptr.p_double[j];
                            }
                        }
                    }
                }
                
                /*
                 * Generate constraints
                 */
                ae_vector_set_length(&bl, n, _state);
                ae_vector_set_length(&bu, n, _state);
                for(i=0; i<=n-1; i++)
                {
                    bl.ptr.p_double[i] = -1.0;
                    bu.ptr.p_double[i] = 1.0;
                }
                ccnt = ae_round(ae_pow((double)(2), (double)(n), _state), _state);
                ae_matrix_set_length(&c, ccnt, n+1, _state);
                ae_vector_set_length(&ct, ccnt, _state);
                for(i=0; i<=ccnt-1; i++)
                {
                    ct.ptr.p_int[i] = -1;
                    k = i;
                    c.ptr.pp_double[i][n] = (double)ae_sign((double)(shiftkind), _state)*ae_pow((double)(10), ae_fabs((double)(shiftkind), _state), _state)*ae_machineepsilon;
                    for(j=0; j<=n-1; j++)
                    {
                        c.ptr.pp_double[i][j] = (double)(2*(k%2)-1);
                        c.ptr.pp_double[i][n] = c.ptr.pp_double[i][n]+c.ptr.pp_double[i][j]*c.ptr.pp_double[i][j];
                        k = k/2;
                    }
                }
                
                /*
                 * Create and optimize
                 */
                minnlccreate(n, &x, &state, _state);
                minnlcsetbc(&state, &bl, &bu, _state);
                minnlcsetlc(&state, &c, &ct, ccnt, _state);
                minnlcsetcond(&state, 1.0E-12, 0, _state);
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, rho, aulits, _state);
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                }
                while(minnlciteration(&state, _state))
                {
                    ae_assert(state.needfij, "Assertion failed", _state);
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+state.x.ptr.p_double[i]*b.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        v = ae_v_dotproduct(&a.ptr.pp_double[i][0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*v;
                        state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+v;
                    }
                }
                minnlcresults(&state, &xs0, &rep, _state);
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1641");
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardresults(&state, &ogrep, _state);
                    ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:1645");
                }
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                
                /*
                 * Evaluate gradient at solution and test
                 */
                vv = 0.0;
                gnrm2 = (double)(0);
                for(i=0; i<=n-1; i++)
                {
                    v = ae_v_dotproduct(&a.ptr.pp_double[i][0], 1, &xs0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    v = v+b.ptr.p_double[i];
                    gnrm2 = gnrm2+v*v;
                    if( ae_fp_less_eq(xs0.ptr.p_double[i],bl.ptr.p_double[i]+tolconstr)&&ae_fp_greater(v,(double)(0)) )
                    {
                        v = 0.0;
                    }
                    if( ae_fp_greater_eq(xs0.ptr.p_double[i],bu.ptr.p_double[i]-tolconstr)&&ae_fp_less(v,(double)(0)) )
                    {
                        v = 0.0;
                    }
                    vv = vv+ae_sqr(v, _state);
                }
                vv = ae_sqrt(vv/(gnrm2+1.0), _state);
                ae_set_error_flag(wereerrors, ae_fp_greater(vv,1.0E-2), __FILE__, __LINE__, "testminnlcunit.ap:1672");
            }
        }
        
        /*
         * Linear/convex optimization problem with combination of
         * box and linear constraints:
         *
         * * N=2..8
         * * f = 0.5*x'*A*x+b'*x
         * * b has normally distributed entries with scale 10^BScale
         * * several kinds of A are tried: zero, well conditioned SPD
         * * box constraints: x[i] in [-1,+1]
         * * initial point x0 = [0 0 ... 0 0]
         * * CCnt=min(3,N-1) general linear constraints of form (c,x)=0.
         *   random mix of equality/inequality constraints is tried.
         *   x0 is guaranteed to be feasible.
         *
         * We check that constrained gradient is close to zero at solution.
         * Inequality constraint is considered active if distance to boundary
         * is less than TolConstr. We use nonnegative least squares solver
         * in order to compute constrained gradient.
         */
        tolconstr = 1.0E-2;
        for(n=2; n<=8; n++)
        {
            for(akind=0; akind<=1; akind++)
            {
                for(bscale=0; bscale>=-2; bscale--)
                {
                    
                    /*
                     * Generate A, B and initial point
                     */
                    ae_matrix_set_length(&a, n, n, _state);
                    ae_vector_set_length(&b, n, _state);
                    ae_vector_set_length(&x, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        b.ptr.p_double[i] = ae_pow((double)(10), (double)(bscale), _state)*hqrndnormal(&rs, _state);
                        x.ptr.p_double[i] = 0.0;
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            a.ptr.pp_double[i][j] = 0.0;
                        }
                    }
                    if( akind==1 )
                    {
                        
                        /*
                         * Dense well conditioned SPD
                         */
                        spdmatrixrndcond(n, 50.0, &a, _state);
                    }
                    if( solvertype!=0 )
                    {
                        
                        /*
                         * AUL performs poorly on such problems,
                         * but SLP works goo.
                         */
                        if( akind==2 )
                        {
                            
                            /*
                             * Dense well conditioned indefinite
                             */
                            smatrixrndcond(n, 50.0, &a, _state);
                        }
                        if( akind==3 )
                        {
                            
                            /*
                             * Low rank
                             */
                            ae_vector_set_length(&tmp, n, _state);
                            for(i=0; i<=n-1; i++)
                            {
                                for(j=0; j<=n-1; j++)
                                {
                                    a.ptr.pp_double[i][j] = 0.0;
                                }
                                a.ptr.pp_double[i][i] = 1.0E-9;
                            }
                            for(k=1; k<=ae_minint(3, n-1, _state); k++)
                            {
                                for(i=0; i<=n-1; i++)
                                {
                                    tmp.ptr.p_double[i] = hqrndnormal(&rs, _state);
                                }
                                v = hqrndnormal(&rs, _state);
                                for(i=0; i<=n-1; i++)
                                {
                                    for(j=0; j<=n-1; j++)
                                    {
                                        a.ptr.pp_double[i][j] = a.ptr.pp_double[i][j]+v*tmp.ptr.p_double[i]*tmp.ptr.p_double[j];
                                    }
                                }
                            }
                        }
                    }
                    
                    /*
                     * Generate constraints
                     */
                    ae_vector_set_length(&bl, n, _state);
                    ae_vector_set_length(&bu, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        bl.ptr.p_double[i] = -1.0;
                        bu.ptr.p_double[i] = 1.0;
                    }
                    ccnt = ae_minint(3, n-1, _state);
                    ae_matrix_set_length(&c, ccnt, n+1, _state);
                    ae_vector_set_length(&ct, ccnt, _state);
                    for(i=0; i<=ccnt-1; i++)
                    {
                        ct.ptr.p_int[i] = hqrnduniformi(&rs, 3, _state)-1;
                        c.ptr.pp_double[i][n] = 0.0;
                        for(j=0; j<=n-1; j++)
                        {
                            c.ptr.pp_double[i][j] = hqrnduniformr(&rs, _state)-0.5;
                        }
                        c.ptr.pp_double[i][i] = c.ptr.pp_double[i][i]+(double)4;
                    }
                    
                    /*
                     * Create and optimize
                     */
                    minnlccreate(n, &x, &state, _state);
                    minnlcsetbc(&state, &bl, &bu, _state);
                    minnlcsetlc(&state, &c, &ct, ccnt, _state);
                    minnlcsetcond(&state, 1.0E-7, 0, _state);
                    if( solvertype==0 )
                    {
                        minnlcsetalgoaul(&state, 1000.0, 10, _state);
                    }
                    else
                    {
                        if( solvertype==1 )
                        {
                            minnlcsetalgoslp(&state, _state);
                        }
                        else
                        {
                            if( solvertype==2 )
                            {
                                minnlcsetalgosqp(&state, _state);
                            }
                            else
                            {
                                ae_assert(ae_false, "Assertion failed", _state);
                            }
                        }
                    }
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                    }
                    while(minnlciteration(&state, _state))
                    {
                        ae_assert(state.needfij, "Assertion failed", _state);
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+state.x.ptr.p_double[i]*b.ptr.p_double[i];
                            state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        }
                        for(i=0; i<=n-1; i++)
                        {
                            v = ae_v_dotproduct(&a.ptr.pp_double[i][0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*v;
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+v;
                        }
                    }
                    minnlcresults(&state, &xs0, &rep, _state);
                    ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1817");
                    if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                    {
                        minnlcoptguardresults(&state, &ogrep, _state);
                        ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:1821");
                    }
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    
                    /*
                     * 1. evaluate unconstrained gradient at solution
                     *
                     * 2. calculate constrained gradient (NNLS solver is used
                     *    to evaluate gradient subject to active constraints).
                     *    In order to do this we form CE matrix, matrix of active
                     *    constraints (columns store constraint vectors). Then
                     *    we try to approximate gradient vector by columns of CE,
                     *    subject to non-negativity restriction placed on variables
                     *    corresponding to inequality constraints.
                     *
                     *    Residual from such regression is a constrained gradient vector.
                     */
                    ae_vector_set_length(&g, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        v = ae_v_dotproduct(&a.ptr.pp_double[i][0], 1, &xs0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                        g.ptr.p_double[i] = v+b.ptr.p_double[i];
                    }
                    ae_matrix_set_length(&ce, n, n+ccnt, _state);
                    ae_vector_set_length(&nonnegative, n+ccnt, _state);
                    k = 0;
                    for(i=0; i<=n-1; i++)
                    {
                        ae_set_error_flag(wereerrors, ae_fp_less(xs0.ptr.p_double[i],bl.ptr.p_double[i]-tolconstr), __FILE__, __LINE__, "testminnlcunit.ap:1850");
                        ae_set_error_flag(wereerrors, ae_fp_greater(xs0.ptr.p_double[i],bu.ptr.p_double[i]+tolconstr), __FILE__, __LINE__, "testminnlcunit.ap:1851");
                        if( ae_fp_less_eq(xs0.ptr.p_double[i],bl.ptr.p_double[i]+tolconstr) )
                        {
                            for(j=0; j<=n-1; j++)
                            {
                                ce.ptr.pp_double[j][k] = 0.0;
                            }
                            ce.ptr.pp_double[i][k] = 1.0;
                            nonnegative.ptr.p_bool[k] = ae_true;
                            inc(&k, _state);
                            continue;
                        }
                        if( ae_fp_greater_eq(xs0.ptr.p_double[i],bu.ptr.p_double[i]-tolconstr) )
                        {
                            for(j=0; j<=n-1; j++)
                            {
                                ce.ptr.pp_double[j][k] = 0.0;
                            }
                            ce.ptr.pp_double[i][k] = -1.0;
                            nonnegative.ptr.p_bool[k] = ae_true;
                            inc(&k, _state);
                            continue;
                        }
                    }
                    for(i=0; i<=ccnt-1; i++)
                    {
                        v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &xs0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                        v = v-c.ptr.pp_double[i][n];
                        ae_set_error_flag(wereerrors, ct.ptr.p_int[i]==0&&ae_fp_greater(ae_fabs(v, _state),tolconstr), __FILE__, __LINE__, "testminnlcunit.ap:1875");
                        ae_set_error_flag(wereerrors, ct.ptr.p_int[i]>0&&ae_fp_less(v,-tolconstr), __FILE__, __LINE__, "testminnlcunit.ap:1876");
                        ae_set_error_flag(wereerrors, ct.ptr.p_int[i]<0&&ae_fp_greater(v,tolconstr), __FILE__, __LINE__, "testminnlcunit.ap:1877");
                        if( ct.ptr.p_int[i]==0 )
                        {
                            for(j=0; j<=n-1; j++)
                            {
                                ce.ptr.pp_double[j][k] = c.ptr.pp_double[i][j];
                            }
                            nonnegative.ptr.p_bool[k] = ae_false;
                            inc(&k, _state);
                            continue;
                        }
                        if( (ct.ptr.p_int[i]>0&&ae_fp_less_eq(v,tolconstr))||(ct.ptr.p_int[i]<0&&ae_fp_greater_eq(v,-tolconstr)) )
                        {
                            for(j=0; j<=n-1; j++)
                            {
                                ce.ptr.pp_double[j][k] = (double)ae_sign((double)(ct.ptr.p_int[i]), _state)*c.ptr.pp_double[i][j];
                            }
                            nonnegative.ptr.p_bool[k] = ae_true;
                            inc(&k, _state);
                            continue;
                        }
                    }
                    snnlsinit(0, 0, 0, &nnls, _state);
                    snnlssetproblem(&nnls, &ce, &g, 0, k, n, _state);
                    for(i=0; i<=k-1; i++)
                    {
                        if( !nonnegative.ptr.p_bool[i] )
                        {
                            snnlsdropnnc(&nnls, i, _state);
                        }
                    }
                    snnlssolve(&nnls, &tmp, _state);
                    for(i=0; i<=k-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            g.ptr.p_double[j] = g.ptr.p_double[j]-tmp.ptr.p_double[i]*ce.ptr.pp_double[j][i];
                        }
                    }
                    vv = ae_v_dotproduct(&g.ptr.p_double[0], 1, &g.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    vv = ae_sqrt(vv, _state);
                    ae_set_error_flag(wereerrors, ae_fp_greater(vv,1.0E-3), __FILE__, __LINE__, "testminnlcunit.ap:1906");
                }
            }
        }
    }
    ae_frame_leave(_state);
}


/*************************************************************************
This function tests nonlinearly constrained quadratic programming algorithm.

Sets error flag on failure.
*************************************************************************/
static void testminnlcunit_testnlc(ae_bool* wereerrors, ae_state *_state)
{
    ae_frame _frame_block;
    ae_int_t n;
    ae_int_t n2;
    double tolx;
    double tolf;
    double tolg;
    ae_int_t aulits;
    double rho;
    minnlcstate state;
    minnlcreport rep;
    optguardreport ogrep;
    ae_int_t scaletype;
    ae_vector x0;
    ae_vector x1;
    ae_vector b;
    ae_vector bndl;
    ae_vector bndu;
    ae_vector s;
    ae_vector g;
    ae_vector rnlc;
    ae_vector xref;
    ae_vector lagmult;
    ae_vector ckind;
    ae_matrix fulla;
    ae_matrix c;
    ae_vector ct;
    ae_int_t cntbc;
    ae_int_t cntlc;
    ae_int_t cntnlec;
    ae_int_t cntnlic;
    ae_int_t cntactive;
    ae_int_t i;
    ae_int_t j;
    ae_int_t k;
    ae_int_t pass;
    ae_int_t klc;
    ae_int_t knlec;
    ae_int_t knlic;
    double v;
    double vv;
    double vx;
    double vy;
    double gnorm2;
    double rawgnorm2;
    double fref;
    double diffstep;
    hqrndstate rs;
    ae_int_t prectype;
    ae_int_t solvertype;

    ae_frame_make(_state, &_frame_block);
    memset(&state, 0, sizeof(state));
    memset(&rep, 0, sizeof(rep));
    memset(&ogrep, 0, sizeof(ogrep));
    memset(&x0, 0, sizeof(x0));
    memset(&x1, 0, sizeof(x1));
    memset(&b, 0, sizeof(b));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&s, 0, sizeof(s));
    memset(&g, 0, sizeof(g));
    memset(&rnlc, 0, sizeof(rnlc));
    memset(&xref, 0, sizeof(xref));
    memset(&lagmult, 0, sizeof(lagmult));
    memset(&ckind, 0, sizeof(ckind));
    memset(&fulla, 0, sizeof(fulla));
    memset(&c, 0, sizeof(c));
    memset(&ct, 0, sizeof(ct));
    memset(&rs, 0, sizeof(rs));
    _minnlcstate_init(&state, _state, ae_true);
    _minnlcreport_init(&rep, _state, ae_true);
    _optguardreport_init(&ogrep, _state, ae_true);
    ae_vector_init(&x0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x1, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&b, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&s, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&g, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&rnlc, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xref, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&lagmult, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&ckind, 0, DT_INT, _state, ae_true);
    ae_matrix_init(&fulla, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&c, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&ct, 0, DT_INT, _state, ae_true);
    _hqrndstate_init(&rs, _state, ae_true);

    hqrndrandomize(&rs, _state);
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        
        /*
         * Basic test:
         * * 2-dimensional problem
         * * target function F(x0,x1) = (x0-1)^2 + (x1-1)^2
         * * one nonlinear constraint Z(x0,x1) = x0^2+x1^2-1,
         *   which is tried as equality and inequality one
         */
        rho = 200.0;
        tolx = 0.0005;
        aulits = 50;
        n = 2;
        ae_vector_set_length(&x0, n, _state);
        for(i=0; i<=n-1; i++)
        {
            x0.ptr.p_double[i] = (double)2*ae_randomreal(_state)-(double)1;
        }
        minnlccreate(n, &x0, &state, _state);
        if( solvertype==0 )
        {
            minnlcsetalgoaul(&state, rho, aulits, _state);
        }
        else
        {
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
        minnlcsetcond(&state, 1.0E-7, 0, _state);
        minnlcsetnlc(&state, 0, 1, _state);
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = ae_sqr(state.x.ptr.p_double[0]-(double)1, _state)+ae_sqr(state.x.ptr.p_double[1]-(double)1, _state);
                state.j.ptr.pp_double[0][0] = (double)2*(state.x.ptr.p_double[0]-(double)1);
                state.j.ptr.pp_double[0][1] = (double)2*(state.x.ptr.p_double[1]-(double)1);
                state.fi.ptr.p_double[1] = ae_sqr(state.x.ptr.p_double[0], _state)+ae_sqr(state.x.ptr.p_double[1], _state)-(double)1;
                state.j.ptr.pp_double[1][0] = (double)2*state.x.ptr.p_double[0];
                state.j.ptr.pp_double[1][1] = (double)2*state.x.ptr.p_double[1];
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:1996");
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:1997");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[0]-ae_sqrt((double)(2), _state)/(double)2, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2000");
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[1]-ae_sqrt((double)(2), _state)/(double)2, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2001");
        minnlcsetnlc(&state, 1, 0, _state);
        minnlcrestartfrom(&state, &x0, _state);
        if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
        {
            minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
        }
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = ae_sqr(state.x.ptr.p_double[0]-(double)1, _state)+ae_sqr(state.x.ptr.p_double[1]-(double)1, _state);
                state.j.ptr.pp_double[0][0] = (double)2*(state.x.ptr.p_double[0]-(double)1);
                state.j.ptr.pp_double[0][1] = (double)2*(state.x.ptr.p_double[1]-(double)1);
                state.fi.ptr.p_double[1] = ae_sqr(state.x.ptr.p_double[0], _state)+ae_sqr(state.x.ptr.p_double[1], _state)-(double)1;
                state.j.ptr.pp_double[1][0] = (double)2*state.x.ptr.p_double[0];
                state.j.ptr.pp_double[1][1] = (double)2*state.x.ptr.p_double[1];
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:2021");
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:2022");
        if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
        {
            minnlcoptguardresults(&state, &ogrep, _state);
            ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:2026");
        }
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[0]-ae_sqrt((double)(2), _state)/(double)2, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2030");
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[1]-ae_sqrt((double)(2), _state)/(double)2, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2031");
        
        /*
         * This test checks correctness of scaling being applied to nonlinear
         * constraints. We solve bound constrained scaled problem and check
         * that solution is correct.
         */
        aulits = 50;
        rho = 200.0;
        tolx = 0.0005;
        tolg = 0.01;
        for(n=1; n<=10; n++)
        {
            for(pass=1; pass<=10; pass++)
            {
                
                /*
                 * Generate well-conditioned problem with unit scale
                 */
                spdmatrixrndcond(n, 1.0E2, &fulla, _state);
                ae_vector_set_length(&b, n, _state);
                ae_vector_set_length(&bndl, n, _state);
                ae_vector_set_length(&bndu, n, _state);
                ae_vector_set_length(&x0, n, _state);
                for(i=0; i<=n-1; i++)
                {
                    b.ptr.p_double[i] = hqrndnormal(&rs, _state);
                    x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                }
                cntnlec = hqrnduniformi(&rs, n, _state);
                cntnlic = n-cntnlec;
                for(i=0; i<=cntnlec-1; i++)
                {
                    bndl.ptr.p_double[i] = hqrndnormal(&rs, _state);
                    bndu.ptr.p_double[i] = bndl.ptr.p_double[i];
                }
                for(i=cntnlec; i<=n-1; i++)
                {
                    bndl.ptr.p_double[i] = hqrndnormal(&rs, _state);
                    bndu.ptr.p_double[i] = bndl.ptr.p_double[i]+0.5;
                }
                
                /*
                 * Apply scaling to quadratic/linear term, so problem becomes
                 * well-conditioned in the scaled coordinates.
                 */
                scaletype = hqrnduniformi(&rs, 2, _state);
                ae_vector_set_length(&s, n, _state);
                for(i=0; i<=n-1; i++)
                {
                    if( scaletype==0 )
                    {
                        s.ptr.p_double[i] = (double)(1);
                    }
                    else
                    {
                        s.ptr.p_double[i] = ae_exp((double)5*hqrndnormal(&rs, _state), _state);
                    }
                }
                for(i=0; i<=n-1; i++)
                {
                    x0.ptr.p_double[i] = x0.ptr.p_double[i]*s.ptr.p_double[i];
                    bndl.ptr.p_double[i] = bndl.ptr.p_double[i]*s.ptr.p_double[i];
                    bndu.ptr.p_double[i] = bndu.ptr.p_double[i]*s.ptr.p_double[i];
                    b.ptr.p_double[i] = b.ptr.p_double[i]/s.ptr.p_double[i];
                    for(j=0; j<=n-1; j++)
                    {
                        fulla.ptr.pp_double[i][j] = fulla.ptr.pp_double[i][j]/(s.ptr.p_double[i]*s.ptr.p_double[j]);
                    }
                }
                
                /*
                 * Solve problem with boundary constraints posed as nonlinear ones
                 */
                minnlccreate(n, &x0, &state, _state);
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, rho, aulits, _state);
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                minnlcsetscale(&state, &s, _state);
                minnlcsetnlc(&state, cntnlec, 2*cntnlic, _state);
                minnlcsetcond(&state, 1.0E-7, 0, _state);
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                }
                while(minnlciteration(&state, _state))
                {
                    if( state.needfij )
                    {
                        for(i=0; i<=cntnlec+2*cntnlic; i++)
                        {
                            state.fi.ptr.p_double[i] = (double)(0);
                            for(j=0; j<=n-1; j++)
                            {
                                state.j.ptr.pp_double[i][j] = (double)(0);
                            }
                        }
                        
                        /*
                         * Function itself
                         */
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                            state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                            for(j=0; j<=n-1; j++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            }
                        }
                        
                        /*
                         * Equality constraints
                         */
                        for(i=0; i<=cntnlec-1; i++)
                        {
                            state.fi.ptr.p_double[1+i] = (state.x.ptr.p_double[i]-bndl.ptr.p_double[i])/s.ptr.p_double[i];
                            state.j.ptr.pp_double[1+i][i] = (double)1/s.ptr.p_double[i];
                        }
                        
                        /*
                         * Inequality constraints
                         */
                        for(i=0; i<=cntnlic-1; i++)
                        {
                            k = cntnlec+i;
                            state.fi.ptr.p_double[1+cntnlec+2*i+0] = (bndl.ptr.p_double[k]-state.x.ptr.p_double[k])/s.ptr.p_double[k];
                            state.j.ptr.pp_double[1+cntnlec+2*i+0][k] = -(double)1/s.ptr.p_double[k];
                            state.fi.ptr.p_double[1+cntnlec+2*i+1] = (state.x.ptr.p_double[k]-bndu.ptr.p_double[k])/s.ptr.p_double[k];
                            state.j.ptr.pp_double[1+cntnlec+2*i+1][k] = (double)1/s.ptr.p_double[k];
                        }
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                minnlcresults(&state, &x1, &rep, _state);
                ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:2165");
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:2166");
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardresults(&state, &ogrep, _state);
                    ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:2170");
                }
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                
                /*
                 * Check feasibility properties
                 */
                for(i=0; i<=n-1; i++)
                {
                    ae_set_error_flag(wereerrors, ae_isfinite(bndl.ptr.p_double[i], _state)&&ae_fp_less_eq(x1.ptr.p_double[i],bndl.ptr.p_double[i]-tolx*s.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:2180");
                    ae_set_error_flag(wereerrors, ae_isfinite(bndu.ptr.p_double[i], _state)&&ae_fp_greater_eq(x1.ptr.p_double[i],bndu.ptr.p_double[i]+tolx*s.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:2181");
                }
                
                /*
                 * Test - calculate scaled constrained gradient at solution,
                 * check its norm.
                 */
                ae_vector_set_length(&g, n, _state);
                gnorm2 = 0.0;
                for(i=0; i<=n-1; i++)
                {
                    g.ptr.p_double[i] = b.ptr.p_double[i];
                    for(j=0; j<=n-1; j++)
                    {
                        g.ptr.p_double[i] = g.ptr.p_double[i]+fulla.ptr.pp_double[i][j]*x1.ptr.p_double[j];
                    }
                    g.ptr.p_double[i] = s.ptr.p_double[i]*g.ptr.p_double[i];
                    if( (ae_isfinite(bndl.ptr.p_double[i], _state)&&ae_fp_less(ae_fabs(x1.ptr.p_double[i]-bndl.ptr.p_double[i], _state),tolx*s.ptr.p_double[i]))&&ae_fp_greater(g.ptr.p_double[i],(double)(0)) )
                    {
                        g.ptr.p_double[i] = (double)(0);
                    }
                    if( (ae_isfinite(bndu.ptr.p_double[i], _state)&&ae_fp_less(ae_fabs(x1.ptr.p_double[i]-bndu.ptr.p_double[i], _state),tolx*s.ptr.p_double[i]))&&ae_fp_less(g.ptr.p_double[i],(double)(0)) )
                    {
                        g.ptr.p_double[i] = (double)(0);
                    }
                    gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[i], _state);
                }
                ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2203");
            }
        }
        
        /*
         * Complex problem with mix of boundary, linear and nonlinear constraints:
         * * quadratic target function f(x) = 0.5*x'*A*x + b'*x
         * * unit scaling is used
         * * problem size N is even
         * * all variables are divided into pairs: x[0] and x[1], x[2] and x[3], ...
         * * constraints are set for pairs of variables, i.e. each constraint involves
         *   only pair of adjacent variables (x0/x1, x2/x3, x4/x5 and so on), and each
         *   pair of variables has at most one constraint which binds them
         * * for variables u and v following kinds of constraints can be randomly set:
         *   * CKind=0      no constraint
         *   * CKind=1      boundary equality constraint:    u=a, v=b
         *   * CKind=2      boundary inequality constraint:  a0<=u<=b0, a1<=v<=b1
         *   * CKind=3      linear equality constraint:      a*u+b*v  = c
         *   * CKind=4      linear inequality constraint:    a*u+b*v <= c
         *   * CKind=5      nonlinear equality constraint:   u^2+v^2  = 1
         *   * CKind=6      nonlinear inequality constraint: u^2+v^2 <= 1
         * * it is relatively easy to calculated projected gradient for such problem
         */
        aulits = 50;
        rho = 200.0;
        tolx = 0.0005;
        tolg = 0.005;
        n = 20;
        n2 = n/2;
        for(pass=1; pass<=5; pass++)
        {
            for(prectype=1; prectype<=2; prectype++)
            {
                
                /*
                 * Generate well-conditioned problem with unit scale
                 */
                spdmatrixrndcond(n, 1.0E2, &fulla, _state);
                ae_vector_set_length(&b, n, _state);
                ae_vector_set_length(&bndl, n, _state);
                ae_vector_set_length(&bndu, n, _state);
                ae_matrix_set_length(&c, n, n+1, _state);
                ae_vector_set_length(&ct, n, _state);
                ae_vector_set_length(&x0, n, _state);
                ae_vector_set_length(&ckind, n2, _state);
                ae_vector_set_length(&rnlc, n2, _state);
                cntbc = 0;
                cntlc = 0;
                cntnlec = 0;
                cntnlic = 0;
                for(i=0; i<=n-1; i++)
                {
                    bndl.ptr.p_double[i] = _state->v_neginf;
                    bndu.ptr.p_double[i] = _state->v_posinf;
                    x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                    b.ptr.p_double[i] = (double)10*hqrndnormal(&rs, _state);
                }
                for(i=0; i<=n2-1; i++)
                {
                    ckind.ptr.p_int[i] = hqrnduniformi(&rs, 7, _state);
                    rnlc.ptr.p_double[i] = (double)(0);
                    if( ckind.ptr.p_int[i]==0 )
                    {
                        
                        /*
                         * Unconstrained
                         */
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==1 )
                    {
                        
                        /*
                         * Bound equality constrained
                         */
                        bndl.ptr.p_double[2*i+0] = hqrnduniformr(&rs, _state)-0.5;
                        bndu.ptr.p_double[2*i+0] = bndl.ptr.p_double[2*i+0];
                        bndl.ptr.p_double[2*i+1] = hqrnduniformr(&rs, _state)-0.5;
                        bndu.ptr.p_double[2*i+1] = bndl.ptr.p_double[2*i+1];
                        inc(&cntbc, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==2 )
                    {
                        
                        /*
                         * Bound inequality constrained
                         */
                        bndl.ptr.p_double[2*i+0] = hqrnduniformr(&rs, _state)-0.5;
                        bndu.ptr.p_double[2*i+0] = bndl.ptr.p_double[2*i+0]+0.5;
                        bndl.ptr.p_double[2*i+1] = hqrnduniformr(&rs, _state)-0.5;
                        bndu.ptr.p_double[2*i+1] = bndl.ptr.p_double[2*i+1]+0.5;
                        inc(&cntbc, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==3 )
                    {
                        
                        /*
                         * Linear equality constrained
                         */
                        for(j=0; j<=n; j++)
                        {
                            c.ptr.pp_double[cntlc][j] = 0.0;
                        }
                        vx = hqrnduniformr(&rs, _state)-0.5;
                        vy = hqrnduniformr(&rs, _state)-0.5;
                        c.ptr.pp_double[cntlc][2*i+0] = vx;
                        c.ptr.pp_double[cntlc][2*i+1] = vy;
                        c.ptr.pp_double[cntlc][n] = hqrnduniformr(&rs, _state)-0.5;
                        ct.ptr.p_int[cntlc] = 0;
                        inc(&cntlc, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==4 )
                    {
                        
                        /*
                         * Linear inequality constrained
                         */
                        for(j=0; j<=n; j++)
                        {
                            c.ptr.pp_double[cntlc][j] = 0.0;
                        }
                        vx = hqrnduniformr(&rs, _state)-0.5;
                        vy = hqrnduniformr(&rs, _state)-0.5;
                        c.ptr.pp_double[cntlc][2*i+0] = vx;
                        c.ptr.pp_double[cntlc][2*i+1] = vy;
                        c.ptr.pp_double[cntlc][n] = hqrnduniformr(&rs, _state)-0.5;
                        ct.ptr.p_int[cntlc] = -1;
                        inc(&cntlc, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==5 )
                    {
                        
                        /*
                         * Nonlinear equality constrained
                         */
                        rnlc.ptr.p_double[i] = 0.5+hqrnduniformr(&rs, _state);
                        inc(&cntnlec, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==6 )
                    {
                        
                        /*
                         * Nonlinear inequality constrained
                         */
                        rnlc.ptr.p_double[i] = 0.5+hqrnduniformr(&rs, _state);
                        inc(&cntnlic, _state);
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                
                /*
                 * Solve problem
                 */
                minnlccreate(n, &x0, &state, _state);
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, rho, aulits, _state);
                    minnlcsetcond(&state, 1.0E-7, 0, _state);
                    if( prectype==0 )
                    {
                        minnlcsetprecinexact(&state, _state);
                    }
                    if( prectype==1 )
                    {
                        minnlcsetprecexactlowrank(&state, 0, _state);
                    }
                    if( prectype==2 )
                    {
                        minnlcsetprecexactrobust(&state, 0, _state);
                    }
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                        minnlcsetcond(&state, 1.0E-6, 0, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                            minnlcsetcond(&state, 1.0E-6, 0, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                minnlcsetbc(&state, &bndl, &bndu, _state);
                minnlcsetlc(&state, &c, &ct, cntlc, _state);
                minnlcsetnlc(&state, cntnlec, cntnlic, _state);
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardsmoothness(&state, hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel+1, _state), _state);
                }
                while(minnlciteration(&state, _state))
                {
                    if( state.needfij )
                    {
                        
                        /*
                         * Evaluate target function
                         */
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                            state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                            for(j=0; j<=n-1; j++)
                            {
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                                state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            }
                        }
                        
                        /*
                         * Evaluate constraint functions
                         */
                        knlec = 1;
                        knlic = 1+cntnlec;
                        for(i=0; i<=n2-1; i++)
                        {
                            if( ckind.ptr.p_int[i]==5 )
                            {
                                state.fi.ptr.p_double[knlec] = (double)(0);
                                for(j=0; j<=n-1; j++)
                                {
                                    state.j.ptr.pp_double[knlec][j] = 0.0;
                                }
                                state.fi.ptr.p_double[knlec] = ae_sqr(state.x.ptr.p_double[2*i+0], _state)+ae_sqr(state.x.ptr.p_double[2*i+1], _state)-rnlc.ptr.p_double[i];
                                state.j.ptr.pp_double[knlec][2*i+0] = (double)2*state.x.ptr.p_double[2*i+0];
                                state.j.ptr.pp_double[knlec][2*i+1] = (double)2*state.x.ptr.p_double[2*i+1];
                                inc(&knlec, _state);
                                continue;
                            }
                            if( ckind.ptr.p_int[i]==6 )
                            {
                                state.fi.ptr.p_double[knlic] = (double)(0);
                                for(j=0; j<=n-1; j++)
                                {
                                    state.j.ptr.pp_double[knlic][j] = 0.0;
                                }
                                state.fi.ptr.p_double[knlic] = ae_sqr(state.x.ptr.p_double[2*i+0], _state)+ae_sqr(state.x.ptr.p_double[2*i+1], _state)-rnlc.ptr.p_double[i];
                                state.j.ptr.pp_double[knlic][2*i+0] = (double)2*state.x.ptr.p_double[2*i+0];
                                state.j.ptr.pp_double[knlic][2*i+1] = (double)2*state.x.ptr.p_double[2*i+1];
                                inc(&knlic, _state);
                                continue;
                            }
                        }
                        ae_assert(knlec==1+cntnlec, "Assertion failed", _state);
                        ae_assert(knlic==1+cntnlec+cntnlic, "Assertion failed", _state);
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                minnlcresults(&state, &x1, &rep, _state);
                ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:2434");
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:2435");
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlcoptguardresults(&state, &ogrep, _state);
                    ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:2439");
                }
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                
                /*
                 * Check feasibility properties
                 */
                klc = 0;
                for(i=0; i<=n2-1; i++)
                {
                    if( ckind.ptr.p_int[i]==0 )
                    {
                        
                        /*
                         * Unconstrained
                         */
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==1 )
                    {
                        
                        /*
                         * Bound equality constrained
                         */
                        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[2*i+0]-bndl.ptr.p_double[2*i+0], _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2462");
                        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[2*i+1]-bndl.ptr.p_double[2*i+1], _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2463");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==2 )
                    {
                        
                        /*
                         * Bound inequality constrained
                         */
                        ae_set_error_flag(wereerrors, ae_fp_less(x1.ptr.p_double[2*i+0],bndl.ptr.p_double[2*i+0]-tolx), __FILE__, __LINE__, "testminnlcunit.ap:2471");
                        ae_set_error_flag(wereerrors, ae_fp_greater(x1.ptr.p_double[2*i+0],bndu.ptr.p_double[2*i+0]+tolx), __FILE__, __LINE__, "testminnlcunit.ap:2472");
                        ae_set_error_flag(wereerrors, ae_fp_less(x1.ptr.p_double[2*i+1],bndl.ptr.p_double[2*i+1]-tolx), __FILE__, __LINE__, "testminnlcunit.ap:2473");
                        ae_set_error_flag(wereerrors, ae_fp_greater(x1.ptr.p_double[2*i+1],bndu.ptr.p_double[2*i+1]+tolx), __FILE__, __LINE__, "testminnlcunit.ap:2474");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==3 )
                    {
                        
                        /*
                         * Linear equality constrained
                         */
                        v = x1.ptr.p_double[2*i+0]*c.ptr.pp_double[klc][2*i+0]+x1.ptr.p_double[2*i+1]*c.ptr.pp_double[klc][2*i+1]-c.ptr.pp_double[klc][n];
                        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(v, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2483");
                        inc(&klc, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==4 )
                    {
                        
                        /*
                         * Linear inequality constrained
                         */
                        v = x1.ptr.p_double[2*i+0]*c.ptr.pp_double[klc][2*i+0]+x1.ptr.p_double[2*i+1]*c.ptr.pp_double[klc][2*i+1]-c.ptr.pp_double[klc][n];
                        ae_set_error_flag(wereerrors, ae_fp_greater(v,tolx), __FILE__, __LINE__, "testminnlcunit.ap:2493");
                        inc(&klc, _state);
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==5 )
                    {
                        
                        /*
                         * Nonlinear equality constrained
                         */
                        v = ae_sqr(x1.ptr.p_double[2*i+0], _state)+ae_sqr(x1.ptr.p_double[2*i+1], _state)-rnlc.ptr.p_double[i];
                        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(v, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:2503");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==6 )
                    {
                        
                        /*
                         * Nonlinear inequality constrained
                         */
                        v = ae_sqr(x1.ptr.p_double[2*i+0], _state)+ae_sqr(x1.ptr.p_double[2*i+1], _state)-rnlc.ptr.p_double[i];
                        ae_set_error_flag(wereerrors, ae_fp_greater(v,tolx), __FILE__, __LINE__, "testminnlcunit.ap:2512");
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                
                /*
                 * Test - calculate scaled constrained gradient at solution,
                 * check its norm.
                 */
                gnorm2 = 0.0;
                rawgnorm2 = (double)(0);
                ae_vector_set_length(&g, n, _state);
                for(i=0; i<=n-1; i++)
                {
                    v = b.ptr.p_double[i];
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+fulla.ptr.pp_double[i][j]*x1.ptr.p_double[j];
                    }
                    g.ptr.p_double[i] = v;
                    rawgnorm2 = rawgnorm2+v*v;
                }
                klc = 0;
                for(i=0; i<=n2-1; i++)
                {
                    if( ckind.ptr.p_int[i]==0 )
                    {
                        
                        /*
                         * Unconstrained
                         */
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2542");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==1 )
                    {
                        
                        /*
                         * Bound equality constrained, unconditionally set gradient to zero
                         */
                        g.ptr.p_double[2*i+0] = 0.0;
                        g.ptr.p_double[2*i+1] = 0.0;
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2553");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==2 )
                    {
                        
                        /*
                         * Bound inequality constrained, conditionally set gradient to zero
                         * (when constraint is active)
                         */
                        if( ae_fp_less(x1.ptr.p_double[2*i+0],bndl.ptr.p_double[2*i+0]+tolx)||ae_fp_greater(x1.ptr.p_double[2*i+0],bndu.ptr.p_double[2*i+0]-tolx) )
                        {
                            g.ptr.p_double[2*i+0] = 0.0;
                        }
                        if( ae_fp_less(x1.ptr.p_double[2*i+1],bndl.ptr.p_double[2*i+1]+tolx)||ae_fp_greater(x1.ptr.p_double[2*i+1],bndu.ptr.p_double[2*i+1]-tolx) )
                        {
                            g.ptr.p_double[2*i+1] = 0.0;
                        }
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2567");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==3 )
                    {
                        
                        /*
                         * Linear equality constrained, unconditionally project gradient into
                         * equality constrained subspace
                         */
                        v = g.ptr.p_double[2*i+0]*c.ptr.pp_double[klc][2*i+0]+g.ptr.p_double[2*i+1]*c.ptr.pp_double[klc][2*i+1];
                        vv = ae_sqr(c.ptr.pp_double[klc][2*i+0], _state)+ae_sqr(c.ptr.pp_double[klc][2*i+1], _state);
                        g.ptr.p_double[2*i+0] = g.ptr.p_double[2*i+0]-c.ptr.pp_double[klc][2*i+0]*(v/vv);
                        g.ptr.p_double[2*i+1] = g.ptr.p_double[2*i+1]-c.ptr.pp_double[klc][2*i+1]*(v/vv);
                        inc(&klc, _state);
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2582");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==4 )
                    {
                        
                        /*
                         * Linear inequality constrained, conditionally project gradient
                         * (when constraint is active)
                         */
                        v = x1.ptr.p_double[2*i+0]*c.ptr.pp_double[klc][2*i+0]+x1.ptr.p_double[2*i+1]*c.ptr.pp_double[klc][2*i+1]-c.ptr.pp_double[klc][n];
                        if( ae_fp_greater(v,-tolx) )
                        {
                            v = g.ptr.p_double[2*i+0]*c.ptr.pp_double[klc][2*i+0]+g.ptr.p_double[2*i+1]*c.ptr.pp_double[klc][2*i+1];
                            vv = ae_sqr(c.ptr.pp_double[klc][2*i+0], _state)+ae_sqr(c.ptr.pp_double[klc][2*i+1], _state);
                            g.ptr.p_double[2*i+0] = g.ptr.p_double[2*i+0]-c.ptr.pp_double[klc][2*i+0]*(v/vv);
                            g.ptr.p_double[2*i+1] = g.ptr.p_double[2*i+1]-c.ptr.pp_double[klc][2*i+1]*(v/vv);
                        }
                        inc(&klc, _state);
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2601");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==5 )
                    {
                        
                        /*
                         * Nonlinear equality constrained, unconditionally project gradient
                         *
                         * NOTE: here we rely on the fact that corresponding components of X
                         *       sum to one.
                         */
                        v = coalesce(ae_sqrt(ae_sqr(x1.ptr.p_double[2*i+0], _state)+ae_sqr(x1.ptr.p_double[2*i+1], _state), _state), 1.0, _state);
                        vx = x1.ptr.p_double[2*i+0]/v;
                        vy = x1.ptr.p_double[2*i+1]/v;
                        v = g.ptr.p_double[2*i+0]*vx+g.ptr.p_double[2*i+1]*vy;
                        g.ptr.p_double[2*i+0] = g.ptr.p_double[2*i+0]-vx*v;
                        g.ptr.p_double[2*i+1] = g.ptr.p_double[2*i+1]-vy*v;
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2619");
                        continue;
                    }
                    if( ckind.ptr.p_int[i]==6 )
                    {
                        
                        /*
                         * Nonlinear inequality constrained, conditionally project gradient
                         * (when constraint is active)
                         *
                         * NOTE: here we rely on the fact that corresponding components of X
                         *       sum to one.
                         */
                        v = ae_sqr(x1.ptr.p_double[2*i+0], _state)+ae_sqr(x1.ptr.p_double[2*i+1], _state)-rnlc.ptr.p_double[i];
                        if( ae_fp_greater(v,-tolx) )
                        {
                            v = coalesce(ae_sqrt(ae_sqr(x1.ptr.p_double[2*i+0], _state)+ae_sqr(x1.ptr.p_double[2*i+1], _state), _state), 1.0, _state);
                            vx = x1.ptr.p_double[2*i+0]/v;
                            vy = x1.ptr.p_double[2*i+1]/v;
                            v = g.ptr.p_double[2*i+0]*vx+g.ptr.p_double[2*i+1]*vy;
                            g.ptr.p_double[2*i+0] = g.ptr.p_double[2*i+0]-vx*v;
                            g.ptr.p_double[2*i+1] = g.ptr.p_double[2*i+1]-vy*v;
                        }
                        gnorm2 = gnorm2+ae_sqr(g.ptr.p_double[2*i+0], _state)+ae_sqr(g.ptr.p_double[2*i+1], _state);
                        ae_set_error_flag(wereerrors, ae_fp_greater(gnorm2,ae_sqr(tolg, _state)*ae_maxreal(rawgnorm2, 1.0, _state)), __FILE__, __LINE__, "testminnlcunit.ap:2642");
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
    }
    
    /*
     * Test a sequence of inequality constrained problems with varying N/NLIC and
     * known answer. The problem formulation is prepared as follows:
     * * first, we generate a solution point and active constraints with Lagrange
     *   multipliers of our choice; at least one constraint is active at the solution.
     * * then we select the target function to match our constraints
     * * finally, we add inactive constraints
     */
    rho = 1000.0;
    tolf = 0.002;
    aulits = 10;
    diffstep = 0.0001;
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        for(n=1; n<=10; n++)
        {
            for(cntnlic=1; cntnlic<=10; cntnlic++)
            {
                
                /*
                 * Create constraint matrix C that stores coefficients of quadratic
                 * constraints: first N columns store linear terms, next N columns
                 * store diagonal of the quadratic term, next column stores constant term.
                 */
                hqrndnormalv(&rs, n, &xref, _state);
                cntactive = 1+hqrnduniformi(&rs, n, _state);
                ae_matrix_set_length(&c, cntnlic, 2*n+1, _state);
                ae_vector_set_length(&lagmult, cntnlic, _state);
                rsetallocv(n, 0.0, &g, _state);
                for(i=0; i<=cntnlic-1; i++)
                {
                    
                    /*
                     * Generate linear and quadratic terms for a constraint, adjust its
                     * constant term depending on whether it is active or not
                     */
                    v = (double)(0);
                    for(j=0; j<=n-1; j++)
                    {
                        c.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                        c.ptr.pp_double[i][n+j] = ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
                        v = v+c.ptr.pp_double[i][j]*xref.ptr.p_double[j]+c.ptr.pp_double[i][n+j]*ae_sqr(xref.ptr.p_double[j], _state);
                    }
                    c.ptr.pp_double[i][2*n] = -v;
                    if( i<cntactive )
                    {
                        
                        /*
                         * Constraint is active, accumulate its gradient in G
                         */
                        lagmult.ptr.p_double[i] = 0.05+ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
                        for(j=0; j<=n-1; j++)
                        {
                            g.ptr.p_double[j] = g.ptr.p_double[j]+lagmult.ptr.p_double[i]*(c.ptr.pp_double[i][j]+(double)2*c.ptr.pp_double[i][n+j]*xref.ptr.p_double[j]);
                        }
                    }
                    else
                    {
                        
                        /*
                         * Constraint is inactive, adjust its constant term
                         */
                        lagmult.ptr.p_double[i] = 0.0;
                        c.ptr.pp_double[i][2*n] = c.ptr.pp_double[i][2*n]-0.1-ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
                    }
                }
                for(i=0; i<=cntnlic-1; i++)
                {
                    j = i+hqrnduniformi(&rs, cntnlic-i, _state);
                    if( j!=i )
                    {
                        swaprows(&c, i, j, 2*n+1, _state);
                        swapelements(&lagmult, i, j, _state);
                    }
                }
                
                /*
                 * Generate target function F that has gradient at XRef[] exactly equal to -G
                 */
                rallocv(n, &b, _state);
                rcopymulv(n, -1.0, &g, &b, _state);
                fref = rdotv(n, &b, &xref, _state);
                
                /*
                 * Solve the problem
                 */
                hqrndnormalv(&rs, n, &x0, _state);
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    minnlccreate(n, &x0, &state, _state);
                }
                else
                {
                    minnlccreatef(n, &x0, diffstep, &state, _state);
                }
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, rho, aulits, _state);
                    minnlcsetcond(&state, 1.0E-7, 0, _state);
                    prectype = hqrnduniformi(&rs, 3, _state);
                    if( prectype==0 )
                    {
                        minnlcsetprecinexact(&state, _state);
                    }
                    if( prectype==1 )
                    {
                        minnlcsetprecexactlowrank(&state, 0, _state);
                    }
                    if( prectype==2 )
                    {
                        minnlcsetprecexactrobust(&state, 0, _state);
                    }
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                        minnlcsetcond(&state, 1.0E-6, 0, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                            minnlcsetcond(&state, 1.0E-6, 0, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                minnlcsetnlc(&state, 0, cntnlic, _state);
                while(minnlciteration(&state, _state))
                {
                    if( state.needfi )
                    {
                        
                        /*
                         * Evaluate target function
                         */
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        }
                        
                        /*
                         * Evaluate constraint functions
                         */
                        k = 1;
                        for(i=0; i<=cntnlic-1; i++)
                        {
                            state.fi.ptr.p_double[k] = c.ptr.pp_double[i][2*n];
                            for(j=0; j<=n-1; j++)
                            {
                                state.fi.ptr.p_double[k] = state.fi.ptr.p_double[k]+c.ptr.pp_double[i][j]*state.x.ptr.p_double[j]+c.ptr.pp_double[i][n+j]*ae_sqr(state.x.ptr.p_double[j], _state);
                            }
                            k = k+1;
                        }
                        ae_assert(k==1+cntnlic, "Assertion failed", _state);
                        continue;
                    }
                    if( state.needfij )
                    {
                        
                        /*
                         * Evaluate target function
                         */
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                            state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        }
                        
                        /*
                         * Evaluate constraint functions
                         */
                        k = 1;
                        for(i=0; i<=cntnlic-1; i++)
                        {
                            state.fi.ptr.p_double[k] = c.ptr.pp_double[i][2*n];
                            for(j=0; j<=n-1; j++)
                            {
                                state.fi.ptr.p_double[k] = state.fi.ptr.p_double[k]+c.ptr.pp_double[i][j]*state.x.ptr.p_double[j]+c.ptr.pp_double[i][n+j]*ae_sqr(state.x.ptr.p_double[j], _state);
                                state.j.ptr.pp_double[k][j] = c.ptr.pp_double[i][j]+(double)2*c.ptr.pp_double[i][n+j]*state.x.ptr.p_double[j];
                            }
                            k = k+1;
                        }
                        ae_assert(k==1+cntnlic, "Assertion failed", _state);
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                minnlcresults(&state, &x1, &rep, _state);
                ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:2818");
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:2819");
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(fref-rdotv(n, &x1, &b, _state), _state),tolf*(rmaxabsv(n, &b, _state)+(double)1)), __FILE__, __LINE__, "testminnlcunit.ap:2824");
            }
        }
    }
    ae_frame_leave(_state);
}


/*************************************************************************
This function performs additional tests

On failure sets error flag.
*************************************************************************/
static void testminnlcunit_testother(ae_bool* wereerrors,
     ae_state *_state)
{
    ae_frame _frame_block;
    hqrndstate rs;
    double v;
    double h;
    double fl;
    double fr;
    double fl2;
    double fr2;
    double dfl;
    double dfr;
    double dfl2;
    double dfr2;
    double d2fl;
    double d2fr;
    double d2fl2;
    double d2fr2;
    double f0;
    double df;
    double d2f;
    double ndf;
    double nd2f;
    double dtol;
    double diffstep;
    minnlcstate state;
    minnlcreport rep;
    optguardreport ogrep;
    double rho;
    ae_int_t aulits;
    double tolx;
    ae_int_t i;
    ae_int_t j;
    ae_int_t k;
    ae_int_t n;
    ae_vector s;
    ae_vector b;
    ae_vector x0;
    ae_vector x1;
    ae_vector x2;
    ae_vector x3;
    ae_vector xlast;
    ae_vector bndl;
    ae_vector bndu;
    ae_vector xu;
    double condv;
    ae_matrix a;
    ae_matrix c;
    ae_matrix fulla;
    ae_vector ct;
    ae_int_t nlbfgs;
    ae_int_t nexactlowrank;
    ae_int_t nexactrobust;
    ae_int_t nnone;
    ae_int_t ctype;
    ae_int_t trialidx;
    ae_int_t blocksize;
    ae_int_t blockcnt;
    ae_int_t maxits;
    ae_int_t spoiliteration;
    ae_int_t stopiteration;
    ae_int_t spoilvar;
    double spoilval;
    ae_int_t pass;
    ae_int_t solvertype;
    ae_int_t badidx0;
    ae_int_t badidx1;
    ae_int_t nlec;
    ae_int_t nlic;
    double ss;
    ae_int_t stopcallidx;
    ae_int_t callidx;
    ae_bool terminationrequested;
    ae_bool firstrep;

    ae_frame_make(_state, &_frame_block);
    memset(&rs, 0, sizeof(rs));
    memset(&state, 0, sizeof(state));
    memset(&rep, 0, sizeof(rep));
    memset(&ogrep, 0, sizeof(ogrep));
    memset(&s, 0, sizeof(s));
    memset(&b, 0, sizeof(b));
    memset(&x0, 0, sizeof(x0));
    memset(&x1, 0, sizeof(x1));
    memset(&x2, 0, sizeof(x2));
    memset(&x3, 0, sizeof(x3));
    memset(&xlast, 0, sizeof(xlast));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&xu, 0, sizeof(xu));
    memset(&a, 0, sizeof(a));
    memset(&c, 0, sizeof(c));
    memset(&fulla, 0, sizeof(fulla));
    memset(&ct, 0, sizeof(ct));
    _hqrndstate_init(&rs, _state, ae_true);
    _minnlcstate_init(&state, _state, ae_true);
    _minnlcreport_init(&rep, _state, ae_true);
    _optguardreport_init(&ogrep, _state, ae_true);
    ae_vector_init(&s, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&b, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x1, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x2, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x3, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xlast, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xu, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&a, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&c, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&fulla, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&ct, 0, DT_INT, _state, ae_true);

    hqrndrandomize(&rs, _state);
    
    /*
     * Test equality penalty function (correctly calculated and smooth)
     */
    h = 1.0E-4;
    v = -0.98;
    dtol = 1.0E-3;
    while(ae_fp_less_eq(v,0.98))
    {
        
        /*
         * Test numerical derivative; this test also checks continuity of the
         * function
         */
        minnlcequalitypenaltyfunction(v-(double)2*h, &fl2, &dfl2, &d2fl2, _state);
        minnlcequalitypenaltyfunction(v-h, &fl, &dfl, &d2fl, _state);
        minnlcequalitypenaltyfunction(v+h, &fr, &dfr, &d2fr, _state);
        minnlcequalitypenaltyfunction(v+(double)2*h, &fr2, &dfr2, &d2fr2, _state);
        minnlcequalitypenaltyfunction(v, &f0, &df, &d2f, _state);
        ndf = (-fr2+(double)8*fr-(double)8*fl+fl2)/((double)12*h);
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(ndf-df, _state),dtol*ae_maxreal(ae_fabs(ndf, _state), (double)(1), _state)), __FILE__, __LINE__, "testminnlcunit.ap:2903");
        nd2f = (-dfr2+(double)8*dfr-(double)8*dfl+dfl2)/((double)12*h);
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(nd2f-d2f, _state),dtol*ae_maxreal(ae_fabs(nd2f, _state), (double)(1), _state)), __FILE__, __LINE__, "testminnlcunit.ap:2905");
        
        /*
         * Next point
         */
        v = v+h;
    }
    minnlcequalitypenaltyfunction(0.0, &f0, &df, &d2f, _state);
    ae_set_error_flag(wereerrors, ae_fp_neq(f0,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:2913");
    ae_set_error_flag(wereerrors, ae_fp_neq(df,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:2914");
    
    /*
     * Test inequality penalty function (correctly calculated and smooth)
     */
    h = 1.0E-4;
    v = 0.02;
    dtol = 1.0E-3;
    while(ae_fp_less_eq(v,2.00))
    {
        
        /*
         * Test numerical derivative; this test also checks continuity of the
         * function
         */
        minnlcinequalityshiftfunction(v-(double)2*h, &fl2, &dfl2, &d2fl2, _state);
        minnlcinequalityshiftfunction(v-h, &fl, &dfl, &d2fl, _state);
        minnlcinequalityshiftfunction(v+h, &fr, &dfr, &d2fr, _state);
        minnlcinequalityshiftfunction(v+(double)2*h, &fr2, &dfr2, &d2fr2, _state);
        minnlcinequalityshiftfunction(v, &f0, &df, &d2f, _state);
        ndf = (-fr2+(double)8*fr-(double)8*fl+fl2)/((double)12*h);
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(ndf-df, _state),dtol*ae_maxreal(ae_fabs(ndf, _state), (double)(1), _state)), __FILE__, __LINE__, "testminnlcunit.ap:2938");
        nd2f = (-dfr2+(double)8*dfr-(double)8*dfl+dfl2)/((double)12*h);
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(nd2f-d2f, _state),dtol*ae_maxreal(ae_fabs(nd2f, _state), (double)(1), _state)), __FILE__, __LINE__, "testminnlcunit.ap:2940");
        
        /*
         * Next point
         */
        v = v+h;
    }
    minnlcinequalityshiftfunction(1.0, &f0, &df, &d2f, _state);
    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(f0, _state),1.0E-6), __FILE__, __LINE__, "testminnlcunit.ap:2948");
    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(df+(double)1, _state),1.0E-6), __FILE__, __LINE__, "testminnlcunit.ap:2949");
    
    /*
     * Test different properties shared by all solvers
     */
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        
        /*
         * Test location reports
         */
        aulits = 50;
        rho = 200.0;
        n = 2;
        ae_vector_set_length(&x0, n, _state);
        ae_vector_set_length(&xlast, n, _state);
        x0.ptr.p_double[0] = 0.1+0.1*hqrnduniformr(&rs, _state);
        x0.ptr.p_double[1] = 0.2+0.1*hqrnduniformr(&rs, _state);
        xlast.ptr.p_double[0] = (double)(0);
        xlast.ptr.p_double[1] = (double)(0);
        firstrep = ae_true;
        minnlccreate(n, &x0, &state, _state);
        if( solvertype==0 )
        {
            minnlcsetalgoaul(&state, rho, aulits, _state);
        }
        else
        {
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
        minnlcsetcond(&state, 1.0E-7, 0, _state);
        minnlcsetnlc(&state, 0, 1, _state);
        minnlcsetxrep(&state, ae_true, _state);
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = ae_sqr(state.x.ptr.p_double[0]-(double)1, _state)+ae_sqr(state.x.ptr.p_double[1]-(double)1, _state);
                state.j.ptr.pp_double[0][0] = (double)2*(state.x.ptr.p_double[0]-(double)1);
                state.j.ptr.pp_double[0][1] = (double)2*(state.x.ptr.p_double[1]-(double)1);
                state.fi.ptr.p_double[1] = ae_sqr(state.x.ptr.p_double[0], _state)+ae_sqr(state.x.ptr.p_double[1], _state)-(double)1;
                state.j.ptr.pp_double[1][0] = (double)2*state.x.ptr.p_double[0];
                state.j.ptr.pp_double[1][1] = (double)2*state.x.ptr.p_double[1];
                continue;
            }
            if( state.xupdated )
            {
                
                /*
                 * If first point reported, compare with initial one
                 */
                if( firstrep )
                {
                    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(state.x.ptr.p_double[0]-x0.ptr.p_double[0], _state),1.0E4*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3002");
                    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(state.x.ptr.p_double[1]-x0.ptr.p_double[1], _state),1.0E4*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3003");
                }
                firstrep = ae_false;
                
                /*
                 * Save last point
                 */
                xlast.ptr.p_double[0] = state.x.ptr.p_double[0];
                xlast.ptr.p_double[1] = state.x.ptr.p_double[1];
                
                /*
                 * Done
                 */
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3021");
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3022");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[0]-xlast.ptr.p_double[0], _state),1.0E4*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3025");
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[1]-xlast.ptr.p_double[1], _state),1.0E4*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3026");
        
        /*
         * Test numerical differentiation
         */
        aulits = 50;
        rho = 200.0;
        tolx = 0.001;
        diffstep = 0.0001;
        n = 2;
        ae_vector_set_length(&x0, n, _state);
        x0.ptr.p_double[0] = 0.1;
        x0.ptr.p_double[1] = 0.2;
        minnlccreatef(n, &x0, diffstep, &state, _state);
        if( solvertype==0 )
        {
            minnlcsetalgoaul(&state, rho, aulits, _state);
        }
        else
        {
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
        minnlcsetcond(&state, 1.0E-7, 0, _state);
        minnlcsetnlc(&state, 0, 1, _state);
        while(minnlciteration(&state, _state))
        {
            if( state.needfi )
            {
                state.fi.ptr.p_double[0] = ae_sqr(state.x.ptr.p_double[0]-(double)1, _state)+ae_sqr(state.x.ptr.p_double[1]-(double)1, _state);
                state.fi.ptr.p_double[1] = ae_sqr(state.x.ptr.p_double[0], _state)+ae_sqr(state.x.ptr.p_double[1], _state)-(double)1;
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3062");
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3063");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[0]-ae_sqrt((double)(2), _state)/(double)2, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:3066");
        ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[1]-ae_sqrt((double)(2), _state)/(double)2, _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:3067");
        
        /*
         * Test integrity checks for NAN/INF:
         * * algorithm solves optimization problem, which is normal for some time (quadratic)
         * * after 5-th step we choose random component of gradient and consistently spoil
         *   it by NAN or INF.
         * * we check that correct termination code is returned (-8)
         */
        n = 100;
        for(pass=1; pass<=10; pass++)
        {
            spoiliteration = 5;
            stopiteration = 8;
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                
                /*
                 * Gradient can be spoiled by +INF, -INF, NAN
                 */
                spoilvar = hqrnduniformi(&rs, n, _state);
                i = hqrnduniformi(&rs, 3, _state);
                spoilval = _state->v_nan;
                if( i==0 )
                {
                    spoilval = _state->v_neginf;
                }
                if( i==1 )
                {
                    spoilval = _state->v_posinf;
                }
            }
            else
            {
                
                /*
                 * Function value can be spoiled only by NAN
                 * (+INF can be recognized as legitimate value during optimization)
                 */
                spoilvar = -1;
                spoilval = _state->v_nan;
            }
            spdmatrixrndcond(n, 1.0E5, &fulla, _state);
            ae_vector_set_length(&b, n, _state);
            ae_vector_set_length(&x0, n, _state);
            for(i=0; i<=n-1; i++)
            {
                b.ptr.p_double[i] = hqrndnormal(&rs, _state);
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
            }
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                aulits = 5;
                rho = 1.0E3;
                minnlcsetalgoaul(&state, rho, aulits, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 0.0, stopiteration, _state);
            minnlcsetxrep(&state, ae_true, _state);
            k = -1;
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    if( k>=spoiliteration )
                    {
                        if( spoilvar<0 )
                        {
                            state.fi.ptr.p_double[0] = spoilval;
                        }
                        else
                        {
                            state.j.ptr.pp_double[0][spoilvar] = spoilval;
                        }
                    }
                    continue;
                }
                if( state.xupdated )
                {
                    inc(&k, _state);
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, rep.terminationtype!=-8, __FILE__, __LINE__, "testminnlcunit.ap:3160");
        }
        
        /*
         * Test that optimizer respects box constraints in all
         * intermediate points:
         * * test that analytic Jacobian respects them
         * * test that numerical Jacobian respects them
         *
         * NOTE: we skip SolverType=0 (AUL) because AUL optimizer
         *       does not provide such guarantee
         */
        if( solvertype!=0 )
        {
            n = 10;
            spdmatrixrndcond(n, 1.0E3, &fulla, _state);
            ae_vector_set_length(&b, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_vector_set_length(&x0, n, _state);
            for(i=0; i<=n-1; i++)
            {
                b.ptr.p_double[i] = hqrndnormal(&rs, _state);
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    bndl.ptr.p_double[i] = (double)(0);
                    bndu.ptr.p_double[i] = _state->v_posinf;
                }
                else
                {
                    bndl.ptr.p_double[i] = _state->v_neginf;
                    bndu.ptr.p_double[i] = (double)(0);
                }
            }
            
            /*
             * Check analytic Jacobian
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetcond(&state, 1.0E-8, 0, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        ae_set_error_flag(wereerrors, ae_fp_less(state.x.ptr.p_double[i],bndl.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:3215");
                        ae_set_error_flag(wereerrors, ae_fp_greater(state.x.ptr.p_double[i],bndu.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:3216");
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3230");
            
            /*
             * Check numerical Jacobian
             */
            minnlccreatef(n, &x0, 1.0E-4, &state, _state);
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetcond(&state, 1.0E-8, 0, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfi )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        ae_set_error_flag(wereerrors, ae_fp_less(state.x.ptr.p_double[i],bndl.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:3251");
                        ae_set_error_flag(wereerrors, ae_fp_greater(state.x.ptr.p_double[i],bndu.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:3252");
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*fulla.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3262");
        }
        
        /*
         * Test constraint violation reports for completely unconstrained
         * problems and problems with all constraints being satisfied exactly
         */
        tolx = 0.01;
        for(pass=1; pass<=10; pass++)
        {
            n = 1+hqrnduniformi(&rs, 5, _state);
            ae_vector_set_length(&x0, n, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
            }
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 10, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 200, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_pow(state.x.ptr.p_double[i], (double)(4), _state);
                        state.j.ptr.pp_double[0][i] = (double)4*ae_pow(state.x.ptr.p_double[i], (double)(3), _state);
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            
            /*
             * Check solution itself
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3305");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3306");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            for(i=0; i<=n-1; i++)
            {
                ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(x1.ptr.p_double[i], _state),tolx), __FILE__, __LINE__, "testminnlcunit.ap:3310");
            }
            
            /*
             * Check constraint violation reports
             */
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3315");
            ae_set_error_flag(wereerrors, rep.bcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3316");
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.lcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3317");
            ae_set_error_flag(wereerrors, rep.lcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3318");
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.nlcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3319");
            ae_set_error_flag(wereerrors, rep.nlcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3320");
        }
        for(pass=1; pass<=10; pass++)
        {
            n = 1+hqrnduniformi(&rs, 5, _state);
            k = 1+hqrnduniformi(&rs, 5, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&xu, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_matrix_set_length(&c, k, n+1, _state);
            ae_vector_set_length(&ct, k, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                xu.ptr.p_double[i] = hqrndnormal(&rs, _state);
                bndl.ptr.p_double[i] = (double)(-1000);
                bndu.ptr.p_double[i] = (double)(1000);
            }
            for(i=0; i<=k-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                }
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    c.ptr.pp_double[i][n] = (double)(1000);
                    ct.ptr.p_int[i] = -1;
                }
                else
                {
                    c.ptr.pp_double[i][n] = (double)(-1000);
                    ct.ptr.p_int[i] = 1;
                }
            }
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 20, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetlc(&state, &c, &ct, k, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_pow(state.x.ptr.p_double[i]-xu.ptr.p_double[i], (double)(2), _state);
                        state.j.ptr.pp_double[0][i] = (double)2*(state.x.ptr.p_double[i]-xu.ptr.p_double[i]);
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            
            /*
             * Check solution itself, calculate reference violation values
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3385");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3386");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Check constraint violation reports
             */
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3393");
            ae_set_error_flag(wereerrors, rep.bcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3394");
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.lcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3395");
            ae_set_error_flag(wereerrors, rep.lcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3396");
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.nlcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3397");
            ae_set_error_flag(wereerrors, rep.nlcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3398");
        }
        
        /*
         * Test constraint violation reports for box/linearly constrained
         * problems. We generate a problem which can not satisfy one (and
         * just one) general linear constraint.
         */
        tolx = 0.001;
        for(pass=1; pass<=10; pass++)
        {
            
            /*
             * Formulate problem with inconsistent constraints
             */
            n = 2+hqrnduniformi(&rs, 5, _state);
            k = 1+hqrnduniformi(&rs, 5, _state);
            ae_vector_set_length(&s, n, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&xu, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_matrix_set_length(&c, k, n+1, _state);
            ae_vector_set_length(&ct, k, _state);
            for(i=0; i<=n-1; i++)
            {
                s.ptr.p_double[i] = ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                xu.ptr.p_double[i] = hqrndnormal(&rs, _state);
                bndl.ptr.p_double[i] = -0.5*hqrnduniformr(&rs, _state)-0.1;
                bndu.ptr.p_double[i] = 0.5*hqrnduniformr(&rs, _state)+0.1;
            }
            for(i=0; i<=k-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                }
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    c.ptr.pp_double[i][n] = (double)(1000);
                    ct.ptr.p_int[i] = -1;
                }
                else
                {
                    c.ptr.pp_double[i][n] = (double)(-1000);
                    ct.ptr.p_int[i] = 1;
                }
            }
            ae_assert(n>=2, "NLCTest: integrity check failed", _state);
            badidx0 = hqrnduniformi(&rs, k, _state);
            badidx1 = hqrnduniformi(&rs, n, _state);
            for(j=0; j<=n-1; j++)
            {
                c.ptr.pp_double[badidx0][j] = (double)(0);
            }
            for(j=0; j<=k-1; j++)
            {
                c.ptr.pp_double[j][badidx1] = (double)(0);
            }
            c.ptr.pp_double[badidx0][badidx1] = (double)(1);
            c.ptr.pp_double[badidx0][n] = (double)(10*(2*hqrnduniformi(&rs, 2, _state)-1));
            if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
            {
                ct.ptr.p_int[badidx0] = 0;
            }
            else
            {
                ct.ptr.p_int[badidx0] = ae_sign(c.ptr.pp_double[badidx0][n], _state);
            }
            
            /*
             * Create and try to solve
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 20, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetlc(&state, &c, &ct, k, _state);
            minnlcsetscale(&state, &s, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_pow(state.x.ptr.p_double[i]-xu.ptr.p_double[i], (double)(2), _state);
                        state.j.ptr.pp_double[0][i] = (double)2*(state.x.ptr.p_double[i]-xu.ptr.p_double[i]);
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            
            /*
             * Check solution itself, calculate reference violation values
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3493");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3494");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Check constraint violation reports
             */
            if( ae_fp_greater(rep.bcerr,(double)(0)) )
            {
                v = ae_maxreal(bndl.ptr.p_double[badidx1]-x1.ptr.p_double[badidx1], x1.ptr.p_double[badidx1]-bndu.ptr.p_double[badidx1], _state);
                v = v/s.ptr.p_double[badidx1];
                ae_set_error_flag(wereerrors, rep.bcidx!=badidx1, __FILE__, __LINE__, "testminnlcunit.ap:3505");
                ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(rep.bcerr-v, _state),1.0E3*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3507");
            }
            else
            {
                ae_set_error_flag(wereerrors, ae_fp_neq(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3512");
                ae_set_error_flag(wereerrors, rep.bcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3513");
                ae_set_error_flag(wereerrors, ae_fp_less(x1.ptr.p_double[badidx1],bndl.ptr.p_double[badidx1])||ae_fp_greater(x1.ptr.p_double[badidx1],bndu.ptr.p_double[badidx1]), __FILE__, __LINE__, "testminnlcunit.ap:3514");
            }
            ae_set_error_flag(wereerrors, rep.lcidx!=badidx0, __FILE__, __LINE__, "testminnlcunit.ap:3516");
            ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(rep.lcerr-ae_fabs(x1.ptr.p_double[badidx1]-c.ptr.pp_double[badidx0][n], _state)/s.ptr.p_double[badidx1], _state),1.0E3*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3517");
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.nlcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3518");
            ae_set_error_flag(wereerrors, rep.nlcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3519");
        }
        
        /*
         * Test constraint violation reports for box/nonlinearly constrained
         * problems. We generate a problem which can not satisfy one (and
         * just one) general linear constraint.
         *
         * NOTE: it is important to have N>=NLEC+NLIC
         */
        tolx = 0.001;
        for(pass=1; pass<=10; pass++)
        {
            
            /*
             * Formulate problem with inconsistent constraints
             */
            nlec = 1+hqrnduniformi(&rs, 5, _state);
            nlic = 1+hqrnduniformi(&rs, 5, _state);
            k = nlec+nlic;
            n = k+hqrnduniformi(&rs, 5, _state);
            ae_vector_set_length(&s, n, _state);
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&xu, n, _state);
            ae_vector_set_length(&bndl, n, _state);
            ae_vector_set_length(&bndu, n, _state);
            ae_matrix_set_length(&c, k, n+1, _state);
            for(i=0; i<=n-1; i++)
            {
                s.ptr.p_double[i] = ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                xu.ptr.p_double[i] = hqrndnormal(&rs, _state);
                bndl.ptr.p_double[i] = -0.5*hqrnduniformr(&rs, _state)-0.1;
                bndu.ptr.p_double[i] = 0.5*hqrnduniformr(&rs, _state)+0.1;
            }
            for(i=0; i<=nlec-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = (double)(0);
                }
                c.ptr.pp_double[i][i] = (double)(1);
                c.ptr.pp_double[i][n] = bndl.ptr.p_double[i]+hqrnduniformr(&rs, _state)*(bndu.ptr.p_double[i]-bndl.ptr.p_double[i]);
            }
            for(i=nlec; i<=k-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = (double)(0);
                }
                c.ptr.pp_double[i][i] = (double)(1);
                c.ptr.pp_double[i][n] = (double)(1000);
            }
            badidx0 = hqrnduniformi(&rs, k, _state);
            if( badidx0<nlec )
            {
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    c.ptr.pp_double[badidx0][n] = bndu.ptr.p_double[badidx0]+(double)10;
                }
                else
                {
                    c.ptr.pp_double[badidx0][n] = bndl.ptr.p_double[badidx0]-(double)10;
                }
            }
            else
            {
                c.ptr.pp_double[badidx0][n] = (double)(-1000);
            }
            
            /*
             * Create and try to solve
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 20, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetbc(&state, &bndl, &bndu, _state);
            minnlcsetnlc(&state, nlec, nlic, _state);
            minnlcsetscale(&state, &s, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_pow(state.x.ptr.p_double[i]-xu.ptr.p_double[i], (double)(2), _state);
                        state.j.ptr.pp_double[0][i] = (double)2*(state.x.ptr.p_double[i]-xu.ptr.p_double[i]);
                    }
                    for(i=0; i<=k-1; i++)
                    {
                        state.fi.ptr.p_double[i+1] = -c.ptr.pp_double[i][n];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[i+1] = state.fi.ptr.p_double[i+1]+c.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[i+1][j] = c.ptr.pp_double[i][j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            
            /*
             * Check solution itself, calculate reference violation values
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3622");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3623");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Check constraint violation reports
             */
            if( badidx0<nlec )
            {
                if( ae_fp_greater(rep.bcerr,(double)(0)) )
                {
                    v = ae_maxreal(bndl.ptr.p_double[badidx0]-x1.ptr.p_double[badidx0], x1.ptr.p_double[badidx0]-bndu.ptr.p_double[badidx0], _state);
                    v = v/s.ptr.p_double[badidx0];
                    ae_set_error_flag(wereerrors, rep.bcidx!=badidx0, __FILE__, __LINE__, "testminnlcunit.ap:3636");
                    ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(rep.bcerr-v, _state),1.0E3*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3638");
                }
                else
                {
                    ae_set_error_flag(wereerrors, ae_fp_neq(rep.bcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3643");
                    ae_set_error_flag(wereerrors, rep.bcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3644");
                    ae_set_error_flag(wereerrors, ae_fp_less(x1.ptr.p_double[badidx0],bndl.ptr.p_double[badidx0])||ae_fp_greater(x1.ptr.p_double[badidx0],bndu.ptr.p_double[badidx0]), __FILE__, __LINE__, "testminnlcunit.ap:3645");
                }
            }
            ae_set_error_flag(wereerrors, rep.lcidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:3648");
            ae_set_error_flag(wereerrors, ae_fp_neq(rep.lcerr,(double)(0)), __FILE__, __LINE__, "testminnlcunit.ap:3649");
            ae_set_error_flag(wereerrors, rep.nlcidx!=badidx0, __FILE__, __LINE__, "testminnlcunit.ap:3650");
            ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(rep.nlcerr-ae_fabs(x1.ptr.p_double[badidx0]-c.ptr.pp_double[badidx0][n], _state), _state),1.0E4*ae_machineepsilon), __FILE__, __LINE__, "testminnlcunit.ap:3651");
        }
        
        /*
         * Test support for termination requests:
         * * to terminate with correct return code = 8
         * * to return point which was "current" at the moment of termination
         */
        for(pass=1; pass<=50; pass++)
        {
            n = 3;
            ss = (double)(100);
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&xlast, n, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = (double)6+hqrnduniformr(&rs, _state);
            }
            stopcallidx = hqrnduniformi(&rs, 20, _state);
            maxits = 25;
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 20, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, (double)(0), maxits, _state);
            minnlcsetxrep(&state, ae_true, _state);
            callidx = 0;
            terminationrequested = ae_false;
            ae_v_move(&xlast.ptr.p_double[0], 1, &x0.ptr.p_double[0], 1, ae_v_len(0,n-1));
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = ss*ae_sqr(ae_exp(state.x.ptr.p_double[0], _state)-(double)2, _state)+ae_sqr(state.x.ptr.p_double[1], _state)+ae_sqr(state.x.ptr.p_double[2]-state.x.ptr.p_double[0], _state);
                    state.j.ptr.pp_double[0][0] = (double)2*ss*(ae_exp(state.x.ptr.p_double[0], _state)-(double)2)*ae_exp(state.x.ptr.p_double[0], _state)+(double)2*(state.x.ptr.p_double[2]-state.x.ptr.p_double[0])*(double)(-1);
                    state.j.ptr.pp_double[0][1] = (double)2*state.x.ptr.p_double[1];
                    state.j.ptr.pp_double[0][2] = (double)2*(state.x.ptr.p_double[2]-state.x.ptr.p_double[0]);
                    if( callidx==stopcallidx )
                    {
                        minnlcrequesttermination(&state, _state);
                        terminationrequested = ae_true;
                    }
                    inc(&callidx, _state);
                    continue;
                }
                if( state.xupdated )
                {
                    if( !terminationrequested )
                    {
                        ae_v_move(&xlast.ptr.p_double[0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, rep.terminationtype!=8, __FILE__, __LINE__, "testminnlcunit.ap:3708");
            for(i=0; i<=n-1; i++)
            {
                ae_set_error_flag(wereerrors, ae_fp_neq(x1.ptr.p_double[i],xlast.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:3710");
            }
        }
    }
    
    /*
     * AUL-specific test.
     *
     * Test preconditioning:
     * * compare number of iterations required to solve problem with
     *   different preconditioners (LBFGS, exact, none)
     * * a set of trials is performed (100 trials)
     * * each trial is a solution of boundary/linearly constrained problem
     *   (linear constraints may be posed as nonlinear ones) with normalized
     *   constraint matrix. Normalization is essential for reproducibility
     *   of results .
     *
     * Outer loop checks handling of different types of constraints
     * (posed as linear or nonlinear ones)
     */
    n = 30;
    blocksize = 3;
    blockcnt = 3;
    rho = 1.0E3;
    aulits = 5;
    condv = 1.0E2;
    ae_vector_set_length(&x0, n, _state);
    ae_vector_set_length(&bndl, n, _state);
    ae_vector_set_length(&bndu, n, _state);
    ae_matrix_set_length(&c, blocksize*blockcnt, n+1, _state);
    ae_vector_set_length(&ct, blocksize*blockcnt, _state);
    for(ctype=0; ctype<=1; ctype++)
    {
        
        /*
         * First, initialize iteration counters
         */
        nlbfgs = 0;
        nexactlowrank = 0;
        nexactrobust = 0;
        nnone = 0;
        
        /*
         * Perform trials
         */
        for(trialidx=0; trialidx<=99; trialidx++)
        {
            
            /*
             * Generate:
             * * boundary constraints BndL/BndU and initial point X0
             * * block-diagonal matrix of linear constraints C such
             *   that X0 is feasible w.r.t. constraints given by C
             */
            for(i=0; i<=n-1; i++)
            {
                if( ae_fp_greater(hqrndnormal(&rs, _state),(double)(0)) )
                {
                    bndl.ptr.p_double[i] = (double)(0);
                    bndu.ptr.p_double[i] = _state->v_posinf;
                    x0.ptr.p_double[i] = hqrnduniformr(&rs, _state);
                }
                else
                {
                    bndl.ptr.p_double[i] = (double)(0);
                    bndu.ptr.p_double[i] = (double)(0);
                    x0.ptr.p_double[i] = (double)(0);
                }
            }
            for(i=0; i<=blocksize*blockcnt-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = 0.0;
                }
            }
            for(k=0; k<=blockcnt-1; k++)
            {
                rmatrixrndcond(blocksize, condv, &a, _state);
                for(i=0; i<=blocksize-1; i++)
                {
                    for(j=0; j<=blocksize-1; j++)
                    {
                        c.ptr.pp_double[k*blocksize+i][k*blocksize+j] = a.ptr.pp_double[i][j];
                    }
                }
            }
            for(i=0; i<=blocksize*blockcnt-1; i++)
            {
                v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                v = (double)1/ae_sqrt(v, _state);
                ae_v_muld(&c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1), v);
                v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &x0.ptr.p_double[0], 1, ae_v_len(0,n-1));
                c.ptr.pp_double[i][n] = v;
                ct.ptr.p_int[i] = hqrnduniformi(&rs, 3, _state)-1;
            }
            
            /*
             * Test unpreconditioned iteration
             */
            minnlccreate(n, &x0, &state, _state);
            minnlcsetalgoaul(&state, rho, aulits, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            if( ctype==0 )
            {
                minnlcsetlc(&state, &c, &ct, blocksize*blockcnt, _state);
            }
            else
            {
                minnlcsetnlc(&state, blocksize*blockcnt, 0, _state);
            }
            minnlcsetprecnone(&state, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_sqr(state.x.ptr.p_double[i], _state);
                        state.j.ptr.pp_double[0][i] = (double)2*state.x.ptr.p_double[i];
                    }
                    if( ctype==1 )
                    {
                        for(i=0; i<=blocksize*blockcnt-1; i++)
                        {
                            v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                            state.fi.ptr.p_double[1+i] = v-c.ptr.pp_double[i][n];
                            ae_v_move(&state.j.ptr.pp_double[1+i][0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3834");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3835");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            nnone = nnone+rep.iterationscount;
            
            /*
             * Test LBFGS preconditioned iteration
             */
            minnlccreate(n, &x0, &state, _state);
            minnlcsetalgoaul(&state, rho, aulits, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            if( ctype==0 )
            {
                minnlcsetlc(&state, &c, &ct, blocksize*blockcnt, _state);
            }
            else
            {
                minnlcsetnlc(&state, blocksize*blockcnt, 0, _state);
            }
            minnlcsetprecinexact(&state, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_sqr(state.x.ptr.p_double[i], _state);
                        state.j.ptr.pp_double[0][i] = (double)2*state.x.ptr.p_double[i];
                    }
                    if( ctype==1 )
                    {
                        for(i=0; i<=blocksize*blockcnt-1; i++)
                        {
                            v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                            state.fi.ptr.p_double[1+i] = v-c.ptr.pp_double[i][n];
                            ae_v_move(&state.j.ptr.pp_double[1+i][0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3875");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3876");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            nlbfgs = nlbfgs+rep.iterationscount;
            
            /*
             * Test exact low rank preconditioner
             */
            minnlccreate(n, &x0, &state, _state);
            minnlcsetalgoaul(&state, rho, aulits, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            if( ctype==0 )
            {
                minnlcsetlc(&state, &c, &ct, blocksize*blockcnt, _state);
            }
            else
            {
                minnlcsetnlc(&state, blocksize*blockcnt, 0, _state);
            }
            minnlcsetprecexactlowrank(&state, 3, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_sqr(state.x.ptr.p_double[i], _state);
                        state.j.ptr.pp_double[0][i] = (double)2*state.x.ptr.p_double[i];
                    }
                    if( ctype==1 )
                    {
                        for(i=0; i<=blocksize*blockcnt-1; i++)
                        {
                            v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                            state.fi.ptr.p_double[1+i] = v-c.ptr.pp_double[i][n];
                            ae_v_move(&state.j.ptr.pp_double[1+i][0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3916");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3917");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            nexactlowrank = nexactlowrank+rep.iterationscount;
            
            /*
             * Test exact robust preconditioner
             */
            minnlccreate(n, &x0, &state, _state);
            minnlcsetalgoaul(&state, rho, aulits, _state);
            minnlcsetcond(&state, 1.0E-7, 0, _state);
            if( ctype==0 )
            {
                minnlcsetlc(&state, &c, &ct, blocksize*blockcnt, _state);
            }
            else
            {
                minnlcsetnlc(&state, blocksize*blockcnt, 0, _state);
            }
            minnlcsetprecexactrobust(&state, 3, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_sqr(state.x.ptr.p_double[i], _state);
                        state.j.ptr.pp_double[0][i] = (double)2*state.x.ptr.p_double[i];
                    }
                    if( ctype==1 )
                    {
                        for(i=0; i<=blocksize*blockcnt-1; i++)
                        {
                            v = ae_v_dotproduct(&c.ptr.pp_double[i][0], 1, &state.x.ptr.p_double[0], 1, ae_v_len(0,n-1));
                            state.fi.ptr.p_double[1+i] = v-c.ptr.pp_double[i][n];
                            ae_v_move(&state.j.ptr.pp_double[1+i][0], 1, &c.ptr.pp_double[i][0], 1, ae_v_len(0,n-1));
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:3957");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:3958");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            nexactrobust = nexactrobust+rep.iterationscount;
        }
        
        /*
         * Compare.
         *
         * Preconditioners must be significantly different,
         * with exact being best one, inexact being second,
         * "none" being worst option.
         */
        ae_set_error_flag(wereerrors, !ae_fp_less((double)(nexactlowrank),0.9*(double)nlbfgs), __FILE__, __LINE__, "testminnlcunit.ap:3971");
        ae_set_error_flag(wereerrors, !ae_fp_less((double)(nexactrobust),0.9*(double)nlbfgs), __FILE__, __LINE__, "testminnlcunit.ap:3972");
        ae_set_error_flag(wereerrors, !ae_fp_less((double)(nlbfgs),0.9*(double)nnone), __FILE__, __LINE__, "testminnlcunit.ap:3973");
    }
    ae_frame_leave(_state);
}


/*************************************************************************
This function tests OptGuard

On failure sets error flag.
*************************************************************************/
static void testminnlcunit_testoptguard(ae_bool* wereerrors,
     ae_state *_state)
{
    ae_frame _frame_block;
    hqrndstate rs;
    double v;
    minnlcstate state;
    minnlcreport rep;
    optguardreport ogrep;
    optguardnonc1test0report ognonc1test0strrep;
    optguardnonc1test0report ognonc1test0lngrep;
    optguardnonc1test1report ognonc1test1strrep;
    optguardnonc1test1report ognonc1test1lngrep;
    ae_int_t i;
    ae_int_t j;
    ae_int_t n;
    ae_matrix a;
    ae_matrix a1;
    ae_vector s;
    ae_vector x0;
    ae_vector x1;
    ae_vector xlast;
    ae_vector b;
    ae_vector bndl;
    ae_vector bndu;
    ae_vector xu;
    double diffstep;
    ae_int_t pass;
    ae_int_t solvertype;
    double vbnd;
    double fscale;
    ae_int_t defecttype;
    double vshift;
    double vpower;
    ae_int_t cntabove;
    ae_int_t cntbelow;
    ae_bool linesearchstarted;
    ae_bool wasgoodlinesearch0;
    ae_bool wasgoodlinesearch1;
    ae_int_t shortsessions;
    ae_int_t maxshortsessions;
    double stplen;
    double shortstplen;
    ae_bool failed;
    ae_int_t passcount;
    ae_int_t maxfails;
    ae_int_t failurecounter;
    ae_int_t maxc1test0fails;
    ae_int_t maxc1test1fails;
    ae_int_t c1test0fails;
    ae_int_t c1test1fails;
    ae_int_t goodidx;
    double avgstr0len;
    double avglng0len;
    double avgstr1len;
    double avglng1len;
    ae_int_t funcidx;
    ae_int_t varidx;
    ae_int_t skind;
    ae_matrix jactrue;
    ae_matrix jacdefect;

    ae_frame_make(_state, &_frame_block);
    memset(&rs, 0, sizeof(rs));
    memset(&state, 0, sizeof(state));
    memset(&rep, 0, sizeof(rep));
    memset(&ogrep, 0, sizeof(ogrep));
    memset(&ognonc1test0strrep, 0, sizeof(ognonc1test0strrep));
    memset(&ognonc1test0lngrep, 0, sizeof(ognonc1test0lngrep));
    memset(&ognonc1test1strrep, 0, sizeof(ognonc1test1strrep));
    memset(&ognonc1test1lngrep, 0, sizeof(ognonc1test1lngrep));
    memset(&a, 0, sizeof(a));
    memset(&a1, 0, sizeof(a1));
    memset(&s, 0, sizeof(s));
    memset(&x0, 0, sizeof(x0));
    memset(&x1, 0, sizeof(x1));
    memset(&xlast, 0, sizeof(xlast));
    memset(&b, 0, sizeof(b));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&xu, 0, sizeof(xu));
    memset(&jactrue, 0, sizeof(jactrue));
    memset(&jacdefect, 0, sizeof(jacdefect));
    _hqrndstate_init(&rs, _state, ae_true);
    _minnlcstate_init(&state, _state, ae_true);
    _minnlcreport_init(&rep, _state, ae_true);
    _optguardreport_init(&ogrep, _state, ae_true);
    _optguardnonc1test0report_init(&ognonc1test0strrep, _state, ae_true);
    _optguardnonc1test0report_init(&ognonc1test0lngrep, _state, ae_true);
    _optguardnonc1test1report_init(&ognonc1test1strrep, _state, ae_true);
    _optguardnonc1test1report_init(&ognonc1test1lngrep, _state, ae_true);
    ae_matrix_init(&a, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&a1, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&s, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x1, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xlast, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&b, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&xu, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&jactrue, 0, 0, DT_REAL, _state, ae_true);
    ae_matrix_init(&jacdefect, 0, 0, DT_REAL, _state, ae_true);

    hqrndrandomize(&rs, _state);
    
    /*
     * Test functionality which should work in all NLC solvers
     */
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        
        /*
         * Check that gradient verification is disabled by default:
         * gradient checking for bad problem must return nothing
         */
        n = 10;
        ae_vector_set_length(&x0, n, _state);
        for(i=0; i<=n-1; i++)
        {
            x0.ptr.p_double[i] = 1.0+0.1*(double)i;
        }
        spdmatrixrndcond(n, 1.0E3, &a, _state);
        spdmatrixrndcond(n, 1.0E3, &a1, _state);
        minnlccreate(n, &x0, &state, _state);
        if( solvertype==0 )
        {
            minnlcsetalgoaul(&state, 1000.0, 5, _state);
        }
        else
        {
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
        minnlcsetcond(&state, 1.0E-7, 10, _state);
        minnlcsetnlc(&state, 0, 1, _state);
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = (double)(0);
                for(i=0; i<=n-1; i++)
                {
                    v = (double)(0);
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+state.x.ptr.p_double[j]*a.ptr.pp_double[i][j];
                    }
                    state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*v;
                }
                state.fi.ptr.p_double[1] = (double)(0);
                for(i=0; i<=n-1; i++)
                {
                    v = (double)(0);
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+state.x.ptr.p_double[j]*a1.ptr.pp_double[i][j];
                    }
                    state.fi.ptr.p_double[1] = state.fi.ptr.p_double[1]+0.5*state.x.ptr.p_double[i]*v;
                }
                for(i=0; i<=n-1; i++)
                {
                    state.j.ptr.pp_double[0][i] = (double)(0);
                    state.j.ptr.pp_double[1][i] = (double)(0);
                }
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        minnlcoptguardresults(&state, &ogrep, _state);
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4085");
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4086");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ogrep.badgradxbase.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:4089");
        ae_set_error_flag(wereerrors, ogrep.badgraduser.rows!=0, __FILE__, __LINE__, "testminnlcunit.ap:4090");
        ae_set_error_flag(wereerrors, ogrep.badgraduser.cols!=0, __FILE__, __LINE__, "testminnlcunit.ap:4091");
        ae_set_error_flag(wereerrors, ogrep.badgradnum.rows!=0, __FILE__, __LINE__, "testminnlcunit.ap:4092");
        ae_set_error_flag(wereerrors, ogrep.badgradnum.cols!=0, __FILE__, __LINE__, "testminnlcunit.ap:4093");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ogrep.badgradsuspected, __FILE__, __LINE__, "testminnlcunit.ap:4096");
        ae_set_error_flag(wereerrors, ogrep.badgradfidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:4097");
        ae_set_error_flag(wereerrors, ogrep.badgradvidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:4098");
        
        /*
         * Test that C0/C1 continuity monitoring is disabled by default;
         * we solve nonsmooth problem and test that nothing is returned
         * by OptGuard.
         */
        n = 10;
        ae_vector_set_length(&x0, n, _state);
        for(i=0; i<=n-1; i++)
        {
            x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
        }
        ae_matrix_set_length(&a, n, n, _state);
        for(i=0; i<=n-1; i++)
        {
            for(j=0; j<=n-1; j++)
            {
                a.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
            }
        }
        minnlccreate(n, &x0, &state, _state);
        if( solvertype==0 )
        {
            minnlcsetalgoaul(&state, 1000.0, 1, _state);
        }
        else
        {
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
        minnlcsetcond(&state, 1.0E-9, 50, _state);
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = (double)(0);
                for(i=0; i<=n-1; i++)
                {
                    state.j.ptr.pp_double[0][i] = (double)(0);
                }
                for(i=0; i<=n-1; i++)
                {
                    v = (double)(0);
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+state.x.ptr.p_double[j]*a.ptr.pp_double[i][j];
                    }
                    state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_fabs(v, _state);
                    v = (double)(ae_sign(v, _state));
                    for(j=0; j<=n-1; j++)
                    {
                        state.j.ptr.pp_double[0][j] = state.j.ptr.pp_double[0][j]+v*a.ptr.pp_double[i][j];
                    }
                }
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        minnlcoptguardresults(&state, &ogrep, _state);
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4146");
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4147");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ogrep.nonc0suspected, __FILE__, __LINE__, "testminnlcunit.ap:4150");
        ae_set_error_flag(wereerrors, ogrep.nonc1suspected, __FILE__, __LINE__, "testminnlcunit.ap:4151");
        ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:4152");
        ae_set_error_flag(wereerrors, ogrep.nonc0fidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:4153");
        ae_set_error_flag(wereerrors, ogrep.nonc1fidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:4154");
        ae_set_error_flag(wereerrors, ogrep.nonc1test0positive, __FILE__, __LINE__, "testminnlcunit.ap:4155");
        ae_set_error_flag(wereerrors, ogrep.nonc1test1positive, __FILE__, __LINE__, "testminnlcunit.ap:4156");
        
        /*
         * Test gradient checking functionality, try various
         * defect types:
         * * accidental zeroing of some gradient component
         * * accidental addition of 1.0 to some component
         * * accidental multiplication by 2.0
         * Try distorting both target and constraints.
         */
        diffstep = 0.001;
        n = 10;
        for(skind=0; skind<=1; skind++)
        {
            for(funcidx=0; funcidx<=1; funcidx++)
            {
                for(defecttype=-1; defecttype<=2; defecttype++)
                {
                    varidx = hqrnduniformi(&rs, n, _state);
                    ae_vector_set_length(&x0, n, _state);
                    ae_vector_set_length(&s, n, _state);
                    ae_vector_set_length(&bndl, n, _state);
                    ae_vector_set_length(&bndu, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        s.ptr.p_double[i] = ae_pow((double)(10), (double)skind*((double)30*hqrnduniformr(&rs, _state)-(double)15), _state);
                        x0.ptr.p_double[i] = (1.0+0.1*(double)i)*s.ptr.p_double[i];
                        j = hqrnduniformi(&rs, 3, _state);
                        bndl.ptr.p_double[i] = -(double)100*s.ptr.p_double[i];
                        bndu.ptr.p_double[i] = (double)100*s.ptr.p_double[i];
                        if( j==1 )
                        {
                            bndl.ptr.p_double[i] = x0.ptr.p_double[i];
                        }
                        if( j==2 )
                        {
                            bndu.ptr.p_double[i] = x0.ptr.p_double[i];
                        }
                    }
                    spdmatrixrndcond(n, 1.0E3, &a, _state);
                    spdmatrixrndcond(n, 1.0E3, &a1, _state);
                    minnlccreate(n, &x0, &state, _state);
                    if( solvertype==0 )
                    {
                        minnlcsetalgoaul(&state, 1000.0, 5, _state);
                    }
                    else
                    {
                        if( solvertype==1 )
                        {
                            minnlcsetalgoslp(&state, _state);
                        }
                        else
                        {
                            if( solvertype==2 )
                            {
                                minnlcsetalgosqp(&state, _state);
                            }
                            else
                            {
                                ae_assert(ae_false, "Assertion failed", _state);
                            }
                        }
                    }
                    minnlcoptguardgradient(&state, diffstep, _state);
                    minnlcsetcond(&state, 1.0E-7, 10, _state);
                    minnlcsetscale(&state, &s, _state);
                    minnlcsetbc(&state, &bndl, &bndu, _state);
                    minnlcsetnlc(&state, 0, 1, _state);
                    while(minnlciteration(&state, _state))
                    {
                        if( state.needfij )
                        {
                            if( solvertype!=0 )
                            {
                                for(i=0; i<=n-1; i++)
                                {
                                    ae_set_error_flag(wereerrors, ae_fp_less(state.x.ptr.p_double[i],bndl.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:4216");
                                    ae_set_error_flag(wereerrors, ae_fp_greater(state.x.ptr.p_double[i],bndu.ptr.p_double[i]), __FILE__, __LINE__, "testminnlcunit.ap:4217");
                                }
                            }
                            state.fi.ptr.p_double[0] = (double)(0);
                            for(i=0; i<=n-1; i++)
                            {
                                v = (double)(0);
                                for(j=0; j<=n-1; j++)
                                {
                                    v = v+state.x.ptr.p_double[j]/s.ptr.p_double[j]*a.ptr.pp_double[i][j];
                                }
                                state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*(state.x.ptr.p_double[i]/s.ptr.p_double[i])*v;
                                state.j.ptr.pp_double[0][i] = v;
                            }
                            state.fi.ptr.p_double[1] = (double)(0);
                            for(i=0; i<=n-1; i++)
                            {
                                v = (double)(0);
                                for(j=0; j<=n-1; j++)
                                {
                                    v = v+state.x.ptr.p_double[j]/s.ptr.p_double[j]*a1.ptr.pp_double[i][j];
                                }
                                state.fi.ptr.p_double[1] = state.fi.ptr.p_double[1]+0.5*(state.x.ptr.p_double[i]/s.ptr.p_double[i])*v;
                                state.j.ptr.pp_double[1][i] = v;
                            }
                            if( defecttype==0 )
                            {
                                state.j.ptr.pp_double[funcidx][varidx] = (double)(0);
                            }
                            if( defecttype==1 )
                            {
                                state.j.ptr.pp_double[funcidx][varidx] = state.j.ptr.pp_double[funcidx][varidx]+(double)1;
                            }
                            if( defecttype==2 )
                            {
                                state.j.ptr.pp_double[funcidx][varidx] = state.j.ptr.pp_double[funcidx][varidx]*(double)2;
                            }
                            for(i=0; i<=n-1; i++)
                            {
                                state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]/s.ptr.p_double[i];
                                state.j.ptr.pp_double[1][i] = state.j.ptr.pp_double[1][i]/s.ptr.p_double[i];
                            }
                            continue;
                        }
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                    minnlcresults(&state, &x1, &rep, _state);
                    minnlcoptguardresults(&state, &ogrep, _state);
                    
                    /*
                     * Check that something is returned
                     */
                    ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4267");
                    ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4268");
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    
                    /*
                     * Compute reference values for true and spoiled Jacobian at X0
                     */
                    ae_set_error_flag(wereerrors, !isfinitevector(&ogrep.badgradxbase, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4275");
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    ae_matrix_set_length(&jactrue, 2, n, _state);
                    ae_matrix_set_length(&jacdefect, 2, n, _state);
                    for(i=0; i<=n-1; i++)
                    {
                        v = (double)(0);
                        for(j=0; j<=n-1; j++)
                        {
                            v = v+ogrep.badgradxbase.ptr.p_double[j]/s.ptr.p_double[j]*a.ptr.pp_double[i][j];
                        }
                        jactrue.ptr.pp_double[0][i] = v;
                        jacdefect.ptr.pp_double[0][i] = v;
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        v = (double)(0);
                        for(j=0; j<=n-1; j++)
                        {
                            v = v+ogrep.badgradxbase.ptr.p_double[j]/s.ptr.p_double[j]*a1.ptr.pp_double[i][j];
                        }
                        jactrue.ptr.pp_double[1][i] = v;
                        jacdefect.ptr.pp_double[1][i] = v;
                    }
                    if( defecttype==0 )
                    {
                        jacdefect.ptr.pp_double[funcidx][varidx] = (double)(0);
                    }
                    if( defecttype==1 )
                    {
                        jacdefect.ptr.pp_double[funcidx][varidx] = jacdefect.ptr.pp_double[funcidx][varidx]+(double)1;
                    }
                    if( defecttype==2 )
                    {
                        jacdefect.ptr.pp_double[funcidx][varidx] = jacdefect.ptr.pp_double[funcidx][varidx]*(double)2;
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        jactrue.ptr.pp_double[0][i] = jactrue.ptr.pp_double[0][i]/s.ptr.p_double[i];
                        jactrue.ptr.pp_double[1][i] = jactrue.ptr.pp_double[1][i]/s.ptr.p_double[i];
                        jacdefect.ptr.pp_double[0][i] = jacdefect.ptr.pp_double[0][i]/s.ptr.p_double[i];
                        jacdefect.ptr.pp_double[1][i] = jacdefect.ptr.pp_double[1][i]/s.ptr.p_double[i];
                    }
                    
                    /*
                     * Check OptGuard report
                     */
                    ae_set_error_flag(wereerrors, !apservisfinitematrix(&ogrep.badgraduser, 2, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4313");
                    ae_set_error_flag(wereerrors, !apservisfinitematrix(&ogrep.badgradnum, 2, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4314");
                    if( *wereerrors )
                    {
                        ae_frame_leave(_state);
                        return;
                    }
                    if( defecttype>=0 )
                    {
                        ae_set_error_flag(wereerrors, !ogrep.badgradsuspected, __FILE__, __LINE__, "testminnlcunit.ap:4319");
                        ae_set_error_flag(wereerrors, ogrep.badgradfidx!=funcidx, __FILE__, __LINE__, "testminnlcunit.ap:4320");
                        ae_set_error_flag(wereerrors, ogrep.badgradvidx!=varidx, __FILE__, __LINE__, "testminnlcunit.ap:4321");
                    }
                    else
                    {
                        ae_set_error_flag(wereerrors, ogrep.badgradsuspected, __FILE__, __LINE__, "testminnlcunit.ap:4325");
                        ae_set_error_flag(wereerrors, ogrep.badgradfidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:4326");
                        ae_set_error_flag(wereerrors, ogrep.badgradvidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:4327");
                    }
                    for(i=0; i<=1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(jactrue.ptr.pp_double[i][j]-ogrep.badgradnum.ptr.pp_double[i][j], _state),0.01/s.ptr.p_double[j]), __FILE__, __LINE__, "testminnlcunit.ap:4332");
                            ae_set_error_flag(wereerrors, ae_fp_greater(ae_fabs(jacdefect.ptr.pp_double[i][j]-ogrep.badgraduser.ptr.pp_double[i][j], _state),0.01/s.ptr.p_double[j]), __FILE__, __LINE__, "testminnlcunit.ap:4333");
                        }
                    }
                }
            }
        }
        
        /*
         * Make sure than no false positives are reported for larger
         * problems where numerical noise can be an issue:
         * * N=100 dimensions
         * * nonnegativity constraints
         * * positive-definite quadratic programming problem
         * * upper limit on iterations count, MaxIts=25
         * We simply test that OptGuard does not return error code.
         */
        n = 100;
        spdmatrixrndcond(n, 1.0E2, &a, _state);
        ae_vector_set_length(&b, n, _state);
        ae_vector_set_length(&bndl, n, _state);
        ae_vector_set_length(&bndu, n, _state);
        ae_vector_set_length(&x0, n, _state);
        for(i=0; i<=n-1; i++)
        {
            b.ptr.p_double[i] = hqrndnormal(&rs, _state);
            bndl.ptr.p_double[i] = (double)(0);
            bndu.ptr.p_double[i] = _state->v_posinf;
            x0.ptr.p_double[i] = ae_pow(2.0, hqrndnormal(&rs, _state), _state);
        }
        minnlccreate(n, &x0, &state, _state);
        if( solvertype==0 )
        {
            minnlcsetalgoaul(&state, 1000.0, 3, _state);
        }
        else
        {
            if( solvertype==1 )
            {
                minnlcsetalgoslp(&state, _state);
            }
            else
            {
                if( solvertype==2 )
                {
                    minnlcsetalgosqp(&state, _state);
                }
                else
                {
                    ae_assert(ae_false, "Assertion failed", _state);
                }
            }
        }
        minnlcoptguardsmoothness(&state, 1+hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel, _state), _state);
        minnlcsetbc(&state, &bndl, &bndu, _state);
        minnlcsetcond(&state, 1.0E-7, 25, _state);
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = (double)(0);
                for(i=0; i<=n-1; i++)
                {
                    state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                    state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                    for(j=0; j<=n-1; j++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*state.x.ptr.p_double[i]*a.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]+a.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                    }
                }
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4391");
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4392");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        minnlcoptguardresults(&state, &ogrep, _state);
        ae_set_error_flag(wereerrors, !optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:4396");
    }
    
    /*
     * Test functionality which works only in some NLC solvers
     */
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        
        /*
         * Skip
         */
        if( solvertype==2 )
        {
            continue;
        }
        
        /*
         * Test detection of discontinuities in the target function
         * and its gradient (analytic gradient is used).
         *
         * Target function is convex quadratic modified by addition of
         * nonsmooth/discontinuous (depending on DefectType) perturbation.
         *
         * This test is complicated because OptGuard does NOT guarantee
         * that C0/C1 violations are ALWAYS caught. OptGuard needs line
         * search to perform
         * * at least 4 function evaluations, with discontinuity in the
         *   middle of them (at least two function values from the left,
         *   at least two from the right)
         * * at least 7 function evaluations to catch C1 violation
         *
         * Furthermore, it is possible that optimizer will perform a few
         * function evaluations BEFORE and AFTER line search starts,
         * which complicates everything.
         *
         * N, VPower and VBnd are selected randomly at the start of the test.
         */
        for(defecttype=0; defecttype<=1; defecttype++)
        {
            n = 1+hqrnduniformi(&rs, 10, _state);
            vpower = (double)10*ae_pow((double)(10), -0.2*hqrnduniformr(&rs, _state), _state);
            vbnd = (double)1*ae_pow((double)(10), -0.2*hqrnduniformr(&rs, _state), _state);
            fscale = 0.1;
            maxshortsessions = 4;
            shortstplen = 1.0E-6;
            shortsessions = 0;
            for(pass=1; pass<=100; pass++)
            {
                
                /*
                 * Formulate problem
                 */
                ae_vector_set_length(&s, n, _state);
                ae_vector_set_length(&xlast, n, _state);
                ae_vector_set_length(&x0, n, _state);
                ae_vector_set_length(&xu, n, _state);
                ae_vector_set_length(&bndl, n, _state);
                ae_vector_set_length(&bndu, n, _state);
                do
                {
                    v = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        xu.ptr.p_double[i] = 0.1+hqrnduniformr(&rs, _state);
                        v = v+ae_sqr(xu.ptr.p_double[i], _state);
                    }
                    v = ae_sqrt(v, _state);
                }
                while(ae_fp_less_eq(v,(double)(0)));
                for(i=0; i<=n-1; i++)
                {
                    xu.ptr.p_double[i] = xu.ptr.p_double[i]/v;
                }
                for(i=0; i<=n-1; i++)
                {
                    xlast.ptr.p_double[i] = (double)(0);
                    x0.ptr.p_double[i] = (double)2*xu.ptr.p_double[i]+0.1*hqrnduniformr(&rs, _state);
                    bndl.ptr.p_double[i] = 0.0;
                    bndu.ptr.p_double[i] = _state->v_posinf;
                    s.ptr.p_double[i] = ae_pow((double)(2), 0.1*hqrndnormal(&rs, _state), _state);
                }
                if( defecttype==0 )
                {
                    vshift = (double)(1);
                }
                else
                {
                    vshift = (double)(0);
                }
                
                /*
                 * Prepare code which detects "good" (long enough) line searches
                 */
                cntbelow = 0;
                cntabove = 0;
                wasgoodlinesearch0 = ae_false;
                wasgoodlinesearch1 = ae_false;
                linesearchstarted = ae_false;
                
                /*
                 * Create and try to solve
                 */
                minnlccreate(n, &x0, &state, _state);
                if( solvertype==0 )
                {
                    minnlcsetalgoaul(&state, 1000.0, 5, _state);
                }
                else
                {
                    if( solvertype==1 )
                    {
                        minnlcsetalgoslp(&state, _state);
                    }
                    else
                    {
                        if( solvertype==2 )
                        {
                            minnlcsetalgosqp(&state, _state);
                        }
                        else
                        {
                            ae_assert(ae_false, "Assertion failed", _state);
                        }
                    }
                }
                minnlcsetbc(&state, &bndl, &bndu, _state);
                minnlcsetscale(&state, &s, _state);
                minnlcsetcond(&state, 1.0E-7, 1000, _state);
                minnlcoptguardsmoothness(&state, 1+hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel, _state), _state);
                minnlcsetxrep(&state, ae_true, _state);
                while(minnlciteration(&state, _state))
                {
                    if( state.needfij )
                    {
                        state.fi.ptr.p_double[0] = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+fscale*ae_pow(state.x.ptr.p_double[i], (double)(2), _state);
                            state.j.ptr.pp_double[0][i] = (double)2*fscale*state.x.ptr.p_double[i];
                        }
                        v = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            v = v+state.x.ptr.p_double[i]*xu.ptr.p_double[i];
                        }
                        if( ae_fp_less(v,vbnd) )
                        {
                            state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+(vshift+vpower*(vbnd-v));
                            for(i=0; i<=n-1; i++)
                            {
                                state.j.ptr.pp_double[0][i] = state.j.ptr.pp_double[0][i]-vpower*xu.ptr.p_double[i];
                            }
                            if( linesearchstarted )
                            {
                                inc(&cntbelow, _state);
                            }
                        }
                        else
                        {
                            if( linesearchstarted )
                            {
                                inc(&cntabove, _state);
                            }
                        }
                        continue;
                    }
                    if( state.xupdated )
                    {
                        
                        /*
                         * Finalize previous line search
                         */
                        if( linesearchstarted )
                        {
                            stplen = (double)(0);
                            for(i=0; i<=n-1; i++)
                            {
                                stplen = stplen+ae_sqr(state.x.ptr.p_double[i]-xlast.ptr.p_double[i], _state);
                            }
                            stplen = ae_sqrt(stplen, _state);
                            wasgoodlinesearch0 = wasgoodlinesearch0||((cntbelow>=2&&cntabove>=2)&&ae_fp_greater_eq(stplen,shortstplen));
                            wasgoodlinesearch1 = wasgoodlinesearch1||((cntbelow>=2&&cntabove>=2)&&ae_fp_greater_eq(stplen,shortstplen));
                        }
                        
                        /*
                         * Start new line search
                         */
                        linesearchstarted = ae_true;
                        cntbelow = 0;
                        cntabove = 0;
                        for(i=0; i<=n-1; i++)
                        {
                            xlast.ptr.p_double[i] = state.x.ptr.p_double[i];
                        }
                        v = (double)(0);
                        for(i=0; i<=n-1; i++)
                        {
                            v = v+state.x.ptr.p_double[i]*xu.ptr.p_double[i];
                        }
                        if( ae_fp_less(v,vbnd) )
                        {
                            inc(&cntbelow, _state);
                        }
                        else
                        {
                            inc(&cntabove, _state);
                        }
                        
                        /*
                         * Done
                         */
                        continue;
                    }
                    ae_assert(ae_false, "Assertion failed", _state);
                }
                minnlcresults(&state, &x1, &rep, _state);
                minnlcoptguardresults(&state, &ogrep, _state);
                
                /*
                 * Check basic properties of the solution
                 */
                ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4573");
                ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4574");
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
                
                /*
                 * Check OptGuard report, increase
                 */
                if( defecttype==0 )
                {
                    if( wasgoodlinesearch0 )
                    {
                        ae_set_error_flag(wereerrors, optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:4585");
                        ae_set_error_flag(wereerrors, !ogrep.nonc0suspected, __FILE__, __LINE__, "testminnlcunit.ap:4586");
                        ae_set_error_flag(wereerrors, ogrep.nonc0fidx!=0, __FILE__, __LINE__, "testminnlcunit.ap:4587");
                    }
                    else
                    {
                        inc(&shortsessions, _state);
                    }
                }
                if( defecttype==1 )
                {
                    if( wasgoodlinesearch1 )
                    {
                        ae_set_error_flag(wereerrors, optguardallclear(&ogrep, _state), __FILE__, __LINE__, "testminnlcunit.ap:4596");
                        ae_set_error_flag(wereerrors, !ogrep.nonc1suspected, __FILE__, __LINE__, "testminnlcunit.ap:4597");
                        ae_set_error_flag(wereerrors, ogrep.nonc1fidx!=0, __FILE__, __LINE__, "testminnlcunit.ap:4598");
                    }
                    else
                    {
                        inc(&shortsessions, _state);
                    }
                }
                if( *wereerrors )
                {
                    ae_frame_leave(_state);
                    return;
                }
            }
            
            /*
             * Check that short optimization sessions are rare.
             */
            ae_set_error_flag(wereerrors, shortsessions>maxshortsessions, __FILE__, __LINE__, "testminnlcunit.ap:4610");
        }
        
        /*
         * One more test for detection of C1 continuity violations in the target.
         *
         * Target function is a sum of |(x,c_i)| for i=1..N.
         * No constraints is present.
         * Analytic gradient is provided.
         *
         * OptGuard should be able to detect violations in more than
         * 99.9% of runs; it means that 100 runs should have no more than 4
         * failures in all cases (even after multiple repeated tests; according
         * to the binomial distribution quantiles).
         *
         * We select some N and perform exhaustive search for this N.
         *
         * NOTE: we skip SQP for this test
         */
        passcount = 100;
        maxfails = 4;
        maxc1test0fails = 10;
        maxc1test1fails = 10;
        n = 1+hqrnduniformi(&rs, 10, _state);
        failurecounter = 0;
        c1test0fails = 0;
        c1test1fails = 0;
        avgstr0len = (double)(0);
        avglng0len = (double)(0);
        avgstr1len = (double)(0);
        avglng1len = (double)(0);
        for(pass=1; pass<=passcount; pass++)
        {
            
            /*
             * Formulate problem
             */
            ae_vector_set_length(&x0, n, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
            }
            ae_vector_set_length(&s, n, _state);
            for(i=0; i<=n-1; i++)
            {
                s.ptr.p_double[i] = ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
            }
            ae_matrix_set_length(&a, n, n, _state);
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    a.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                }
            }
            
            /*
             * Create and try to solve
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 1, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 50, _state);
            minnlcsetscale(&state, &s, _state);
            minnlcoptguardsmoothness(&state, 1+hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel, _state), _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.j.ptr.pp_double[0][i] = (double)(0);
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        v = (double)(0);
                        for(j=0; j<=n-1; j++)
                        {
                            v = v+state.x.ptr.p_double[j]*a.ptr.pp_double[i][j];
                        }
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_fabs(v, _state);
                        v = (double)(ae_sign(v, _state));
                        for(j=0; j<=n-1; j++)
                        {
                            state.j.ptr.pp_double[0][j] = state.j.ptr.pp_double[0][j]+v*a.ptr.pp_double[i][j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            minnlcoptguardresults(&state, &ogrep, _state);
            
            /*
             * Check basic properties of the solution
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4700");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4701");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Check generic OptGuard report: distinguish between "hard"
             * failures which result in immediate termination
             * (C0 violation being reported) and "soft" ones
             * (C1 violation is NOT reported) which accumulate
             * until we exhaust limit.
             */
            ae_set_error_flag(wereerrors, ogrep.nonc0suspected, __FILE__, __LINE__, "testminnlcunit.ap:4712");
            ae_set_error_flag(wereerrors, ogrep.nonc0fidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:4713");
            failed = ae_false;
            failed = failed||optguardallclear(&ogrep, _state);
            failed = failed||!ogrep.nonc1suspected;
            failed = failed||ogrep.nonc1fidx!=0;
            if( failed )
            {
                inc(&failurecounter, _state);
            }
            
            /*
             * Check C1 continuity test #0
             */
            minnlcoptguardnonc1test0results(&state, &ognonc1test0strrep, &ognonc1test0lngrep, _state);
            minnlcoptguardnonc1test1results(&state, &ognonc1test1strrep, &ognonc1test1lngrep, _state);
            if( ogrep.nonc1test0positive )
            {
                ae_set_error_flag(wereerrors, !ogrep.nonc1suspected, __FILE__, __LINE__, "testminnlcunit.ap:4728");
                ae_set_error_flag(wereerrors, !ognonc1test0strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4729");
                ae_set_error_flag(wereerrors, !ognonc1test0lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4730");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx!=0, __FILE__, __LINE__, "testminnlcunit.ap:4731");
                testminnlcunit_testoptguardc1test0reportfortask0(wereerrors, &ognonc1test0strrep, &a, n, _state);
                testminnlcunit_testoptguardc1test0reportfortask0(wereerrors, &ognonc1test0lngrep, &a, n, _state);
                avgstr0len = avgstr0len+(double)ognonc1test0strrep.cnt/(double)passcount;
                avglng0len = avglng0len+(double)ognonc1test0lngrep.cnt/(double)passcount;
            }
            else
            {
                ae_set_error_flag(wereerrors, ognonc1test0strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4739");
                ae_set_error_flag(wereerrors, ognonc1test0lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4740");
                testminnlcunit_testoptguardc1test0reportfortask0(wereerrors, &ognonc1test0strrep, &a, n, _state);
                testminnlcunit_testoptguardc1test0reportfortask0(wereerrors, &ognonc1test0lngrep, &a, n, _state);
                inc(&c1test0fails, _state);
            }
            if( ogrep.nonc1test1positive )
            {
                ae_set_error_flag(wereerrors, !ogrep.nonc1suspected, __FILE__, __LINE__, "testminnlcunit.ap:4747");
                ae_set_error_flag(wereerrors, !ognonc1test1strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4748");
                ae_set_error_flag(wereerrors, !ognonc1test1lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4749");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx!=0, __FILE__, __LINE__, "testminnlcunit.ap:4750");
                testminnlcunit_testoptguardc1test1reportfortask0(wereerrors, &ognonc1test1strrep, &a, n, _state);
                testminnlcunit_testoptguardc1test1reportfortask0(wereerrors, &ognonc1test1lngrep, &a, n, _state);
                avgstr1len = avgstr1len+(double)ognonc1test1strrep.cnt/(double)passcount;
                avglng1len = avglng1len+(double)ognonc1test1lngrep.cnt/(double)passcount;
            }
            else
            {
                ae_set_error_flag(wereerrors, ognonc1test1strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4758");
                ae_set_error_flag(wereerrors, ognonc1test1lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4759");
                testminnlcunit_testoptguardc1test1reportfortask0(wereerrors, &ognonc1test1strrep, &a, n, _state);
                testminnlcunit_testoptguardc1test1reportfortask0(wereerrors, &ognonc1test1lngrep, &a, n, _state);
                inc(&c1test1fails, _state);
            }
        }
        ae_set_error_flag(wereerrors, failurecounter>maxfails, __FILE__, __LINE__, "testminnlcunit.ap:4766");
        ae_set_error_flag(wereerrors, c1test0fails>maxc1test0fails, __FILE__, __LINE__, "testminnlcunit.ap:4767");
        ae_set_error_flag(wereerrors, c1test1fails>maxc1test1fails, __FILE__, __LINE__, "testminnlcunit.ap:4768");
        ae_set_error_flag(wereerrors, ae_fp_less_eq(avglng0len,avgstr0len), __FILE__, __LINE__, "testminnlcunit.ap:4769");
        ae_set_error_flag(wereerrors, ae_fp_less_eq(avglng1len,avgstr1len), __FILE__, __LINE__, "testminnlcunit.ap:4770");
        
        /*
         * Detection of C1 continuity violations in the target under numerical differentiation:
         * * target function is a sum of |(x,c_i)| for i=1..N.
         * * no constraints is present.
         * * analytic gradient is provided.
         *
         * OptGuard should always be able to detect violations in more than
         * 99% of runs (note: reduced strength when compared with analytic gradient);
         * it means that 100 runs should have no more than 10 failures in all cases
         * (even after multiple repeated tests; according to the binomial distribution
         * quantiles).
         *
         * We select some N and perform exhaustive search for this N.
         *
         * NOTE: we skip SQP solver for this test
         */
        diffstep = 0.0001;
        passcount = 100;
        maxfails = 10;
        n = 1+hqrnduniformi(&rs, 10, _state);
        failurecounter = 0;
        for(pass=1; pass<=passcount; pass++)
        {
            
            /*
             * Formulate problem
             */
            ae_vector_set_length(&x0, n, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
            }
            ae_vector_set_length(&s, n, _state);
            for(i=0; i<=n-1; i++)
            {
                s.ptr.p_double[i] = 0.01*ae_pow((double)(2), 0.33*hqrndnormal(&rs, _state), _state);
            }
            ae_matrix_set_length(&a, n, n, _state);
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    a.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                }
            }
            
            /*
             * Create and try to solve
             */
            minnlccreatef(n, &x0, diffstep, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 1, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 50, _state);
            minnlcoptguardsmoothness(&state, 1+hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel, _state), _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfi )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        v = (double)(0);
                        for(j=0; j<=n-1; j++)
                        {
                            v = v+state.x.ptr.p_double[j]*a.ptr.pp_double[i][j];
                        }
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+ae_fabs(v, _state);
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            minnlcoptguardresults(&state, &ogrep, _state);
            
            /*
             * Check basic properties of the solution
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4845");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4846");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Check OptGuard report: distinguish between "hard"
             * failures which result in immediate termination
             * (C0 violation being reported) and "soft" ones
             * (C1 violation is NOT reported) which accumulate
             * until we exhaust limit.
             */
            ae_set_error_flag(wereerrors, ogrep.nonc0suspected, __FILE__, __LINE__, "testminnlcunit.ap:4857");
            ae_set_error_flag(wereerrors, ogrep.nonc0fidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:4858");
            failed = ae_false;
            failed = failed||optguardallclear(&ogrep, _state);
            failed = failed||!ogrep.nonc1suspected;
            failed = failed||ogrep.nonc1fidx!=0;
            if( failed )
            {
                inc(&failurecounter, _state);
            }
        }
        ae_set_error_flag(wereerrors, failurecounter>maxfails, __FILE__, __LINE__, "testminnlcunit.ap:4866");
        
        /*
         * Detection of C1 continuity violations in the nonlinear constraints.
         *
         * This test is a bit tricky because optimizers are less sensitive to
         * continuity violations in constraints, so we may have hard time collecting
         * enough statistics. In order to do so we solve carefully designed hard
         * problem with MULTIPLE bad constraints and only one good constraint.
         *
         * Optimizer may report any of bad constraints, but not good one.
         *
         * We select some N and perform exhaustive search for this N.
         */
        passcount = 100;
        maxfails = 30;
        n = 5;
        failurecounter = 0;
        c1test0fails = 0;
        c1test1fails = 0;
        for(pass=1; pass<=passcount; pass++)
        {
            
            /*
             * Formulate problem, select constraint index to perturb with
             * nonsmoothness; make sure that this constraint is active at
             * the solution
             */
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&s, n, _state);
            ae_vector_set_length(&b, n, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = hqrnduniformr(&rs, _state)-0.5;
                s.ptr.p_double[i] = ae_pow((double)(2), hqrndnormal(&rs, _state), _state);
                b.ptr.p_double[i] = hqrndnormal(&rs, _state);
            }
            ae_matrix_set_length(&a, n, n, _state);
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    a.ptr.pp_double[i][j] = ae_pow((double)(2), 0.01*hqrndnormal(&rs, _state), _state);
                }
            }
            goodidx = hqrnduniformi(&rs, n, _state);
            
            /*
             * Create and try to solve
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 1000.0, 3, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 50, _state);
            minnlcsetnlc(&state, 0, n, _state);
            minnlcsetscale(&state, &s, _state);
            minnlcoptguardsmoothness(&state, 1+hqrnduniformi(&rs, testminnlcunit_maxoptguardlevel, _state), _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+b.ptr.p_double[i]*state.x.ptr.p_double[i];
                        state.j.ptr.pp_double[0][i] = b.ptr.p_double[i];
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        state.fi.ptr.p_double[1+i] = (double)(-1);
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[1+i] = state.fi.ptr.p_double[1+i]+a.ptr.pp_double[i][j]*ae_sqr(state.x.ptr.p_double[j], _state);
                            state.j.ptr.pp_double[1+i][j] = (double)2*a.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                        }
                        if( i!=goodidx )
                        {
                            state.fi.ptr.p_double[1+i] = ae_maxreal(state.fi.ptr.p_double[1+i], 0.0, _state);
                            for(j=0; j<=n-1; j++)
                            {
                                state.j.ptr.pp_double[1+i][j] = (double)ae_sign(state.fi.ptr.p_double[1+i], _state)*state.j.ptr.pp_double[1+i][j];
                            }
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            minnlcoptguardresults(&state, &ogrep, _state);
            
            /*
             * Check basic properties of the solution
             */
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:4962");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:4963");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
            
            /*
             * Check generic OptGuard report: distinguish between "hard"
             * failures which result in immediate termination
             * (C0 violation being reported) and "soft" ones
             * (C1 violation is NOT reported) which accumulate
             * until we exhaust limit.
             */
            ae_set_error_flag(wereerrors, ogrep.nonc0suspected, __FILE__, __LINE__, "testminnlcunit.ap:4974");
            ae_set_error_flag(wereerrors, ogrep.nonc0fidx>=0, __FILE__, __LINE__, "testminnlcunit.ap:4975");
            ae_set_error_flag(wereerrors, ogrep.nonc1fidx==goodidx+1, __FILE__, __LINE__, "testminnlcunit.ap:4976");
            failed = ae_false;
            failed = failed||optguardallclear(&ogrep, _state);
            failed = failed||!ogrep.nonc1suspected;
            if( failed )
            {
                inc(&failurecounter, _state);
            }
            
            /*
             * Check C1 continuity tests #0 and #1
             */
            minnlcoptguardnonc1test0results(&state, &ognonc1test0strrep, &ognonc1test0lngrep, _state);
            minnlcoptguardnonc1test1results(&state, &ognonc1test1strrep, &ognonc1test1lngrep, _state);
            if( ogrep.nonc1test0positive )
            {
                ae_set_error_flag(wereerrors, !ogrep.nonc1suspected, __FILE__, __LINE__, "testminnlcunit.ap:4990");
                ae_set_error_flag(wereerrors, !ognonc1test0strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4991");
                ae_set_error_flag(wereerrors, !ognonc1test0lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:4992");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx<1, __FILE__, __LINE__, "testminnlcunit.ap:4993");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx>n, __FILE__, __LINE__, "testminnlcunit.ap:4994");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx==goodidx+1, __FILE__, __LINE__, "testminnlcunit.ap:4995");
                testminnlcunit_testoptguardc1test0reportfortask1(wereerrors, &ognonc1test0strrep, &a, n, goodidx, _state);
                testminnlcunit_testoptguardc1test0reportfortask1(wereerrors, &ognonc1test0lngrep, &a, n, goodidx, _state);
            }
            else
            {
                ae_set_error_flag(wereerrors, ognonc1test0strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:5001");
                ae_set_error_flag(wereerrors, ognonc1test0lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:5002");
                testminnlcunit_testoptguardc1test0reportfortask1(wereerrors, &ognonc1test0strrep, &a, n, goodidx, _state);
                testminnlcunit_testoptguardc1test0reportfortask1(wereerrors, &ognonc1test0lngrep, &a, n, goodidx, _state);
                inc(&c1test0fails, _state);
            }
            if( ogrep.nonc1test1positive )
            {
                ae_set_error_flag(wereerrors, !ogrep.nonc1suspected, __FILE__, __LINE__, "testminnlcunit.ap:5009");
                ae_set_error_flag(wereerrors, !ognonc1test1strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:5010");
                ae_set_error_flag(wereerrors, !ognonc1test1lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:5011");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx<1, __FILE__, __LINE__, "testminnlcunit.ap:5012");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx>n, __FILE__, __LINE__, "testminnlcunit.ap:5013");
                ae_set_error_flag(wereerrors, ogrep.nonc1fidx==goodidx+1, __FILE__, __LINE__, "testminnlcunit.ap:5014");
                testminnlcunit_testoptguardc1test1reportfortask1(wereerrors, &ognonc1test1strrep, &a, n, goodidx, _state);
                testminnlcunit_testoptguardc1test1reportfortask1(wereerrors, &ognonc1test1lngrep, &a, n, goodidx, _state);
            }
            else
            {
                ae_set_error_flag(wereerrors, ognonc1test1strrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:5020");
                ae_set_error_flag(wereerrors, ognonc1test1lngrep.positive, __FILE__, __LINE__, "testminnlcunit.ap:5021");
                testminnlcunit_testoptguardc1test1reportfortask1(wereerrors, &ognonc1test1strrep, &a, n, goodidx, _state);
                testminnlcunit_testoptguardc1test1reportfortask1(wereerrors, &ognonc1test1lngrep, &a, n, goodidx, _state);
                inc(&c1test1fails, _state);
            }
        }
        ae_set_error_flag(wereerrors, failurecounter>maxfails, __FILE__, __LINE__, "testminnlcunit.ap:5027");
    }
    ae_frame_leave(_state);
}


/*************************************************************************
This function performs tests for fixed bugs

On failure sets error flag.
*************************************************************************/
static void testminnlcunit_testbugs(ae_bool* wereerrors, ae_state *_state)
{
    ae_frame _frame_block;
    hqrndstate rs;
    ae_int_t n;
    ae_int_t aulits;
    ae_int_t maxits;
    double rho;
    ae_int_t ckind;
    ae_int_t i;
    ae_int_t j;
    ae_int_t k;
    ae_int_t solvertype;
    minnlcstate state;
    minnlcreport rep;
    ae_vector x0;
    ae_vector x1;
    ae_vector x2;
    ae_vector bndl;
    ae_vector bndu;
    ae_vector d;
    ae_vector b;
    ae_vector ct;
    ae_matrix c;

    ae_frame_make(_state, &_frame_block);
    memset(&rs, 0, sizeof(rs));
    memset(&state, 0, sizeof(state));
    memset(&rep, 0, sizeof(rep));
    memset(&x0, 0, sizeof(x0));
    memset(&x1, 0, sizeof(x1));
    memset(&x2, 0, sizeof(x2));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&d, 0, sizeof(d));
    memset(&b, 0, sizeof(b));
    memset(&ct, 0, sizeof(ct));
    memset(&c, 0, sizeof(c));
    _hqrndstate_init(&rs, _state, ae_true);
    _minnlcstate_init(&state, _state, ae_true);
    _minnlcreport_init(&rep, _state, ae_true);
    ae_vector_init(&x0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x1, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&x2, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&d, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&b, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&ct, 0, DT_INT, _state, ae_true);
    ae_matrix_init(&c, 0, 0, DT_REAL, _state, ae_true);

    hqrndrandomize(&rs, _state);
    
    /*
     * Bug description (fixed): sometimes on non-convex problems, when
     * Lagrange coefficient for inequality constraint becomes small,
     * algorithm performs VERY deep step into infeasible area (step is 1E50),
     * which de-stabilizes it and prevents from converging back to feasible area.
     *
     * Very rare situation, but must be fixed with additional "convexifying" term.
     * This test reproduces situation with convexified term turned off, then
     * checks that introduction of term solves issue.
     *
     * We perform three kinds of tests:
     * * with box inequality constraint
     * * with linear inequality constraint
     * * with nonlinear inequality constraint
     *
     * In all three cases we:
     * * first time solve non-convex problem with artificially moved stabilizing
     *   point and decreased initial value of Lagrange multiplier.
     * * second time we solve problem with good stabilizing point, but zero Lagrange multiplier
     * * last time solve same problem, but with default settings
     */
    aulits = 1;
    maxits = 1;
    rho = 100.0;
    n = 1;
    ae_vector_set_length(&x0, n, _state);
    x0.ptr.p_double[0] = 0.0;
    ae_vector_set_length(&bndl, n, _state);
    ae_vector_set_length(&bndu, n, _state);
    bndl.ptr.p_double[0] = 0.0;
    bndu.ptr.p_double[0] = _state->v_posinf;
    ae_matrix_set_length(&c, 1, 2, _state);
    ae_vector_set_length(&ct, 1, _state);
    c.ptr.pp_double[0][0] = 1.0;
    c.ptr.pp_double[0][1] = 0.0;
    ct.ptr.p_int[0] = 1;
    for(ckind=0; ckind<=2; ckind++)
    {
        minnlccreate(n, &x0, &state, _state);
        state.stabilizingpoint = -1.0E300;
        state.initialinequalitymultiplier = 1.0E-12;
        minnlcsetalgoaul(&state, rho, aulits, _state);
        minnlcsetcond(&state, 0.0, maxits, _state);
        if( ckind==0 )
        {
            minnlcsetbc(&state, &bndl, &bndu, _state);
        }
        if( ckind==1 )
        {
            minnlcsetlc(&state, &c, &ct, 1, _state);
        }
        if( ckind==2 )
        {
            minnlcsetnlc(&state, 0, 1, _state);
        }
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = state.x.ptr.p_double[0]-ae_sqr(state.x.ptr.p_double[0], _state);
                state.j.ptr.pp_double[0][0] = (double)1-(double)2*state.x.ptr.p_double[0];
                if( ckind==2 )
                {
                    state.fi.ptr.p_double[1] = -state.x.ptr.p_double[0];
                    state.j.ptr.pp_double[1][0] = (double)(-1);
                }
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:5125");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_greater(x1.ptr.p_double[0],-1.0E6), __FILE__, __LINE__, "testminnlcunit.ap:5128");
        minnlccreate(n, &x0, &state, _state);
        state.stabilizingpoint = -1.0E2;
        state.initialinequalitymultiplier = 1.0E-12;
        minnlcsetalgoaul(&state, rho, aulits, _state);
        minnlcsetcond(&state, 0.0, maxits, _state);
        if( ckind==0 )
        {
            minnlcsetbc(&state, &bndl, &bndu, _state);
        }
        if( ckind==1 )
        {
            minnlcsetlc(&state, &c, &ct, 1, _state);
        }
        if( ckind==2 )
        {
            minnlcsetnlc(&state, 0, 1, _state);
        }
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = state.x.ptr.p_double[0]-ae_sqr(state.x.ptr.p_double[0], _state);
                state.j.ptr.pp_double[0][0] = (double)1-(double)2*state.x.ptr.p_double[0];
                if( ckind==2 )
                {
                    state.fi.ptr.p_double[1] = -state.x.ptr.p_double[0];
                    state.j.ptr.pp_double[1][0] = (double)(-1);
                }
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:5157");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_less(x1.ptr.p_double[0],(double)3*state.stabilizingpoint), __FILE__, __LINE__, "testminnlcunit.ap:5160");
        minnlccreate(n, &x0, &state, _state);
        minnlcsetalgoaul(&state, rho, aulits, _state);
        minnlcsetcond(&state, 0.0, maxits, _state);
        if( ckind==0 )
        {
            minnlcsetbc(&state, &bndl, &bndu, _state);
        }
        if( ckind==1 )
        {
            minnlcsetlc(&state, &c, &ct, 1, _state);
        }
        if( ckind==2 )
        {
            minnlcsetnlc(&state, 0, 1, _state);
        }
        while(minnlciteration(&state, _state))
        {
            if( state.needfij )
            {
                state.fi.ptr.p_double[0] = state.x.ptr.p_double[0]-ae_sqr(state.x.ptr.p_double[0], _state);
                state.j.ptr.pp_double[0][0] = (double)1-(double)2*state.x.ptr.p_double[0];
                if( ckind==2 )
                {
                    state.fi.ptr.p_double[1] = -state.x.ptr.p_double[0];
                    state.j.ptr.pp_double[1][0] = (double)(-1);
                }
                continue;
            }
            ae_assert(ae_false, "Assertion failed", _state);
        }
        minnlcresults(&state, &x1, &rep, _state);
        ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:5187");
        if( *wereerrors )
        {
            ae_frame_leave(_state);
            return;
        }
        ae_set_error_flag(wereerrors, ae_fp_less(x1.ptr.p_double[0],(double)3*state.stabilizingpoint), __FILE__, __LINE__, "testminnlcunit.ap:5190");
    }
    
    /*
     * This test checks report by E. Pozamantir. Relevant for SLP
     * and related methods, but we test it for all algorithms.
     *
     * Description:
     *
     * The sequential linear programming solver performs warm-start
     * at each iteration, i.e. it reuses previously found LP basis.
     * However, when some initially non-zero Jacobian entries become
     * exactly zero (possible with constraints which are nonsmooth
     * at some distance from the boundary), our warm-start strategy
     * may fail because warm-start basis becomes exactly degenerate.
     *
     * In order to test that this bug was fixed we solve carefully
     * designed noisy test problem with Jacobian entries being randomly
     * turned on and off. Simply being able to return from the solver
     * without triggering critical exception is enough.
     */
    for(solvertype=0; solvertype<=testminnlcunit_maxsolvertype; solvertype++)
    {
        for(n=6; n<=15; n++)
        {
            
            /*
             * Setup problem
             */
            ae_vector_set_length(&x0, n, _state);
            ae_vector_set_length(&d, n, _state);
            for(i=0; i<=n-1; i++)
            {
                x0.ptr.p_double[i] = hqrndnormal(&rs, _state);
                d.ptr.p_double[i] = ae_sqr(hqrndnormal(&rs, _state), _state);
            }
            k = 1+hqrnduniformi(&rs, n/3, _state);
            ae_matrix_set_length(&c, 2*k, n+1, _state);
            for(i=0; i<=2*k-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    c.ptr.pp_double[i][j] = hqrndnormal(&rs, _state);
                }
            }
            for(i=0; i<=k-1; i++)
            {
                c.ptr.pp_double[i][n] = (double)(0);
            }
            for(i=k; i<=2*k-1; i++)
            {
                c.ptr.pp_double[i][n] = 0.1+hqrnduniformr(&rs, _state);
            }
            
            /*
             * Create solver and solve problem
             */
            minnlccreate(n, &x0, &state, _state);
            if( solvertype==0 )
            {
                minnlcsetalgoaul(&state, 200.0, 20, _state);
            }
            else
            {
                if( solvertype==1 )
                {
                    minnlcsetalgoslp(&state, _state);
                }
                else
                {
                    if( solvertype==2 )
                    {
                        minnlcsetalgosqp(&state, _state);
                    }
                    else
                    {
                        ae_assert(ae_false, "Assertion failed", _state);
                    }
                }
            }
            minnlcsetcond(&state, 1.0E-7, 20, _state);
            minnlcsetnlc(&state, k, k, _state);
            while(minnlciteration(&state, _state))
            {
                if( state.needfij )
                {
                    state.fi.ptr.p_double[0] = (double)(0);
                    for(j=0; j<=n-1; j++)
                    {
                        state.fi.ptr.p_double[0] = state.fi.ptr.p_double[0]+0.5*d.ptr.p_double[j]*ae_sqr(state.x.ptr.p_double[j], _state);
                        state.j.ptr.pp_double[0][j] = d.ptr.p_double[j]*state.x.ptr.p_double[j];
                    }
                    for(i=0; i<=2*k-1; i++)
                    {
                        state.fi.ptr.p_double[1+i] = -c.ptr.pp_double[i][n];
                        for(j=0; j<=n-1; j++)
                        {
                            state.fi.ptr.p_double[1+i] = state.fi.ptr.p_double[1+i]+c.ptr.pp_double[i][j]*state.x.ptr.p_double[j];
                            state.j.ptr.pp_double[1+i][j] = (double)hqrnduniformi(&rs, 2, _state)*c.ptr.pp_double[i][j];
                        }
                    }
                    continue;
                }
                ae_assert(ae_false, "Assertion failed", _state);
            }
            minnlcresults(&state, &x1, &rep, _state);
            ae_set_error_flag(wereerrors, !isfinitevector(&x1, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:5277");
            ae_set_error_flag(wereerrors, rep.terminationtype<=0, __FILE__, __LINE__, "testminnlcunit.ap:5278");
            if( *wereerrors )
            {
                ae_frame_leave(_state);
                return;
            }
        }
    }
    ae_frame_leave(_state);
}


/*************************************************************************
This function tests report of "non-C1" test #0 for task #0
given by matrix A.

On failure sets error flag.
*************************************************************************/
static void testminnlcunit_testoptguardc1test0reportfortask0(ae_bool* err,
     const optguardnonc1test0report* rep,
     /* Real    */ const ae_matrix* a,
     ae_int_t n,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t j;
    ae_int_t k;
    double va;
    double vb;
    ae_bool hasc1discontinuities;


    if( rep->positive )
    {
        
        /*
         * Check positive report, first checks
         */
        ae_set_error_flag(err, rep->fidx!=0, __FILE__, __LINE__, "testminnlcunit.ap:5307");
        ae_set_error_flag(err, rep->n!=n, __FILE__, __LINE__, "testminnlcunit.ap:5308");
        ae_set_error_flag(err, !(0<=rep->stpidxa), __FILE__, __LINE__, "testminnlcunit.ap:5309");
        ae_set_error_flag(err, !(rep->stpidxa<rep->stpidxb), __FILE__, __LINE__, "testminnlcunit.ap:5310");
        ae_set_error_flag(err, !(rep->stpidxb<rep->cnt), __FILE__, __LINE__, "testminnlcunit.ap:5311");
        ae_set_error_flag(err, rep->x0.cnt!=rep->n, __FILE__, __LINE__, "testminnlcunit.ap:5312");
        ae_set_error_flag(err, rep->d.cnt!=rep->n, __FILE__, __LINE__, "testminnlcunit.ap:5313");
        ae_set_error_flag(err, rep->stp.cnt!=rep->cnt, __FILE__, __LINE__, "testminnlcunit.ap:5314");
        ae_set_error_flag(err, rep->f.cnt!=rep->cnt, __FILE__, __LINE__, "testminnlcunit.ap:5315");
        ae_set_error_flag(err, !isfinitevector(&rep->x0, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:5316");
        ae_set_error_flag(err, !isfinitevector(&rep->d, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:5317");
        ae_set_error_flag(err, !isfinitevector(&rep->stp, rep->cnt, _state), __FILE__, __LINE__, "testminnlcunit.ap:5318");
        ae_set_error_flag(err, !isfinitevector(&rep->f, rep->cnt, _state), __FILE__, __LINE__, "testminnlcunit.ap:5319");
        if( *err )
        {
            return;
        }
        
        /*
         * Check consistency of Stp.
         */
        for(k=0; k<=rep->cnt-2; k++)
        {
            ae_set_error_flag(err, ae_fp_greater_eq(rep->stp.ptr.p_double[k],rep->stp.ptr.p_double[k+1]), __FILE__, __LINE__, "testminnlcunit.ap:5327");
        }
        
        /*
         * Check that interval [#StpIdxA,#StpIdxB] contains at least one discontinuity
         */
        hasc1discontinuities = ae_false;
        for(i=0; i<=n-1; i++)
        {
            va = (double)(0);
            vb = (double)(0);
            for(j=0; j<=n-1; j++)
            {
                va = va+a->ptr.pp_double[i][j]*(rep->x0.ptr.p_double[j]+rep->d.ptr.p_double[j]*rep->stp.ptr.p_double[rep->stpidxa]);
                vb = vb+a->ptr.pp_double[i][j]*(rep->x0.ptr.p_double[j]+rep->d.ptr.p_double[j]*rep->stp.ptr.p_double[rep->stpidxb]);
            }
            hasc1discontinuities = hasc1discontinuities||ae_sign(va, _state)!=ae_sign(vb, _state);
        }
        ae_set_error_flag(err, !hasc1discontinuities, __FILE__, __LINE__, "testminnlcunit.ap:5344");
    }
    else
    {
        
        /*
         * Check negative report: fields must be empty
         */
        ae_set_error_flag(err, rep->stpidxa!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5351");
        ae_set_error_flag(err, rep->stpidxb!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5352");
        ae_set_error_flag(err, rep->fidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5353");
        ae_set_error_flag(err, rep->cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5354");
        ae_set_error_flag(err, rep->n!=0, __FILE__, __LINE__, "testminnlcunit.ap:5355");
        ae_set_error_flag(err, rep->x0.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5356");
        ae_set_error_flag(err, rep->d.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5357");
        ae_set_error_flag(err, rep->stp.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5358");
        ae_set_error_flag(err, rep->f.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5359");
    }
}


/*************************************************************************
This function tests report of "non-C1" test #1 for task #0
given by matrix A.

On failure sets error flag.
*************************************************************************/
static void testminnlcunit_testoptguardc1test1reportfortask0(ae_bool* err,
     const optguardnonc1test1report* rep,
     /* Real    */ const ae_matrix* a,
     ae_int_t n,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t j;
    ae_int_t k;
    double va;
    double vb;
    ae_bool tooclose;
    ae_bool hasc1discontinuities;


    if( rep->positive )
    {
        
        /*
         * Check positive report, first checks
         */
        ae_set_error_flag(err, rep->fidx!=0, __FILE__, __LINE__, "testminnlcunit.ap:5387");
        ae_set_error_flag(err, rep->vidx<0, __FILE__, __LINE__, "testminnlcunit.ap:5388");
        ae_set_error_flag(err, rep->vidx>n, __FILE__, __LINE__, "testminnlcunit.ap:5389");
        ae_set_error_flag(err, rep->n!=n, __FILE__, __LINE__, "testminnlcunit.ap:5390");
        ae_set_error_flag(err, !(0<=rep->stpidxa), __FILE__, __LINE__, "testminnlcunit.ap:5391");
        ae_set_error_flag(err, !(rep->stpidxa<rep->stpidxb), __FILE__, __LINE__, "testminnlcunit.ap:5392");
        ae_set_error_flag(err, !(rep->stpidxb<rep->cnt), __FILE__, __LINE__, "testminnlcunit.ap:5393");
        ae_set_error_flag(err, rep->x0.cnt!=rep->n, __FILE__, __LINE__, "testminnlcunit.ap:5394");
        ae_set_error_flag(err, rep->d.cnt!=rep->n, __FILE__, __LINE__, "testminnlcunit.ap:5395");
        ae_set_error_flag(err, rep->stp.cnt!=rep->cnt, __FILE__, __LINE__, "testminnlcunit.ap:5396");
        ae_set_error_flag(err, rep->g.cnt!=rep->cnt, __FILE__, __LINE__, "testminnlcunit.ap:5397");
        ae_set_error_flag(err, !isfinitevector(&rep->x0, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:5398");
        ae_set_error_flag(err, !isfinitevector(&rep->d, n, _state), __FILE__, __LINE__, "testminnlcunit.ap:5399");
        ae_set_error_flag(err, !isfinitevector(&rep->stp, rep->cnt, _state), __FILE__, __LINE__, "testminnlcunit.ap:5400");
        ae_set_error_flag(err, !isfinitevector(&rep->g, rep->cnt, _state), __FILE__, __LINE__, "testminnlcunit.ap:5401");
        if( *err )
        {
            return;
        }
        
        /*
         * Check consistency of Stp
         */
        for(k=0; k<=rep->cnt-2; k++)
        {
            ae_set_error_flag(err, ae_fp_greater_eq(rep->stp.ptr.p_double[k],rep->stp.ptr.p_double[k+1]), __FILE__, __LINE__, "testminnlcunit.ap:5409");
        }
        
        /*
         * Check that interval [#StpIdxA,#StpIdxB] contains at least one discontinuity
         */
        tooclose = ae_false;
        hasc1discontinuities = ae_false;
        for(i=0; i<=n-1; i++)
        {
            va = (double)(0);
            vb = (double)(0);
            for(j=0; j<=n-1; j++)
            {
                va = va+a->ptr.pp_double[i][j]*(rep->x0.ptr.p_double[j]+rep->d.ptr.p_double[j]*rep->stp.ptr.p_double[rep->stpidxa]);
                vb = vb+a->ptr.pp_double[i][j]*(rep->x0.ptr.p_double[j]+rep->d.ptr.p_double[j]*rep->stp.ptr.p_double[rep->stpidxb]);
            }
            tooclose = (tooclose||ae_fp_less(ae_fabs(va, _state),1.0E-8))||ae_fp_less(ae_fabs(vb, _state),1.0E-8);
            hasc1discontinuities = hasc1discontinuities||ae_sign(va, _state)!=ae_sign(vb, _state);
        }
        if( !tooclose )
        {
            ae_set_error_flag(err, !hasc1discontinuities, __FILE__, __LINE__, "testminnlcunit.ap:5429");
        }
    }
    else
    {
        
        /*
         * Check negative report: fields must be empty
         */
        ae_set_error_flag(err, rep->stpidxa!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5436");
        ae_set_error_flag(err, rep->stpidxb!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5437");
        ae_set_error_flag(err, rep->fidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5438");
        ae_set_error_flag(err, rep->vidx!=-1, __FILE__, __LINE__, "testminnlcunit.ap:5439");
        ae_set_error_flag(err, rep->cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5440");
        ae_set_error_flag(err, rep->n!=0, __FILE__, __LINE__, "testminnlcunit.ap:5441");
        ae_set_error_flag(err, rep->x0.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5442");
        ae_set_error_flag(err, rep->d.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5443");
        ae_set_error_flag(err, rep->stp.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5444");
        ae_set_error_flag(err, rep->g.cnt!=0, __FILE__, __LINE__, "testminnlcunit.ap:5445");
    }
}


