static ae_int_t testminmounit_maxsolvertype = 1;
static double testminmounit_testfuncquadraticcoeff = 0.005;
static double testminmounit_testfuncquarticcoeff = 0.005;
static double testminmounit_epsxstop = 1.0E-8;
static void testminmounit_test1obj(ae_bool* errflag, ae_state *_state);
static void testminmounit_testmobj(ae_bool* errflag, ae_state *_state);
static void testminmounit_setmosolver(minmostate* s,
     ae_int_t solvertype,
     ae_int_t frontsize,
     ae_state *_state);
static void testminmounit_getopttol(ae_int_t solvertype,
     ae_int_t difftype,
     double* quantileopttol,
     double* maxopttol,
     ae_state *_state);
static void testminmounit_setnlcalgo(minnlcstate* s, ae_state *_state);
