static void testminmounit_setnlcalgo(minnlcstate* s, ae_state *_state)
{


    minnlcsetalgosqp(s, _state);
    minnlcsetcond(s, testminmounit_epsxstop, 5000, _state);
}


/*************************************************************************
Send linear constraints of the problem to MO solver, use  random  sequence
of calls to

  -- ALGLIB --
     Copyright 04.03.2023 by Bochkanov Sergey
*************************************************************************/
static void testminmounit_randomlysendlc2mo(const multiobjectivetestfunction* problem,
     hqrndstate* rs,
     minmostate* solver,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_int_t nset;
    ae_int_t nadd;
    ae_int_t nsetsparse;
    ae_int_t nsetdense;
    ae_int_t idx;
    ae_int_t i;
    ae_int_t j;
    ae_int_t setformat;
    ae_int_t addformat;
    sparsematrix spsuba;
    ae_matrix suba;
    ae_vector subal;
    ae_vector subau;
    ae_vector rowvals;
    ae_vector sparsevals;
    ae_vector sparseidx;
    ae_int_t nnz;

    ae_frame_make(_state, &_frame_block);
    memset(&spsuba, 0, sizeof(spsuba));
    memset(&suba, 0, sizeof(suba));
    memset(&subal, 0, sizeof(subal));
    memset(&subau, 0, sizeof(subau));
    memset(&rowvals, 0, sizeof(rowvals));
    memset(&sparsevals, 0, sizeof(sparsevals));
    memset(&sparseidx, 0, sizeof(sparseidx));
    _sparsematrix_init(&spsuba, _state, ae_true);
    ae_matrix_init(&suba, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&subal, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&subau, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&rowvals, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&sparsevals, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&sparseidx, 0, DT_INT, _state, ae_true);

    nset = hqrnduniformi(rs, problem->nlinear+1, _state);
    nadd = problem->nlinear-nset;
    setformat = hqrnduniformi(rs, 3, _state);
    addformat = hqrnduniformi(rs, 3, _state);
    rallocv(problem->n, &rowvals, _state);
    rallocv(problem->n, &sparsevals, _state);
    iallocv(problem->n, &sparseidx, _state);
    
    /*
     * First, set leading NSet rows
     */
    if( setformat==0 )
    {
        
        /*
         * Set using dense format
         */
        if( nset>0 )
        {
            rallocm(nset, problem->n, &suba, _state);
            rallocv(nset, &subal, _state);
            rallocv(nset, &subau, _state);
            rcopym(nset, problem->n, &problem->densea, &suba, _state);
            rcopyv(nset, &problem->al, &subal, _state);
            rcopyv(nset, &problem->au, &subau, _state);
        }
        minmosetlc2dense(solver, &suba, &subal, &subau, nset, _state);
    }
    if( setformat==1 )
    {
        
        /*
         * Set using sparse format
         */
        if( nset>0 )
        {
            sparsecreate(nset, problem->n, 0, &spsuba, _state);
            for(i=0; i<=nset-1; i++)
            {
                for(j=0; j<=problem->n-1; j++)
                {
                    if( ae_fp_neq(problem->densea.ptr.pp_double[i][j],(double)(0)) )
                    {
                        sparseset(&spsuba, i, j, problem->densea.ptr.pp_double[i][j], _state);
                    }
                }
            }
            sparseconverttocrs(&spsuba, _state);
            rallocv(nset, &subal, _state);
            rallocv(nset, &subau, _state);
            rcopyv(nset, &problem->al, &subal, _state);
            rcopyv(nset, &problem->au, &subau, _state);
        }
        minmosetlc2(solver, &spsuba, &subal, &subau, nset, _state);
    }
    if( setformat==2 )
    {
        
        /*
         * Set using mixed sparse/dense format
         */
        nsetsparse = hqrnduniformi(rs, nset+1, _state);
        nsetdense = nset-nsetsparse;
        if( nsetsparse>0 )
        {
            sparsecreate(nsetsparse, problem->n, 0, &spsuba, _state);
            for(i=0; i<=nsetsparse-1; i++)
            {
                for(j=0; j<=problem->n-1; j++)
                {
                    if( ae_fp_neq(problem->densea.ptr.pp_double[i][j],(double)(0)) )
                    {
                        sparseset(&spsuba, i, j, problem->densea.ptr.pp_double[i][j], _state);
                    }
                }
            }
            sparseconverttocrs(&spsuba, _state);
        }
        if( nsetdense>0 )
        {
            rallocm(nsetdense, problem->n, &suba, _state);
            for(i=0; i<=nsetdense-1; i++)
            {
                for(j=0; j<=problem->n-1; j++)
                {
                    suba.ptr.pp_double[i][j] = problem->densea.ptr.pp_double[nsetsparse+i][j];
                }
            }
        }
        rallocv(nset, &subal, _state);
        rallocv(nset, &subau, _state);
        rcopyv(nset, &problem->al, &subal, _state);
        rcopyv(nset, &problem->au, &subau, _state);
        minmosetlc2mixed(solver, &spsuba, nsetsparse, &suba, nsetdense, &subal, &subau, _state);
    }
    
    /*
     * Second, add trailing NAdd rows
     */
    for(idx=nset; idx<=problem->nlinear-1; idx++)
    {
        if( addformat==0 )
        {
            
            /*
             * Add dense row
             */
            rcopyrv(problem->n, &problem->densea, idx, &rowvals, _state);
            minmoaddlc2dense(solver, &rowvals, problem->al.ptr.p_double[idx], problem->au.ptr.p_double[idx], _state);
        }
        if( addformat==1 )
        {
            
            /*
             * Add sparse row
             */
            nnz = 0;
            for(j=0; j<=problem->n-1; j++)
            {
                if( ae_fp_neq(problem->densea.ptr.pp_double[idx][j],(double)(0))||ae_fp_greater(hqrndnormal(rs, _state),(double)(0)) )
                {
                    sparsevals.ptr.p_double[nnz] = problem->densea.ptr.pp_double[idx][j];
                    sparseidx.ptr.p_int[nnz] = j;
                    nnz = nnz+1;
                }
            }
            minmoaddlc2(solver, &sparseidx, &sparsevals, nnz, problem->al.ptr.p_double[idx], problem->au.ptr.p_double[idx], _state);
        }
        if( addformat==2 )
        {
            
            /*
             * Add dense row as a sparse one
             */
            rcopyrv(problem->n, &problem->densea, idx, &rowvals, _state);
            minmoaddlc2sparsefromdense(solver, &rowvals, problem->al.ptr.p_double[idx], problem->au.ptr.p_double[idx], _state);
        }
    }
    ae_frame_leave(_state);
}


/*************************************************************************
Send linear constraints of the problem to MinNLC solver

  -- ALGLIB --
     Copyright 04.03.2023 by Bochkanov Sergey
*************************************************************************/
static void testminmounit_sendlc2nlc(const multiobjectivetestfunction* problem,
     minnlcstate* solver,
     ae_state *_state)
{
    ae_frame _frame_block;
    sparsematrix sparsedummy;
    ae_matrix olddensec;
    ae_vector olddensect;
    ae_int_t olddensek;

    ae_frame_make(_state, &_frame_block);
    memset(&sparsedummy, 0, sizeof(sparsedummy));
    memset(&olddensec, 0, sizeof(olddensec));
    memset(&olddensect, 0, sizeof(olddensect));
    _sparsematrix_init(&sparsedummy, _state, ae_true);
    ae_matrix_init(&olddensec, 0, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&olddensect, 0, DT_INT, _state, ae_true);

    converttwosidedlctoonesidedold(&sparsedummy, 0, &problem->densea, problem->nlinear, problem->n, &problem->al, &problem->au, &olddensec, &olddensect, &olddensek, _state);
    minnlcsetlc(solver, &olddensec, &olddensect, olddensek, _state);
    ae_frame_leave(_state);
}



