    waserrors = waserrors||ae_fp_neq(tailb,(double)(1));
    waserrors = waserrors||ae_fp_neq(taill,(double)(1));
    waserrors = waserrors||ae_fp_neq(tailr,(double)(1));
    studentttest1(&x, 1, 0.0, &tailb, &taill, &tailr, _state);
