    ae_set_error_flag(fiterrors, ae_fp_greater(rep.rmserror,0.02), __FILE__, __LINE__, "testlsfitunit.ap:2523");
    logisticfit5(&x, &y, 190, &a, &b, &c, &d, &g, &rep2, _state);
