                ae_vector_set_length(&testpoint, nx, _state);
                testpoint.ptr.p_double[0] = ae_randomreal(_state)*(double)(k0-1);
                testpoint.ptr.p_double[1] = ae_randomreal(_state)*(double)(k1-1);
                testpoint.ptr.p_double[2] = ae_randomreal(_state)*(double)(k2-1);
