                                memset(&_local_dynamic_block, 0, sizeof(_local_dynamic_block));
                                ae_db_init(&_local_dynamic_block, _local_ssize+1, _state, ae_true);
                                ae_serializer_sstart_str(&_local_serializer, (char*)_local_dynamic_block.ptr);
